import { Accordion as AccordionPrimitive } from "@base-ui/react/accordion";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import { RotatingChevron } from "@/registry/erbium/ui/stateful-icon";
import { Separator } from "@/registry/erbium/ui/separator";

const Accordion = ({ className, ...props }: AccordionPrimitive.Root.Props) => (
  <AccordionPrimitive.Root
    data-slot="accordion"
    className={cn("flex w-full flex-col", className)}
    {...props}
  />
);

const AccordionItem = ({ className, children, ...props }: AccordionPrimitive.Item.Props) => (
  <AccordionPrimitive.Item
    data-slot="accordion-item"
    className={cn("group/accordion-item", className)}
    {...props}
  >
    {children}
    <Separator data-slot="accordion-item-separator" className="group-last/accordion-item:hidden" />
  </AccordionPrimitive.Item>
);

const AccordionTrigger = ({ className, children, ...props }: AccordionPrimitive.Trigger.Props) => (
  <AccordionPrimitive.Header className="flex">
    <AccordionPrimitive.Trigger
      data-slot="accordion-trigger"
      className={cn(
        "group group/accordion-trigger relative flex flex-1 items-start justify-between rounded-lg border border-transparent min-h-control py-related text-start text-control-sm transition-colors outline-none hover:underline data-panel-open:rounded-b-none group-has-[[data-slot=accordion-content]:not([hidden])]/accordion-item:rounded-b-none focus-visible:border-ring focus-visible:after:border-ring **:data-[slot=accordion-trigger-icon]:ms-auto **:data-[slot=accordion-trigger-icon]:size-4 **:data-[slot=accordion-trigger-icon]:text-muted-foreground data-disabled:pointer-events-none data-disabled:opacity-50",
        className,
      )}
      {...props}
    >
      {children}
      <RotatingChevron data-slot="accordion-trigger-icon" className="pointer-events-none" />
    </AccordionPrimitive.Trigger>
  </AccordionPrimitive.Header>
);

const AccordionContent = ({ className, children, ...props }: AccordionPrimitive.Panel.Props) => (
  <AccordionPrimitive.Panel
    data-slot="accordion-content"
    className="h-(--accordion-panel-height) overflow-hidden text-caption transition-[height] duration-200 ease-in-out data-ending-style:h-0 data-starting-style:h-0 motion-reduce:transition-none"
    {...props}
  >
    <div
      className={cn(
        "pt-2.5 pb-2.5 [&_a]:underline [&_a]:underline-offset-3 [&_a]:hover:text-foreground [&_p:not(:last-child)]:mb-4",
        className,
      )}
    >
      {children}
    </div>
  </AccordionPrimitive.Panel>
);

export { Accordion, AccordionItem, AccordionTrigger, AccordionContent };

import * as React from "react";
import { Icon } from "@/registry/erbium/ui/icon";
import { cn } from "@/registry/erbium/lib/erbium-utils";

type AlertVariant = "default" | "info" | "success" | "warning" | "error";

const alertVariants: Record<AlertVariant, { className: string; icon: React.ReactNode }> = {
  default: {
    className: "surface-panel text-card-foreground",
    icon: <Icon name="info" aria-hidden="true" />,
  },
  error: {
    className: "surface-tint-error-soft text-error-soft-foreground",
    icon: <Icon name="octagon-x" className="text-error" aria-hidden="true" />,
  },
  info: {
    className: "surface-tint-info-soft text-info-soft-foreground",
    icon: <Icon name="info" className="text-info" aria-hidden="true" />,
  },
  success: {
    className: "surface-tint-success-soft text-success-soft-foreground",
    icon: <Icon name="circle-check" className="text-success" aria-hidden="true" />,
  },
  warning: {
    className: "surface-tint-warning-soft text-warning-soft-foreground",
    icon: <Icon name="triangle-alert" className="text-warning" aria-hidden="true" />,
  },
};

const Alert = ({
  className,
  variant = "default",
  children,
  ...props
}: React.ComponentProps<"div"> & { variant?: AlertVariant }) => (
  <div
    data-slot="alert"
    role="alert"
    className={cn(
      "group/alert relative grid w-full grid-cols-[auto_1fr] gap-x-2 gap-y-0.5 rounded-lg border px-2.5 py-2 text-start text-caption has-data-[slot=alert-action]:pe-18 [&>svg]:row-span-2 [&>svg]:size-4 [&>svg]:translate-y-0.5",
      alertVariants[variant].className,
      className,
    )}
    {...props}
  >
    {alertVariants[variant].icon}
    {children}
  </div>
);

const AlertTitle = ({ className, ...props }: React.ComponentProps<"div">) => (
  <div
    data-slot="alert-title"
    className={cn(
      "col-start-2 text-control [&_a]:underline [&_a]:underline-offset-3 [&_a]:hover:text-foreground",
      className,
    )}
    {...props}
  />
);

const AlertDescription = ({ className, ...props }: React.ComponentProps<"div">) => (
  <div
    data-slot="alert-description"
    className={cn(
      "col-start-2 text-caption text-balance text-muted-foreground md:text-pretty [&_a]:underline [&_a]:underline-offset-3 [&_a]:hover:text-foreground [&_p:not(:last-child)]:mb-4",
      className,
    )}
    {...props}
  />
);

const AlertAction = ({ className, ...props }: React.ComponentProps<"div">) => (
  <div data-slot="alert-action" className={cn("absolute top-2 inset-e-2", className)} {...props} />
);

export { Alert, AlertTitle, AlertDescription, AlertAction };

export type { AlertVariant };

import * as React from "react";
import { AlertDialog as AlertDialogPrimitive } from "@base-ui/react/alert-dialog";
import { ModalHotkeysScope } from "@/registry/erbium/lib/modal-hotkeys-scope";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import { Button } from "@/registry/erbium/ui/button";

const AlertDialog = ({ ...props }: AlertDialogPrimitive.Root.Props) => (
  <AlertDialogPrimitive.Root data-slot="alert-dialog" {...props} />
);

const AlertDialogTrigger = ({ ...props }: AlertDialogPrimitive.Trigger.Props) => (
  <AlertDialogPrimitive.Trigger data-slot="alert-dialog-trigger" {...props} />
);

const AlertDialogPortal = ({ ...props }: AlertDialogPrimitive.Portal.Props) => (
  <AlertDialogPrimitive.Portal data-slot="alert-dialog-portal" {...props} />
);

const AlertDialogOverlay = ({ className, ...props }: AlertDialogPrimitive.Backdrop.Props) => (
  <AlertDialogPrimitive.Backdrop
    data-slot="alert-dialog-overlay"
    className={cn(
      "fixed inset-0 isolate z-50 bg-overlay-backdrop duration-100 supports-backdrop-filter:backdrop-blur-(--overlay-backdrop-blur,2px) data-open:animate-in data-open:fade-in-0 data-closed:animate-out data-closed:fade-out-0",
      className,
    )}
    {...props}
  />
);

const AlertDialogViewport = ({ className, ...props }: AlertDialogPrimitive.Viewport.Props) => (
  <AlertDialogPrimitive.Viewport
    data-slot="alert-dialog-viewport"
    className={cn(
      "fixed inset-0 z-50 grid grid-rows-[1fr_auto_3fr] justify-items-center p-4",
      className,
    )}
    {...props}
  />
);

const AlertDialogContent = ({
  className,
  size = "default",
  children,
  ...props
}: AlertDialogPrimitive.Popup.Props & {
  size?: "default" | "sm";
}) => (
  <AlertDialogPortal>
    <AlertDialogOverlay />
    <AlertDialogViewport>
      <AlertDialogPrimitive.Popup
        data-slot="alert-dialog-content"
        data-size={size}
        className={cn(
          "group/alert-dialog-content relative row-start-2 grid max-h-[calc(100dvh-2rem)] w-full gap-group overflow-hidden rounded-xl surface-modal separator-inset p-panel text-popover-foreground duration-100 outline-none data-[size=default]:max-w-xs data-[size=sm]:max-w-xs data-[size=default]:sm:max-w-sm data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-95",
          className,
        )}
        {...props}
      >
        <ModalHotkeysScope>{children}</ModalHotkeysScope>
      </AlertDialogPrimitive.Popup>
    </AlertDialogViewport>
  </AlertDialogPortal>
);

const AlertDialogHeader = ({ className, ...props }: React.ComponentProps<"div">) => (
  <div
    data-slot="alert-dialog-header"
    className={cn(
      "grid grid-rows-[auto_1fr] place-items-center gap-1.5 text-center has-data-[slot=alert-dialog-media]:grid-rows-[auto_auto_1fr] has-data-[slot=alert-dialog-media]:gap-x-4 sm:group-data-[size=default]/alert-dialog-content:place-items-start sm:group-data-[size=default]/alert-dialog-content:text-start sm:group-data-[size=default]/alert-dialog-content:has-data-[slot=alert-dialog-media]:grid-rows-[auto_1fr]",
      className,
    )}
    {...props}
  />
);

const AlertDialogFooter = ({ className, ...props }: React.ComponentProps<"div">) => (
  <div
    data-slot="alert-dialog-footer"
    className={cn(
      "-mx-(--panel-padding) -mb-(--panel-padding) flex flex-col-reverse gap-related surface-footer p-panel group-data-[size=sm]/alert-dialog-content:grid group-data-[size=sm]/alert-dialog-content:grid-cols-2 sm:flex-row sm:justify-end",
      className,
    )}
    {...props}
  />
);

const AlertDialogMedia = ({ className, ...props }: React.ComponentProps<"div">) => (
  <div
    data-slot="alert-dialog-media"
    className={cn(
      "mb-2 inline-flex size-10 items-center justify-center rounded-md bg-muted sm:group-data-[size=default]/alert-dialog-content:row-span-2 *:[svg:not([class*='size-'])]:size-6",
      className,
    )}
    {...props}
  />
);

const AlertDialogTitle = ({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Title>) => (
  <AlertDialogPrimitive.Title
    data-slot="alert-dialog-title"
    className={cn(
      "text-subtitle sm:group-data-[size=default]/alert-dialog-content:group-has-data-[slot=alert-dialog-media]/alert-dialog-content:col-start-2",
      className,
    )}
    {...props}
  />
);

const AlertDialogDescription = ({
  className,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Description>) => (
  <AlertDialogPrimitive.Description
    data-slot="alert-dialog-description"
    className={cn(
      "text-caption text-muted-foreground *:[a]:underline *:[a]:underline-offset-3 *:[a]:hover:text-foreground",
      className,
    )}
    {...props}
  />
);

const AlertDialogAction = ({ className, ...props }: React.ComponentProps<typeof Button>) => (
  <Button data-slot="alert-dialog-action" className={cn(className)} {...props} />
);

const AlertDialogCancel = ({
  className,
  variant = "outline",
  size = "default",
  ...props
}: AlertDialogPrimitive.Close.Props &
  Pick<React.ComponentProps<typeof Button>, "variant" | "size">) => (
  <AlertDialogPrimitive.Close
    data-slot="alert-dialog-cancel"
    className={cn(className)}
    render={<Button variant={variant} size={size} />}
    {...props}
  />
);

export {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogMedia,
  AlertDialogOverlay,
  AlertDialogPortal,
  AlertDialogTitle,
  AlertDialogTrigger,
};

/*
 * Eases an element's height when its content changes it, as the skeleton engine eases a container
 * when content replaces its skeleton: read the height the content had, let the change land, then
 * animate from the old height to the new one while clipping what has not been revealed yet. An
 * interrupted change starts from wherever the running one has got to, so nothing jumps.
 *
 * It is a ref callback, so it needs no hook: `ref={animateHeight}`, or merge it with other refs.
 * Only DOM changes inside the element animate; a resize of the viewport or a font loading does not.
 */

const duration = 200;
const easing = "cubic-bezier(0.2, 0, 0, 1)";

// Clip vertically only, so a shaking control is not cut at the sides, with room for the invalid
// halo and focus ring above and below the control.
const clip = {
  boxSizing: "border-box",
  overflowClipMargin: "4px",
  overflowX: "visible",
  overflowY: "clip",
};

const watchHeight = (element: HTMLElement) => {
  const height = () => element.getBoundingClientRect().height;
  let settled = height();
  let running: Animation | null = null;

  // Remembers the height content settles at, so the next change knows where it started.
  const resize = new ResizeObserver(() => {
    if (!running) {
      settled = height();
    }
  });

  // DOM changes are delivered after the change lands but before it is painted.
  const mutations = new MutationObserver(() => {
    const from = running ? height() : settled;
    running?.cancel();
    running = null;

    const to = height();
    settled = to;

    // A field shown or hidden as a whole appears at once, like any other element.
    if (
      Math.abs(to - from) < 0.5 ||
      from === 0 ||
      to === 0 ||
      window.matchMedia?.("(prefers-reduced-motion: reduce)").matches
    ) {
      return;
    }

    const animation = element.animate(
      [
        { ...clip, height: `${from}px` },
        { ...clip, height: `${to}px` },
      ],
      { duration, easing },
    );

    running = animation;
    animation.addEventListener("finish", () => {
      if (running === animation) {
        running = null;
        settled = height();
      }
    });
  });

  resize.observe(element);
  mutations.observe(element, {
    attributes: true,
    characterData: true,
    childList: true,
    subtree: true,
  });

  return () => {
    resize.disconnect();
    mutations.disconnect();
    running?.cancel();
  };
};

interface Watcher {
  stop: () => void;
  users: number;
}

const watchers = new WeakMap<HTMLElement, Watcher>();

const attach = (element: HTMLElement) => {
  let watcher = watchers.get(element);

  if (!watcher) {
    watcher = { stop: watchHeight(element), users: 0 };
    watchers.set(element, watcher);
  }

  const current = watcher;
  current.users += 1;

  return () => {
    current.users -= 1;

    // Components that merge refs can detach and attach this again in the commit that changed the
    // content. Stopping after that commit's changes are delivered keeps one watcher, which still
    // knows the height from before them, so the change animates.
    queueMicrotask(() => {
      if (current.users === 0 && watchers.get(element) === current) {
        current.stop();
        watchers.delete(element);
      }
    });
  };
};

const animateHeight = (element: HTMLElement | null) => (element ? attach(element) : undefined);

export { animateHeight };

import * as React from "react";
import { useMatches, useRouter } from "@tanstack/react-router";
import type {
  AnyRouteMatch,
  AnyRouter,
  LinkComponentProps,
  RegisteredRouter,
} from "@tanstack/react-router";
import { Breadcrumb } from "@/registry/erbium/ui/breadcrumb";
import { DrawerIndent, DrawerProvider } from "@/registry/erbium/ui/drawer";
import type { BreadcrumbDestination } from "@/registry/erbium/ui/breadcrumb";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarInset,
  SidebarMenu,
  SidebarMenuBadge,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
  SidebarRail,
  SidebarTrigger,
  useSidebar,
} from "@/registry/erbium/ui/sidebar";
import type { SidebarMenuButtonProps } from "@/registry/erbium/ui/sidebar";
import { Toaster } from "@/registry/erbium/ui/toast";
import { useRouterPending } from "@/registry/erbium/hooks/use-router-pending";
import { Option, Schema } from "effect";
import { cn } from "@/registry/erbium/lib/erbium-utils";

/*
 * Routes describe their own header. `crumb` names the route in the breadcrumb trail and the
 * title; a route named by its data returns `crumb` from its loader instead. `actions` is a
 * component the header renders while the route is the deepest one with actions.
 */
declare module "@tanstack/react-router" {
  interface StaticDataRouteOption {
    crumb?: string;
    actions?: React.ComponentType;
  }
}

// A loader names its route by returning `{ crumb }` alongside its data.
const decodeLoaderCrumb = Schema.decodeUnknownOption(Schema.Struct({ crumb: Schema.String }));

const crumbOf = (match: AnyRouteMatch) =>
  Option.match(decodeLoaderCrumb(match.loaderData), {
    onNone: () => match.staticData.crumb,
    onSome: ({ crumb }) => crumb,
  });

/**
 * `resizable`: the sidebar collapses offcanvas and resizes from its edge; open state and width
 * are remembered. `fixed`: the sidebar is always open on desktop and cannot be resized, as on
 * a documentation site. Both use a drawer on mobile.
 */
type AppShellSidebarMode = "resizable" | "fixed";

/**
 * What scrolls. `content`: the shell fills the viewport and only `AppShellContent` scrolls, so
 * the header stays in place, as in an application. `page`: the document scrolls and the surface
 * grows with its content beside the fixed sidebar, as on a documentation site. The browser then
 * owns scrolling: scroll restoration, anchors, find in page, and the mobile toolbar that
 * collapses as the page scrolls.
 */
type AppShellScrollMode = "content" | "page";

const AppShellContext = React.createContext<{
  sidebar: AppShellSidebarMode;
  scroll: AppShellScrollMode;
}>({
  sidebar: "resizable",
  scroll: "content",
});

// True inside an AppShell, so a nested shell (a preview inside a documentation page) leaves the
// indent and the toaster to the outer one.
const AppShellFrameContext = React.createContext(false);

const StoredSidebarState = Schema.Struct({
  open: Schema.Boolean,
  width: Schema.optionalKey(Schema.Finite),
});

type SidebarState = typeof StoredSidebarState.Type;

const decodeSidebarState = Schema.decodeUnknownOption(Schema.fromJsonString(StoredSidebarState));

const defaultSidebarState: SidebarState = { open: true };

// Storage can be unavailable (private windows, blocked site data) or hold an older format; the
// shell then starts from its defaults.
const readSidebarState = (storageKey: string): SidebarState => {
  let stored: string | null = null;

  try {
    stored = localStorage.getItem(storageKey);
  } catch {
    // Unreadable storage is an expected condition, not a fault: the defaults apply.
  }

  return Option.getOrElse(decodeSidebarState(stored), () => defaultSidebarState);
};

const writeSidebarState = (storageKey: string, state: SidebarState) => {
  try {
    localStorage.setItem(storageKey, JSON.stringify(state));
  } catch {
    // Without writable storage the state lasts for this visit only, which is the fallback.
  }
};

const keepOpen = () => {
  // A fixed sidebar ignores requests to collapse; the mobile drawer has its own state.
};

/* Closes the mobile drawer once a navigation lands on a new path, so links need no handler. */
const CloseDrawerOnNavigation = () => {
  const router = useRouter();
  const { setOpenMobile } = useSidebar();

  React.useEffect(
    () =>
      router.subscribe("onResolved", (event) => {
        if (event.pathChanged) {
          setOpenMobile(false);
        }
      }),
    [router, setOpenMobile],
  );

  return null;
};

type AppShellProps = Omit<
  React.ComponentProps<typeof SidebarProvider>,
  "defaultOpen" | "open" | "onOpenChange" | "defaultWidth" | "width" | "onWidthChange"
> & {
  sidebar?: AppShellSidebarMode;
  scroll?: AppShellScrollMode;
  /** Where a resizable sidebar remembers its open state and width. `null` remembers nothing. */
  storageKey?: string | null;
};

/**
 * The persistent frame of an application: sidebar, header, and a content surface. Render it
 * once in a layout route around `<Outlet />`, so navigating replaces only the content. It also
 * mounts the app-wide parts an app needs once: a `DrawerProvider` with a `DrawerIndent` around
 * the frame, so open drawers inset the page, and a `Toaster` for `toast.add`.
 */
const AppShell = ({
  sidebar = "resizable",
  scroll = "content",
  storageKey = "app-shell",
  className,
  children,
  ...props
}: AppShellProps) => {
  const [state, setState] = React.useState(() =>
    storageKey === null ? defaultSidebarState : readSidebarState(storageKey),
  );

  const update = (next: SidebarState) => {
    setState(next);

    if (storageKey !== null) {
      writeSidebarState(storageKey, next);
    }
  };

  const context = React.useMemo(() => ({ sidebar, scroll }), [sidebar, scroll]);
  const fixed = sidebar === "fixed";
  const nested = React.use(AppShellFrameContext);

  const frame = (
    <AppShellContext value={context}>
      <SidebarProvider
        data-slot="app-shell"
        data-sidebar-mode={sidebar}
        data-scroll={scroll}
        open={fixed || state.open}
        onOpenChange={
          fixed
            ? keepOpen
            : (open) => {
                update({ ...state, open });
              }
        }
        width={fixed ? undefined : state.width}
        onWidthChange={(width) => {
          update({ ...state, width });
        }}
        className={cn(
          "[--app-shell-header-height:--spacing(12)]",
          scroll === "content" && "h-svh min-h-0 overflow-hidden",
          className,
        )}
        {...props}
      >
        <CloseDrawerOnNavigation />
        {children}
      </SidebarProvider>
    </AppShellContext>
  );

  if (nested) {
    return frame;
  }

  return (
    <AppShellFrameContext value={true}>
      <DrawerProvider>
        <DrawerIndent>{frame}</DrawerIndent>
        <Toaster />
      </DrawerProvider>
    </AppShellFrameContext>
  );
};

const AppShellSidebar = ({
  className,
  children,
  ...props
}: Omit<React.ComponentProps<typeof Sidebar>, "variant" | "collapsible">) => {
  const { sidebar } = React.use(AppShellContext);

  return (
    <Sidebar
      data-slot="app-shell-sidebar"
      variant="inset"
      collapsible="offcanvas"
      // While the drawer indent contains the fixed sidebar, it stays at the top of the screen.
      className={cn("top-(--drawer-indent-top,0px)", className)}
      {...props}
    >
      {children}
      {sidebar === "resizable" && <SidebarRail />}
    </Sidebar>
  );
};

const AppShellSidebarHeader = (props: React.ComponentProps<typeof SidebarHeader>) => (
  <SidebarHeader data-slot="app-shell-sidebar-header" {...props} />
);

const AppShellSidebarFooter = (props: React.ComponentProps<typeof SidebarFooter>) => (
  <SidebarFooter data-slot="app-shell-sidebar-footer" {...props} />
);

/*
 * Scrolls the current page's row into view when the shell mounts and after each navigation,
 * so a long navigation never hides where the reader is. Router links mark that row with
 * `aria-current="page"`; the frame waits for the links to render the new location.
 */
const useRevealCurrentRow = (nav: React.RefObject<HTMLElement | null>) => {
  const router = useRouter();

  React.useEffect(() => {
    let frame = 0;

    const reveal = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => {
        nav.current?.querySelector('[aria-current="page"]')?.scrollIntoView({ block: "nearest" });
      });
    };

    reveal();
    const unsubscribe = router.subscribe("onResolved", reveal);

    return () => {
      unsubscribe();
      cancelAnimationFrame(frame);
    };
  }, [nav, router]);
};

/**
 * The scrolling navigation landmark between the sidebar's header and footer. It keeps the
 * current page's row in view.
 */
const AppShellNav = ({
  label,
  className,
  children,
  ...props
}: Omit<React.ComponentProps<"nav">, "ref"> & { label: string }) => {
  const nav = React.useRef<HTMLElement>(null);
  useRevealCurrentRow(nav);

  return (
    <SidebarContent>
      <nav
        ref={nav}
        data-slot="app-shell-nav"
        aria-label={label}
        className={cn("flex flex-col", className)}
        {...props}
      >
        {children}
      </nav>
    </SidebarContent>
  );
};

/** A labelled group of navigation rows. */
const AppShellNavSection = ({
  label,
  className,
  children,
  ...props
}: Omit<React.ComponentProps<"div">, "role"> & { label?: string }) => {
  const labelId = React.useId();

  return (
    <SidebarGroup
      data-slot="app-shell-nav-section"
      role={label === undefined ? undefined : "group"}
      aria-labelledby={label === undefined ? undefined : labelId}
      className={className}
      {...props}
    >
      {label !== undefined && <SidebarGroupLabel id={labelId}>{label}</SidebarGroupLabel>}
      <SidebarMenu>{children}</SidebarMenu>
    </SidebarGroup>
  );
};

interface AppShellNavRowProps {
  label: string;
  icon?: React.ReactNode;
  /** Passive metadata such as a count. Not interactive. */
  badge?: React.ReactNode;
}

/**
 * A navigation row. Takes Router's link options (`to`, `params`, `search`, `activeOptions`),
 * so destinations stay typed, preload ahead of the click, and mark themselves active.
 */
function AppShellNavLink<
  TRouter extends AnyRouter = RegisteredRouter,
  const TFrom extends string = string,
  const TTo extends string | undefined = undefined,
  const TMaskFrom extends string = TFrom,
  const TMaskTo extends string = "",
>(
  // An intersection rather than `Omit`, which would resolve Router's conditional types early
  // and stop `to` inferring from the value, so destinations built from data would not type.
  props: LinkComponentProps<"a", TRouter, TFrom, TTo, TMaskFrom, TMaskTo> &
    AppShellNavRowProps & { children?: never },
): React.ReactElement;

// The implementation accepts the options of any link; the overload restores the generics.
function AppShellNavLink({
  label,
  icon,
  badge,
  className,
  ...linkProps
}: Omit<LinkComponentProps<"a", RegisteredRouter, string, string>, "children"> &
  AppShellNavRowProps) {
  return (
    <SidebarMenuItem data-slot="app-shell-nav-link">
      <SidebarMenuButton {...linkProps} className={className}>
        {icon}
        <span>{label}</span>
      </SidebarMenuButton>
      {badge !== undefined && <SidebarMenuBadge>{badge}</SidebarMenuBadge>}
    </SidebarMenuItem>
  );
}

/** A row that runs an action instead of navigating, such as creating a project. */
const AppShellNavAction = ({
  label,
  icon,
  badge,
  ...props
}: Omit<Extract<SidebarMenuButtonProps, { href?: never }>, "children" | "render"> &
  AppShellNavRowProps) => (
  <SidebarMenuItem data-slot="app-shell-nav-action">
    <SidebarMenuButton type="button" {...props}>
      {icon}
      <span>{label}</span>
    </SidebarMenuButton>
    {badge !== undefined && <SidebarMenuBadge>{badge}</SidebarMenuBadge>}
  </SidebarMenuItem>
);

/**
 * The raised surface beside the sidebar that holds the header and the routed content. On
 * desktop it is a `surface-panel` above the sidebar's canvas; on mobile, where the sidebar is
 * a drawer, it fills the screen with the same panel face, so content reads on one colour.
 * `overflow-clip` rounds its content without making it a scroll container, so sticky content
 * inside a page-scrolling shell sticks to the viewport.
 */
const AppShellSurface = ({ className, ...props }: React.ComponentProps<typeof SidebarInset>) => (
  <SidebarInset
    data-slot="app-shell-surface"
    className={cn("min-h-0 min-w-0 overflow-clip bg-surface-panel", className)}
    {...props}
  />
);

/* A thin bar along the header's bottom edge while a navigation resolves. The fade-in waits a
   moment, so navigations that resolve quickly never show it. */
const AppShellPendingBar = () => {
  const pending = useRouterPending();

  return (
    <div
      aria-hidden="true"
      data-pending={pending ? "" : undefined}
      className="pointer-events-none absolute inset-x-0 bottom-0 h-0.5 bg-primary opacity-0 transition-opacity duration-300 data-pending:animate-pulse data-pending:opacity-100 data-pending:delay-150"
    />
  );
};

/**
 * The sidebar toggle. A fixed sidebar never collapses on desktop, so its trigger shows only
 * on mobile, where it opens the drawer. `AppShellHeader` renders one; a shell without a header
 * places this wherever its mobile layout needs it.
 */
const AppShellTrigger = ({ className, ...props }: React.ComponentProps<typeof SidebarTrigger>) => {
  const { sidebar } = React.use(AppShellContext);

  return (
    <SidebarTrigger
      data-slot="app-shell-trigger"
      className={cn(sidebar === "fixed" && "md:hidden", className)}
      {...props}
    />
  );
};

/**
 * The optional header at the top of the surface. It holds the sidebar trigger and the
 * navigation progress bar; compose a breadcrumb trail or a title, and the actions, inside it.
 * Leave it out for a surface that is all content, and render `AppShellTrigger` instead. When
 * the page scrolls, the header sticks to the top of the viewport.
 */
const AppShellHeader = ({ className, children, ...props }: React.ComponentProps<"header">) => {
  const { scroll } = React.use(AppShellContext);

  return (
    <header
      data-slot="app-shell-header"
      className={cn(
        "relative flex h-(--app-shell-header-height) shrink-0 items-center gap-related carve-bottom px-3",
        scroll === "page" && "sticky top-0 z-10 bg-surface-panel",
        className,
      )}
      {...props}
    >
      <AppShellTrigger className="-ms-1" />
      {children}
      <AppShellPendingBar />
    </header>
  );
};

interface Crumb {
  id: string;
  label: string;
  pathname: string;
}

const trimTrailingSlash = (pathname: string) =>
  pathname.length > 1 && pathname.endsWith("/") ? pathname.slice(0, -1) : pathname;

/** The active route trail: each match's loader `crumb`, or else its `staticData.crumb`. */
const useAppShellCrumbs = (): readonly Crumb[] => {
  const matches = useMatches();

  return React.useMemo(() => {
    const crumbs: Crumb[] = [];

    for (const match of matches) {
      const label = crumbOf(match);

      if (label !== undefined && label !== "") {
        const pathname = trimTrailingSlash(match.pathname);
        const previous = crumbs.at(-1);

        // A layout and its index route share a path; the deeper route names it.
        if (previous?.pathname === pathname) {
          crumbs.pop();
        }

        crumbs.push({ id: match.id, label, pathname });
      }
    }

    return crumbs;
  }, [matches]);
};

/** The route trail as breadcrumbs: ancestors link back, the current route is the page. */
const AppShellBreadcrumbs = ({
  className,
  ...props
}: Omit<React.ComponentProps<typeof Breadcrumb>, "items" | "currentPage" | "children">) => {
  const crumbs = useAppShellCrumbs();

  const items = React.useMemo(
    () =>
      crumbs.slice(0, -1).map((crumb): BreadcrumbDestination => ({
        id: crumb.id,
        label: crumb.label,
        // The matched path is already resolved, so its params are filled in.
        to: crumb.pathname,
      })),
    [crumbs],
  );

  const current = crumbs.at(-1);

  if (current === undefined) {
    return null;
  }

  return (
    <Breadcrumb
      data-slot="app-shell-breadcrumbs"
      items={items}
      currentPage={current.label}
      className={cn("min-w-0 flex-1", className)}
      {...props}
    />
  );
};

/** The current route's crumb as the page heading. */
const AppShellTitle = ({ className, ...props }: Omit<React.ComponentProps<"h1">, "children">) => {
  const current = useAppShellCrumbs().at(-1);

  if (current === undefined) {
    return null;
  }

  return (
    <h1
      data-slot="app-shell-title"
      className={cn("min-w-0 flex-1 truncate text-control", className)}
      {...props}
    >
      {current.label}
    </h1>
  );
};

/**
 * The header's trailing controls: the deepest route's `staticData.actions`, then `children`
 * for actions every route shares.
 */
const AppShellActions = ({ className, children, ...props }: React.ComponentProps<"div">) => {
  const matches = useMatches();
  const match = matches.findLast((candidate) => candidate.staticData.actions !== undefined);
  const RouteActions = match?.staticData.actions;

  return (
    <div
      data-slot="app-shell-actions"
      className={cn("ms-auto flex shrink-0 items-center gap-related", className)}
      {...props}
    >
      {RouteActions !== undefined && match !== undefined && <RouteActions key={match.id} />}
      {children}
    </div>
  );
};

/**
 * The region for routed content. In a content-scrolling shell it is the scroll container:
 * Router restores its scroll position per entry when the router enables `scrollRestoration`,
 * and listing `[data-slot="app-shell-content"]` in the router's `scrollToTopSelectors` starts a
 * new page at the top. In a page-scrolling shell the window scrolls and Router handles it
 * without either. The region is `aria-busy` while a navigation resolves, since the previous
 * page stays on screen until the next one is ready.
 */
const AppShellContent = ({ className, ...props }: React.ComponentProps<"div">) => {
  const { scroll } = React.use(AppShellContext);
  const pending = useRouterPending();
  const scrolls = scroll === "content";

  return (
    <div
      data-slot="app-shell-content"
      data-scroll-restoration-id={scrolls ? "app-shell-content" : undefined}
      aria-busy={pending || undefined}
      className={cn(
        "relative flex-1",
        scrolls && "min-h-0 overflow-y-auto overscroll-contain",
        className,
      )}
      {...props}
    />
  );
};

export {
  AppShell,
  AppShellActions,
  AppShellBreadcrumbs,
  AppShellContent,
  AppShellHeader,
  AppShellNav,
  AppShellNavAction,
  AppShellNavLink,
  AppShellNavSection,
  AppShellSidebar,
  AppShellSidebarFooter,
  AppShellSidebarHeader,
  AppShellSurface,
  AppShellTitle,
  AppShellTrigger,
  useAppShellCrumbs,
};

export type { AppShellProps, AppShellScrollMode, AppShellSidebarMode };

import * as React from "react";
import { areaY, defineChart, lineY, stack } from "@tanstack/charts";
import type { ChartGradient, ChartValue } from "@tanstack/charts";
import { scaleLinear } from "@tanstack/charts/scales/linear";
import {
  Chart,
  ChartLegend,
  ChartRoot,
  chartColorScale,
  chartCurves,
  chartIndexScale,
  chartTheme,
  chartValueTooltip,
  foldChartSeries,
  formatChartNumber,
  useChartSeries,
} from "@/registry/erbium/charts/chart";
import type {
  ChartCurve,
  ChartDatum,
  ChartFrameProps,
  ChartIndexType,
  ChartRow,
  ChartSeries,
} from "@/registry/erbium/charts/chart";

type AreaChartProps<
  TIndex extends string,
  TKey extends string,
  TDatum extends ChartDatum<TIndex, TKey>,
> = ChartFrameProps & {
  /** One row per x value, with one numeric field per series. */
  data: readonly TDatum[];
  /** The field on the x axis, such as `"month"` or `"date"`. */
  index: TIndex;
  /** How the x field reads: categories, numbers, or UTC dates. Defaults to `category`. */
  indexType?: ChartIndexType;
  /** The numeric fields to draw, in order. */
  series: readonly ChartSeries<TKey>[];
  /** Stacks the series so the top edge is their total. */
  stacked?: boolean;
  /** Defaults to `smooth`. */
  curve?: ChartCurve;
  /** `gradient` fades the fill toward the baseline; `solid` fills it evenly. Defaults to `gradient`. */
  fill?: "gradient" | "solid";
  /** Shows gridlines along the value axis. Defaults to on. */
  grid?: boolean;
  /** Shows the axes. Defaults to on. */
  axis?: boolean;
  /** Formats x-axis labels and the tooltip heading. */
  indexFormat?: (value: ChartValue) => string;
};

/** TanStack Charts scopes resource ids to each chart, so a fixed prefix cannot collide. */
const gradientPrefix = "erbium-area";

/** Shows a trend over a range where volume matters, with a fill under each line. */
const AreaChart = <
  const TIndex extends string,
  const TKey extends string,
  TDatum extends ChartDatum<TIndex, TKey>,
>({
  data,
  index,
  indexType = "category",
  series,
  stacked = false,
  curve = "smooth",
  fill = "gradient",
  grid = true,
  axis = true,
  indexFormat,
  ariaLabel,
  height = 240,
  initialWidth,
  className,
  legend,
  tooltip = true,
  format,
  locale,
  emptyMessage,
  hiddenSeries,
  defaultHiddenSeries,
  onHiddenSeriesChange,
}: AreaChartProps<TIndex, TKey, TDatum>) => {
  const { all, hidden, toggle, visible } = useChartSeries(series, {
    defaultHiddenSeries,
    hiddenSeries,
    onHiddenSeriesChange,
  });

  const showLegend = legend ?? series.length > 1;

  const definition = React.useMemo(() => {
    const rows = foldChartSeries(data, index, visible);
    const seriesPosition = new Map(all.map((item, position) => [item.label, position]));

    const gradients: ChartGradient[] = all.map((item, position) => ({
      id: `${gradientPrefix}-${position}`,
      stops: [
        { color: item.color, offset: 0, opacity: 0.02 },
        { color: item.color, offset: 1, opacity: stacked ? 0.5 : 0.32 },
      ],
      x1: 0,
      x2: 0,
      y1: 1,
      y2: 0,
    }));

    const gradientFill = (row: ChartRow<TDatum>) =>
      `url(#${gradientPrefix}-${seriesPosition.get(row.series) ?? 0})`;

    return defineChart({
      color: { scale: chartColorScale(all) },
      focus: "group-x",
      gradients,
      marks: [
        // Without explicit endpoints, areaY stacks its series, so unstacked areas
        // span from zero to their own value.
        stacked
          ? areaY(rows, {
              color: "series",
              curve: chartCurves[curve],
              fill: fill === "gradient" ? gradientFill : undefined,
              fillOpacity: fill === "gradient" ? 1 : 0.24,
              layout: stack(),
              x: "index",
              y: "value",
              z: "series",
            })
          : areaY(rows, {
              color: "series",
              curve: chartCurves[curve],
              fill: fill === "gradient" ? gradientFill : undefined,
              fillOpacity: fill === "gradient" ? 1 : 0.24,
              x: "index",
              y1: 0,
              y2: "value",
              z: "series",
            }),
        // A stacked area's top edges come from the stack, so only unstacked areas get a line.
        ...(stacked
          ? []
          : [
              lineY(rows, {
                color: "series",
                curve: chartCurves[curve],
                strokeWidth: 2,
                x: "index",
                y: "value",
                z: "series",
              }),
            ]),
      ],
      scales: {
        x: {
          axis: axis ? { ticks: { format: indexFormat } } : false,
          scale: chartIndexScale(indexType),
        },
        y: {
          axis: axis
            ? { ticks: { format: (value: number) => formatChartNumber(value, format) } }
            : false,
          grid,
          nice: true,
          scale: scaleLinear,
        },
      },
      theme: chartTheme,
      tooltip: tooltip ? chartValueTooltip({ format, indexFormat, locale }) : false,
    });
  }, [
    all,
    axis,
    curve,
    data,
    fill,
    format,
    grid,
    index,
    indexFormat,
    indexType,
    locale,
    stacked,
    tooltip,
    visible,
  ]);

  return (
    <ChartRoot
      ariaLabel={ariaLabel}
      className={className}
      empty={data.length === 0}
      emptyMessage={emptyMessage}
      height={height}
      legend={
        showLegend ? (
          <ChartLegend series={all} hiddenSeries={hidden} onToggleSeries={toggle} />
        ) : null
      }
    >
      <Chart
        ariaLabel={ariaLabel}
        definition={definition}
        height={height}
        initialWidth={initialWidth}
      />
    </ChartRoot>
  );
};

export { AreaChart };

export type { AreaChartProps };

