  CarouselSlideProps,
  CarouselState,
  CarouselValueChangeDetails,
};

import * as React from "react";
import type { Menu as MenuPrimitive } from "@base-ui/react/menu";
import {
  Cascader as CascaderPrimitive,
  createCascaderIndex,
  useCascader,
} from "@erbium-ui/react/cascader";
import type {
  CascaderIndex,
  CascaderMatch,
  CascaderNode as CascaderPrimitiveNode,
  CascaderRow,
  CascaderValueChangeDetails,
} from "@erbium-ui/react/cascader";
import { focusSearchInput } from "@/registry/erbium/lib/focus-search-input";
import {
  menuChoiceIndicatorClassName,
  menuChoiceItemClassName,
  menuEmptyClassName,
  menuItemClassName,
  menuLabelClassName,
  menuListClassName,
  menuPopupClassName,
  menuPositionerClassName,
} from "@/registry/erbium/lib/menu-styles";
import { skeletonBlock } from "@/registry/erbium/lib/skeleton-hints";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import { Button } from "@/registry/erbium/ui/button";
import { Icon } from "@/registry/erbium/ui/icon";
import { MenuScroll } from "@/registry/erbium/ui/menu-search";
import { Separator } from "@/registry/erbium/ui/separator";
import { CheckboxStateIcon, RotatingChevron } from "@/registry/erbium/ui/stateful-icon";

/*
 * Erbium's cascader: the @erbium-ui/react cascader primitive with the menu design. The primitive
 * owns levels, search, selection, keyboard and focus; this file decides the look and closes the
 * API around one layout (search header, scrolling list, optional clear footer).
 */

// Tree

/** One option of a cascader. A node with `children` opens a level; a node without is a leaf. */
interface CascaderNode {
  /** Stable unique id, and the committed value of a leaf. */
  value: string;
  /** Display text, used for search and typeahead. */
  label: string;
  /** Leading icon of the row. */
  icon?: React.ReactNode;
  /** Secondary line under the label. */
  description?: string;
  /** Nodes of the next level. */
  children?: CascaderNode[];
  /** Keeps the node visible but unselectable; a disabled level cannot be opened. */
  disabled?: boolean;
  /** Extra terms the search matches alongside the label. */
  keywords?: string[];
}

/** The primitive's node, carrying the Erbium node it was made from as `data`. */
type PrimitiveNode = CascaderPrimitiveNode<CascaderNode>;

const toPrimitiveNodes = (nodes: readonly CascaderNode[]): PrimitiveNode[] =>
  nodes.map((node) => ({
    children: node.children === undefined ? undefined : toPrimitiveNodes(node.children),
    data: node,
    disabled: node.disabled,
    keywords: node.keywords,
    label: node.label,
    value: node.value,
  }));

const toNodes = (path: readonly CascaderPrimitiveNode<CascaderNode>[]): CascaderNode[] =>
  path.flatMap((node) => (node.data === undefined ? [] : [node.data]));

const NodesContext = React.createContext<CascaderIndex<CascaderNode> | null>(null);

/** Every Erbium node by value, with its path from the top. */
const useNodes = (part: string) => {
  const index = React.use(NodesContext);

  if (index === null) {
    throw new Error(`${part} must be used within Cascader`);
  }

  return index;
};

/** The Erbium nodes on the path to a value, root first. */
const pathOf = (index: CascaderIndex<CascaderNode>, value: string) =>
  toNodes(index.get(value)?.path ?? []);

// Root

interface CascaderChangeDetails {
  /** The leaf that was picked or toggled, or `null` when the selection was cleared. */
  node: CascaderNode | null;
  /** The leaf's ancestors and the leaf itself, root first. Empty when cleared. */
  path: CascaderNode[];
}

interface CascaderSharedProps {
  /** The option tree. */
  items: readonly CascaderNode[];
  children?: React.ReactNode;
  /** Lets `CascaderSearch` filter the open level, as `searchable` on `DropdownMenu` does. */
  searchable?: boolean;
  /** Replaces the search match. Defaults to a locale-aware substring test on label and keywords. */
  filter?: (node: CascaderNode, query: string) => boolean;
  disabled?: boolean;
  /** Submits each selected value under this name with a surrounding form. */
  name?: string;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: MenuPrimitive.Root.Props["onOpenChange"];
  onOpenChangeComplete?: MenuPrimitive.Root.Props["onOpenChangeComplete"];
}

interface CascaderSingleProps extends CascaderSharedProps {
  multiple?: false;
  value?: string | null;
  defaultValue?: string | null;
  onValueChange?: (value: string | null, details: CascaderChangeDetails) => void;
}

interface CascaderMultipleProps extends CascaderSharedProps {
  /** Picks any number of leaves; the popup stays open while picking. */
  multiple: true;
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (value: string[], details: CascaderChangeDetails) => void;
}

type CascaderProps = CascaderSingleProps | CascaderMultipleProps;

/**
 * A select whose options form a tree. A row with children opens its level in place, inside the
 * same popup, and the search of a level finds options at any depth below it.
 */
const Cascader = (props: CascaderProps) => {
  const {
    children,
    defaultOpen,
    disabled,
    filter,
    items,
    name,
    onOpenChange,
    onOpenChangeComplete,
    open,
    searchable,
  } = props;

  const nodes = React.useMemo(() => toPrimitiveNodes(items), [items]);
  const index = React.useMemo(() => createCascaderIndex(nodes), [nodes]);

  // The primitive matches its own nodes; the filter is written against Erbium's.
  const match = React.useMemo<CascaderMatch | undefined>(
    () =>
      filter === undefined
        ? undefined
        : (node, query) => {
            const source = index.get(node.value)?.node.data;

            return source !== undefined && filter(source, query);
          },
    [filter, index],
  );

  const toDetails = (details: CascaderValueChangeDetails): CascaderChangeDetails =>
    details.node === null
      ? { node: null, path: [] }
      : {
          node: index.get(details.node.value)?.node.data ?? null,
          path: pathOf(index, details.node.value),
        };

  const shared = {
    defaultOpen,
    disabled,
    filter: match,
    items: nodes,
    name,
    onOpenChange,
    onOpenChangeComplete,
    open,
    searchable,
  };

  let root: React.ReactNode;

  if (props.multiple === true) {
    const onMultipleChange = props.onValueChange;

    root = (
      <CascaderPrimitive.Root
        {...shared}
        multiple
        value={props.value}
        defaultValue={props.defaultValue}
        onValueChange={(value, details) => {
          onMultipleChange?.(value, toDetails(details));
        }}
      >
        {children}
      </CascaderPrimitive.Root>
    );
  } else {
    const onSingleChange = props.onValueChange;

    root = (
      <CascaderPrimitive.Root
        {...shared}
        value={props.value}
        defaultValue={props.defaultValue}
        onValueChange={(value, details) => {
          onSingleChange?.(value, toDetails(details));
        }}
      >
        {children}
      </CascaderPrimitive.Root>
    );
  }

  return <NodesContext value={index}>{root}</NodesContext>;
};

// Trigger and value

/**
 * Opens the popup. By default it is a select-style button that shows the value. Pass `render`
 * to use another element, such as a toolbar `Button`: that element is then the whole trigger,
 * and the select styles, size and chevron are left out.
 */
const CascaderTrigger = ({
  className,
  size = "default",
  children,
  render,
  ...props
}: MenuPrimitive.Trigger.Props & {
  size?: "sm" | "default";
}) => {
  if (render !== undefined) {
    return (
      <CascaderPrimitive.Trigger
        data-slot="cascader-trigger"
        render={render}
        className={cn("group", className)}
        {...props}
      >
        {children}
      </CascaderPrimitive.Trigger>
    );
  }

  return (
    <CascaderPrimitive.Trigger
      data-slot="cascader-trigger"
      {...skeletonBlock}
      data-size={size}
      className={cn(
        "group flex w-fit min-w-0 items-center justify-between gap-control-gap control-size touch-target rounded-lg border surface-control text-control-sm whitespace-nowrap transition-[color,background-color,box-shadow] duration-150 outline-none select-none motion-reduce:transition-none aria-invalid:border-error aria-invalid:ring-[1.5px] aria-invalid:ring-invalid-halo group-data-invalid/field:border-error group-data-invalid/field:ring-[1.5px] group-data-invalid/field:ring-invalid-halo data-placeholder:text-muted-foreground data-[size=sm]:control-size-sm data-[size=sm]:rounded-[min(var(--radius-md),10px)] data-disabled:cursor-not-allowed data-disabled:opacity-50 dark:aria-invalid:border-invalid dark:group-data-invalid/field:border-invalid [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-control-icon",
        className,
      )}
      {...props}
    >
      {children}
      <RotatingChevron className="pointer-events-none size-control-icon text-muted-foreground" />
    </CascaderPrimitive.Trigger>
  );
};

interface CascaderValueProps extends Omit<React.ComponentProps<"span">, "children"> {
  /** Shown while nothing is selected. */
  placeholder?: React.ReactNode;
  /** Renders the selection. Receives the path of each selected leaf, root first. */
  children?: (paths: CascaderNode[][]) => React.ReactNode;
}

const CascaderPath = ({ path }: { path: CascaderNode[] }) =>
  path.map((node, position) =>
    position === path.length - 1 ? (
      <span key={node.value}>{node.label}</span>
    ) : (
      <span key={node.value} className="text-muted-foreground">
        {node.label}
        <span aria-hidden="true"> / </span>
      </span>
    ),
  );

/** The selection: the full path of a single leaf, or the labels of several. */
const CascaderValue = ({ className, placeholder, children, ...props }: CascaderValueProps) => {
  const index = useNodes("CascaderValue");
  const { state } = useCascader();

  return (
    <CascaderPrimitive.Value
      data-slot="cascader-value"
      className={cn("min-w-0 flex-1 truncate text-start", className)}
      {...props}
    >
      {({ paths }): React.ReactNode => {
        const selected = paths.map((path) => pathOf(index, path.at(-1)?.value ?? ""));

        if (children !== undefined) {
          return children(selected);
        }

        if (selected.length === 0) {
          return placeholder;
        }

        return state.multiple ? (
          selected.map((path) => path.at(-1)?.label).join(", ")
        ) : (
          <CascaderPath path={selected[0] ?? []} />
        );
      }}
    </CascaderPrimitive.Value>
  );
};

// Popup

/** The popup. Every level opens inside it, in place of the one before. */
const CascaderContent = ({
  align = "start",
  alignOffset,
  side = "bottom",
  sideOffset = 4,
  className,
  ...props
}: MenuPrimitive.Popup.Props &
  Pick<MenuPrimitive.Positioner.Props, "align" | "alignOffset" | "side" | "sideOffset">) => (
  <CascaderPrimitive.Portal>
    <CascaderPrimitive.Positioner
      className={menuPositionerClassName}
      align={align}
      alignOffset={alignOffset}
      side={side}
      sideOffset={sideOffset}
    >
      <CascaderPrimitive.Popup
        data-slot="cascader-content"
        className={cn(menuPopupClassName, "w-(--anchor-width) min-w-56", className)}
        {...props}
      />
    </CascaderPrimitive.Positioner>
  </CascaderPrimitive.Portal>
);

/**
 * Search field of the open level. It finds options at any depth below the level, and inside a
 * level it leads with a button back to the parent level. `placeholder` and `aria-label` apply to
 * the top level; inside a level, both name the level.
 */
const CascaderSearch = ({
  placeholder = "Search…",
  "aria-label": ariaLabel,
  ...props
}: MenuPrimitive.Input.Props) => {
  const { state } = useCascader();

  return (
    <div data-slot="cascader-search" className="shrink-0">
      <div
        className="flex search-input-row items-center"
        onPointerDown={(event) => {
          focusSearchInput(event.currentTarget, event);
        }}
      >
        {state.levelNode === null ? (
          <Icon
            name="search-01"
            aria-hidden="true"
            className="size-control-icon shrink-0 text-muted-foreground"
          />
        ) : (
          <CascaderPrimitive.Back
            render={
              <Button variant="ghost" size="icon-xs" className="-ms-1 shrink-0 rtl:rotate-180" />
            }
          >
            <Icon name="chevron-left" aria-hidden="true" />
          </CascaderPrimitive.Back>
        )}
        <CascaderPrimitive.Search
          data-slot="cascader-search-input"
          aria-label={ariaLabel}
          placeholder={placeholder}
          className="min-h-0 min-w-0 flex-1 bg-transparent py-0 text-field outline-hidden placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50"
          {...props}
        />
        <CascaderPrimitive.SearchClear
          aria-label="Clear search"
          render={<Button variant="ghost" size="icon-xs" />}
        >
          <Icon name="x" aria-hidden="true" />
        </CascaderPrimitive.SearchClear>
      </div>
      <Separator variant="full" />
    </div>
  );
};

/** Shown when the search of the open level matches nothing. */
const CascaderEmpty = ({
  className,
  children = "No results found.",
  ...props
}: MenuPrimitive.Empty.Props) => (
  <CascaderPrimitive.Empty
    data-slot="cascader-empty"
    className={cn(menuEmptyClassName, className)}
    {...props}
  >
    {children}
  </CascaderPrimitive.Empty>
);

// List

type CascaderRenderRow = (node: CascaderNode) => React.ReactNode;

interface CascaderListProps extends Omit<MenuPrimitive.List.Props, "children"> {
  /** Renders the content of each row. Defaults to the node's icon, label and description. */
  children?: CascaderRenderRow;
}

const secondaryLineClassName = "truncate text-metadata text-muted-foreground";

/** One row: a radio or checkbox item for a leaf, a row that opens the level of one with children. */
const CascaderItem = ({
  row,
  render,
}: {
  row: CascaderRow<CascaderNode>;
  render: CascaderRenderRow | undefined;
}) => {
  const { state } = useCascader();
  const node = row.node.data;

  if (node === undefined) {
    return null;
  }

  const branch = row.kind === "branch";

  return (
    <CascaderPrimitive.Item
      row={row}
      data-slot={branch ? "cascader-branch" : "cascader-item"}
      className={cn(
        branch ? menuItemClassName : menuChoiceItemClassName,
        "group/cascader-item gap-related",
      )}
    >
      {branch ? null : (
        <span className={menuChoiceIndicatorClassName}>
          {state.multiple ? (
            <CascaderPrimitive.ItemIndicator className="group/check-indicator inline-grid">
              <CheckboxStateIcon className="size-control-icon" />
            </CascaderPrimitive.ItemIndicator>
          ) : (
            <CascaderPrimitive.ItemIndicator keepMounted={false}>
              <Icon name="check" />
            </CascaderPrimitive.ItemIndicator>
          )}
        </span>
      )}
      <span data-slot="cascader-item-content" className="flex min-w-0 flex-1 flex-col">
        <span className="flex min-w-0 items-center gap-related">
          {render === undefined ? (
            <>
              {node.icon}
              <span className="truncate">{node.label}</span>
            </>
          ) : (
            render(node)
          )}
        </span>
        <CascaderPrimitive.ItemTrail
          data-slot="cascader-item-description"
          className={secondaryLineClassName}
        />
        {row.trail.length > 0 || node.description === undefined ? null : (
          <span data-slot="cascader-item-description" className={secondaryLineClassName}>
            {node.description}
          </span>
        )}
      </span>
      {branch ? (
        <>
          <CascaderPrimitive.ItemCount
            data-slot="cascader-branch-count"
            className="text-muted-foreground tabular-nums group-data-selected/cascader-item:text-foreground"
          />
          <Icon
            name="chevron-right"
            aria-hidden="true"
            className="text-muted-foreground rtl:rotate-180"
          />
        </>
      ) : null}
    </CascaderPrimitive.Item>
  );
};

/**
 * The options of the open level, under the level's name. A leaf picks a value; a row with
 * children opens its level in place. While searched, it lists every match below the level with
 * the path that leads there.
 */
const CascaderList = ({ children, className, ...props }: CascaderListProps) => (
  <MenuScroll>
    <CascaderPrimitive.List
      data-slot="cascader-list"
      className={cn(menuListClassName, className)}
      {...props}
    >
      <CascaderPrimitive.BackItem
        data-slot="cascader-back"
        className={cn(menuItemClassName, "gap-related text-muted-foreground")}
      >
        <Icon name="chevron-left" aria-hidden="true" className="rtl:rotate-180" />
        Back
      </CascaderPrimitive.BackItem>
      <CascaderPrimitive.Level data-filter-section="">
        <CascaderPrimitive.LevelLabel data-slot="cascader-label" className={menuLabelClassName} />
        <CascaderPrimitive.Rows>
          {(row: CascaderRow<CascaderNode>) => <CascaderItem row={row} render={children} />}
        </CascaderPrimitive.Rows>
      </CascaderPrimitive.Level>
    </CascaderPrimitive.List>
  </MenuScroll>
);

/** Footer action that clears the selection. Disabled while nothing is selected. */
const CascaderClear = ({
  className,
  children = "Clear selection",
  ...props
}: Omit<React.ComponentProps<typeof Button>, "onClick">) => (
  <div data-slot="cascader-clear" className="shrink-0">
    <Separator variant="full" />
    <div className="p-1">
      <CascaderPrimitive.Clear
        render={
          <Button
            variant="ghost"
            size="sm"
            className={cn("w-full justify-start gap-related text-muted-foreground", className)}
            {...props}
          />
        }
      >
        <Icon name="x" aria-hidden="true" />
        {children}
      </CascaderPrimitive.Clear>
    </div>
  </div>
);

export {
  Cascader,
  CascaderClear,
  CascaderContent,
  CascaderEmpty,
  CascaderList,
  CascaderSearch,
  CascaderTrigger,
  CascaderValue,
};

export type { CascaderChangeDetails, CascaderNode, CascaderProps };

let transitionFrame = 0;

/** Apply a synchronous theme update without interpolating component colors or shadows. */
export const changeTheme = (update: () => void) => {
  const root = document.documentElement;
  cancelAnimationFrame(transitionFrame);
  root.dataset.themeChanging = "";

  try {
    update();
  } finally {
    // Commit the new palette while transitions are disabled, including portal content.
    getComputedStyle(root).getPropertyValue("--background");
    transitionFrame = requestAnimationFrame(() => {
      transitionFrame = requestAnimationFrame(() => {
        delete root.dataset.themeChanging;
      });
    });
  }
};

import * as React from "react";
import { d3Curve } from "@tanstack/charts";
import type { ChartPoint, ChartTheme, ChartTooltipContent, ChartValue } from "@tanstack/charts";
import { Chart as TanStackChart } from "@tanstack/charts/react/tooltip";
import type {
  ChartProps as TanStackChartProps,
  ChartTooltipBodyRenderContext,
} from "@tanstack/charts/react/tooltip";
import { scaleLinear } from "@tanstack/charts/scales/linear";
import { scaleOrdinal } from "@tanstack/charts/scales/ordinal";
import { scalePoint } from "@tanstack/charts/scales/point";
import { scaleUtc } from "@tanstack/charts/scales/time";
import { tooltip } from "@tanstack/charts/tooltip";
import { curveLinear, curveMonotoneX, curveStepAfter } from "d3-shape";
import { cn } from "@/registry/erbium/lib/erbium-utils";

/**
 * Series colors in order: the six Vitesse accents (green, blue, cyan, orange,
 * magenta, yellow), with separate light and dark values in `theme.css`. A series
 * without its own color takes the next one. Past six series, group the smallest
 * into one "Other" series: more colors stop being distinguishable.
 */
const chartColors = [
  "var(--chart-1)",
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
  "var(--chart-5)",
  "var(--chart-6)",
] as const;

/** Scene colors for TanStack Charts, resolved from Erbium's theme tokens. */
const chartTheme = {
  background: "transparent",
  foreground: "var(--foreground)",
  grid: "var(--border)",
  muted: "var(--muted-foreground)",
  palette: chartColors,
} satisfies Partial<ChartTheme>;

/** The built-in tooltip, styled by `.erbium-chart-tooltip` in `chart.css`. */
const chartTooltip = { className: "erbium-chart-tooltip", use: tooltip } as const;

/** Formats a number for ticks and tooltips. Build one with `chartNumberFormat`. */
type ChartFormat = (value: number) => string;

/** A `ChartFormat` from `Intl.NumberFormat` options, such as `{ style: "percent" }`. */
const chartNumberFormat = (options?: Intl.NumberFormatOptions, locale?: string): ChartFormat => {
  const formatter = new Intl.NumberFormat(locale, options);

  return (value) => formatter.format(value);
};

const formatChartNumber = (value: number, format: ChartFormat = chartNumberFormat()) =>
  format(value);

/** Prints an x or category value: dates in the reader's locale, everything else as written. */
const formatChartIndex = (value: ChartValue, locale?: string) =>
  value instanceof Date ? value.toLocaleDateString(locale) : String(value);

/**
 * The fields of `TDatum` whose values fit `TValue`. Chart types use it to accept
 * only fields of the right kind, such as numeric fields for series.
 */
type ChartFieldOf<TDatum, TValue> = {
  [TField in keyof TDatum]-?: TDatum[TField] extends TValue ? TField : never;
}[keyof TDatum] &
  string;

/** A row with an x or category field and numeric series fields. */
type ChartDatum<TIndex extends string, TKey extends string> = Record<TIndex, ChartValue> &
  Partial<Record<TKey, number | null>>;

/** One series, or one category of a pie, scatter, or heatmap. */
interface ChartSeries<TKey extends string = string> {
  /** The data key that holds the series' values, or the category value it names. */
  key: TKey;
  /** The name in the legend and tooltip. Defaults to `key`. */
  label?: string;
  /** Any CSS color. Defaults to the next of `--chart-1` to `--chart-6`. */
  color?: string;
}

interface ResolvedChartSeries<TKey extends string = string> {
  key: TKey;
  label: string;
  color: string;
}

const resolveChartSeries = <TKey extends string>(
  series: readonly ChartSeries<TKey>[],
): ResolvedChartSeries<TKey>[] =>
  series.map((item, position) => ({
    color: item.color ?? chartColors[position % chartColors.length] ?? "var(--chart-1)",
    key: item.key,
    label: item.label ?? item.key,
  }));

/** One value of one series: the long form TanStack Charts marks consume. */
interface ChartRow<TDatum = unknown> {
  datum: TDatum;
  /** The category or position the value belongs to. */
  index: ChartValue;
  /** The series label, which is also its color-scale value. */
  series: string;
  value: number | null;
}

/** Turns wide rows (`{ month, desktop, mobile }`) into one row per series value. */
const foldChartSeries = <
  TIndex extends string,
  TKey extends string,
  TDatum extends ChartDatum<TIndex, TKey>,
>(
  data: readonly TDatum[],
  index: TIndex,
  series: readonly ResolvedChartSeries<TKey>[],
): ChartRow<TDatum>[] =>
  data.flatMap((datum) =>
    series.map((item) => ({
      datum,
      index: datum[index],
      series: item.label,
      value: datum[item.key] ?? null,
    })),
  );

/** Maps series labels to their colors. Pass every series, hidden ones included, so colors stay put. */
const chartColorScale = (series: readonly ResolvedChartSeries[]) =>
  scaleOrdinal(
    series.map((item) => item.label),
    series.map((item) => item.color),
  );

/** How the x axis reads its values: categories, numbers, or UTC dates. */
type ChartIndexType = "category" | "number" | "time";

/** The x scale for line and area charts. Categories sit on points, inset from the edges. */
const chartIndexScale = (type: ChartIndexType) => {
  if (type === "number") {
    return scaleLinear;
  }

  if (type === "time") {
    return scaleUtc;
  }

  return () => scalePoint().padding(0.2);
};

/** How a line or area moves between values. */
type ChartCurve = "linear" | "smooth" | "step";

const chartCurves = {
  linear: d3Curve(curveLinear),
  smooth: d3Curve(curveMonotoneX),
  step: d3Curve(curveStepAfter),
} as const;

interface ChartTooltipFormatOptions {
  /** Which position channel carries the value. */
  valueAxis?: "x" | "y";
  format?: ChartFormat;
  indexFormat?: (value: ChartValue) => string;
  locale?: string;
}

/** The tooltip for series charts: the shared x value as the heading, one row per series. */
const chartValueTooltip = ({
  valueAxis = "y",
  format,
  indexFormat,
  locale,
}: ChartTooltipFormatOptions) => {
  const valueOf = (point: ChartPoint) => Number(valueAxis === "y" ? point.yValue : point.xValue);
  const indexOf = (point: ChartPoint) => (valueAxis === "y" ? point.xValue : point.yValue);

  return {
    ...chartTooltip,
    format: (point: ChartPoint) => formatChartNumber(valueOf(point), format),
    formatGroup: (points: readonly ChartPoint[]) => {
      const [first] = points;

      if (first === undefined) {
        return "";
      }

      return indexFormat ? indexFormat(indexOf(first)) : formatChartIndex(indexOf(first), locale);
    },
  };
};

interface ChartSeriesStateOptions {
  /** Series hidden through the legend, by key. */
  hiddenSeries?: readonly string[];
  defaultHiddenSeries?: readonly string[];
  onHiddenSeriesChange?: (hiddenSeries: string[]) => void;
}

const noSeries: readonly string[] = [];

/**
 * Resolves colors and labels, and tracks which series the reader hid through the
 * legend. Hidden series keep their colors, so the remaining series do not repaint.
 */
const useChartSeries = <TKey extends string>(
  series: readonly ChartSeries<TKey>[],
  {
    hiddenSeries,
    defaultHiddenSeries = noSeries,
    onHiddenSeriesChange,
  }: ChartSeriesStateOptions = {},
) => {
  const [uncontrolled, setUncontrolled] = React.useState<readonly string[]>(defaultHiddenSeries);
  const hidden = hiddenSeries ?? uncontrolled;
  const all = React.useMemo(() => resolveChartSeries(series), [series]);

  const visible = React.useMemo(
    () => all.filter((item) => !hidden.includes(item.key)),
    [all, hidden],
  );

  const toggle = React.useCallback(
    (key: string) => {
      const next = hidden.includes(key) ? hidden.filter((item) => item !== key) : [...hidden, key];

      if (hiddenSeries === undefined) {
        setUncontrolled(next);
      }

      onHiddenSeriesChange?.(next);
    },
    [hidden, hiddenSeries, onHiddenSeriesChange],
  );

  return { all, hidden, toggle, visible };
};

/** The key beside a legend entry or tooltip value. */
const ChartSwatch = ({ className, color, style, ...props }: React.ComponentProps<"span">) => (
  <span
    aria-hidden
    data-slot="chart-swatch"
    className={cn("size-2 shrink-0 rounded-full", className)}
    style={{ backgroundColor: color, ...style }}
    {...props}
  />
);

type ChartLegendProps = Omit<React.ComponentProps<"ul">, "children"> & {
  series: readonly ResolvedChartSeries[];
  /** Keys of hidden series. */
  hiddenSeries?: readonly string[];
  /** Makes each entry a toggle that hides or shows its series. */
  onToggleSeries?: (key: string) => void;
};

/** The chart's legend, as HTML so it follows text direction, wrapping, and focus styles. */
const ChartLegend = ({
  className,
  series,
  hiddenSeries = noSeries,
  onToggleSeries,
  ...props
}: ChartLegendProps) => (
  <ul
    data-slot="chart-legend"
    className={cn("flex flex-wrap items-center gap-x-1 gap-y-0.5 text-metadata", className)}
    {...props}
  >
    {series.map((item) => {
      const isHidden = hiddenSeries.includes(item.key);

      const content = (
        <>
          <ChartSwatch color={item.color} />
          {item.label}
        </>
      );

      return (
        <li key={item.key}>
          {onToggleSeries ? (
            <button
              type="button"
              aria-pressed={!isHidden}
              data-hidden={isHidden ? "" : undefined}
              onClick={() => {
                onToggleSeries(item.key);
              }}
              className="inline-flex items-center gap-1.5 rounded-lg border border-transparent px-1.5 py-0.5 text-foreground outline-none transition-colors duration-150 motion-reduce:transition-none hover:bg-accent focus-visible:border-ring data-hidden:text-muted-foreground data-hidden:line-through data-hidden:[&>[data-slot=chart-swatch]]:opacity-40"
            >
              {content}
            </button>
          ) : (
            <span className="inline-flex items-center gap-1.5 px-1.5 py-0.5 text-foreground">
              {content}
            </span>
          )}
        </li>
      );
    })}
  </ul>
);

/**
 * TanStack Charts drops its own card styles when a custom body renders, so the
 * body carries the overlay surface that popovers and hover cards use.
 */
const tooltipSurface =
  "rounded-lg surface-overlay px-2 py-1.5 text-control-sm text-popover-foreground";

/** Tooltip content in Erbium markup. Passed to TanStack Charts as `renderTooltipBody`. */
const ChartTooltipBody = ({ content }: { content: ChartTooltipContent | string }) => {
  // oxlint-disable-next-line anti-slop/no-runtime-typeof -- TanStack Charts types tooltip content as its own union of a plain string or rows; this branches on that library contract, not on unparsed input.
  if (typeof content === "string") {
    return (
      <div data-slot="chart-tooltip" className={tooltipSurface}>
        {content}
      </div>
    );
  }

  const { title = "", rows } = content;

  return (
    <div data-slot="chart-tooltip" className={cn(tooltipSurface, "grid min-w-32 gap-1")}>
      {title === "" ? null : (
        <div data-slot="chart-tooltip-title" className="text-muted-foreground">
          {title}
        </div>
      )}
      <ul className="grid gap-0.5">
        {rows.map(({ active = false, color = "", label, value }) => (
          <li
            key={label}
            data-slot="chart-tooltip-row"
            data-active={active ? "" : undefined}
            className="flex items-center gap-2 data-active:font-selected"
          >
            {color === "" ? null : <ChartSwatch color={color} />}
            <span className="flex-1">{label}</span>
            <span className="font-medium tabular-nums">{value}</span>
          </li>
        ))}
      </ul>
    </div>
  );
};

const renderChartTooltip = ({ content }: ChartTooltipBodyRenderContext) => (
  <ChartTooltipBody content={content} />
);

type ChartProps<
  TDatum,
  TXValue extends ChartValue = ChartValue,
  TYValue extends ChartValue = ChartValue,
> = TanStackChartProps<TDatum, TXValue, TYValue>;

/**
 * Renders any TanStack Charts definition with Erbium's palette, tooltip body,
 * and typography. Chart types such as `BarChart` build their definition and
 * render through this component; use it directly for compositions they do not cover.
 */
const Chart = <
  TDatum,
  TXValue extends ChartValue = ChartValue,
  TYValue extends ChartValue = ChartValue,
>({
  className,
  renderTooltipBody = renderChartTooltip,
  ...props
}: ChartProps<TDatum, TXValue, TYValue>) => (
  <TanStackChart
    className={cn("erbium-chart text-metadata", className)}
    renderTooltipBody={renderTooltipBody}
    {...props}
  />
);

/** Props every chart type shares. */
interface ChartFrameProps extends ChartSeriesStateOptions {
  /** Names the chart for screen readers, such as "Revenue by month". */
  ariaLabel: string;
  /** Plot height in pixels. */
  height?: number;
  /** Width used for server rendering before the container is measured. */
  initialWidth?: number;
  className?: string;
  /** Shows the legend. Defaults to on when there is more than one series. */
  legend?: boolean;
  /** Shows a tooltip for the hovered or focused value. Defaults to on. */
  tooltip?: boolean;
  /** Formats values in ticks and tooltips. */
  format?: ChartFormat;
  /** The locale dates are printed in. Defaults to the browser's. */
  locale?: string;
  /** Shown in place of the plot when there is no data. */
  emptyMessage?: React.ReactNode;
}

type ChartRootProps = Omit<React.ComponentProps<"div">, "children"> & {
  ariaLabel: string;
  height: number;
  empty?: boolean;
  emptyMessage?: React.ReactNode;
  legend?: React.ReactNode;
  children: React.ReactNode;
};

/** The frame every chart type renders inside: legend, plot, and empty state. */
const ChartRoot = ({
  ariaLabel,
  className,
  height,
  empty = false,
  emptyMessage = "No data to show.",
  legend,
  children,
  ...props
}: ChartRootProps) => (
  <div data-slot="chart" className={cn("flex min-w-0 flex-col gap-3", className)} {...props}>
    {legend}
    {empty ? (
      <output
        aria-label={ariaLabel}
        data-slot="chart-empty"
        className="flex items-center justify-center rounded-lg border border-dashed text-metadata text-muted-foreground"
        style={{ height }}
      >
        {emptyMessage}
      </output>
    ) : (
      children
    )}
  </div>
);

export {
  Chart,
  ChartLegend,
  ChartRoot,
  ChartSwatch,
  ChartTooltipBody,
  chartColorScale,
  chartColors,
  chartCurves,
  chartIndexScale,
  chartNumberFormat,
  chartTheme,
  chartTooltip,
  chartValueTooltip,
  foldChartSeries,
  formatChartIndex,
  formatChartNumber,
  resolveChartSeries,
  useChartSeries,
};

export type {
  ChartCurve,
  ChartDatum,
  ChartFieldOf,
  ChartFormat,
  ChartFrameProps,
  ChartIndexType,
  ChartLegendProps,
  ChartProps,
  ChartRootProps,
  ChartRow,
  ChartSeries,
  ChartSeriesStateOptions,
  ResolvedChartSeries,
};

import { CheckboxStateIcon } from "@/registry/erbium/ui/stateful-icon";
import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox";
import { CheckboxGroup as CheckboxGroupPrimitive } from "@base-ui/react/checkbox-group";
import { mergeProps } from "@base-ui/react/merge-props";
import { flushSync } from "react-dom";

import { useDragSelect } from "@/registry/erbium/hooks/use-drag-select";
import { skeletonBlock } from "@/registry/erbium/lib/skeleton-hints";
import { checkboxClassName } from "@/registry/erbium/lib/choice-styles";
import { cn } from "@/registry/erbium/lib/erbium-utils";

const Checkbox = ({ className, ...props }: CheckboxPrimitive.Root.Props) => (
  <CheckboxPrimitive.Root
    data-slot="checkbox"
    {...skeletonBlock}
    data-choice=""
    className={cn(checkboxClassName, className)}
    {...props}
  >
    <CheckboxPrimitive.Indicator
      data-slot="checkbox-indicator"
      keepMounted
      className="group/check-indicator grid place-content-center text-current"
    >
      <CheckboxStateIcon />
    </CheckboxPrimitive.Indicator>
  </CheckboxPrimitive.Root>
);

// Drag targets every checkbox except the `parent`, which follows its children.
const DRAGGABLE = '[data-slot="checkbox"]:not([data-parent])';

const checkboxesIn = (group: HTMLElement) => [...group.querySelectorAll<HTMLElement>(DRAGGABLE)];

const isEditable = (checkbox: HTMLElement) =>
  !Object.hasOwn(checkbox.dataset, "disabled") && !Object.hasOwn(checkbox.dataset, "readonly");

// The row under the pointer is its closest ancestor holding exactly one checkbox,
// so labels, `Field`s, and plain wrappers all work as rows.
const checkboxAt = (target: Element, group: HTMLElement) => {
  for (let node: Element | null = target; node && node !== group; node = node.parentElement) {
    const found = node.matches(DRAGGABLE) ? [node] : node.querySelectorAll(DRAGGABLE);

    if (found.length > 0) {
      const [only] = found;

      return found.length === 1 && only instanceof HTMLElement ? only : null;
    }
  }

  return null;
};

/** Shares one `value` array across checkboxes. Press a row and drag to set the rows it crosses. */
const CheckboxGroup = ({ className, ...props }: CheckboxGroupPrimitive.Props) => {
  const dragSelect = useDragSelect({
    resolve(target, group) {
      const checkbox = checkboxAt(target, group);

      if (!checkbox || !isEditable(checkbox)) {
        return null;
      }

      return {
        index: checkboxesIn(group).indexOf(checkbox),
        selected: Object.hasOwn(checkbox.dataset, "checked"),
      };
    },
    selectRange(start, end, selected, group) {
      for (const checkbox of checkboxesIn(group).slice(start, end + 1)) {
        if (isEditable(checkbox) && Object.hasOwn(checkbox.dataset, "checked") !== selected) {
          // A real click keeps Base UI's value, form state, and callbacks in charge. Flush each one
          // because a group with a `parent` checkbox computes the next value from the last render.
          flushSync(() => {
            checkbox.click();
          });
        }
      }
    },
  });

  return (
    <CheckboxGroupPrimitive
      data-slot="checkbox-group"
      className={cn("flex flex-col gap-3", className)}
      {...mergeProps(dragSelect, props)}
    />
  );
};

export { Checkbox, CheckboxGroup };

/*
 * The look of Erbium's choice controls, shared by `RadioGroupItem`, `Checkbox`, the card `Field`
 * and controls that draw the same choice around another input, such as the questionnaire's
 * choices. State comes from `data-checked`, `data-indeterminate` and `aria-invalid` on the element.
 */

