import { Tabs as TabsPrimitive } from "@base-ui/react/tabs";
import { createContext, use, useEffect, useMemo, useRef, useState } from "react";
import type { ComponentProps } from "react";
import type { TokensResult } from "shiki/core";
import { TabsList, TabsTrigger } from "@/registry/erbium/ui/tabs";
import { DirectionProvider } from "@/registry/erbium/ui/direction";
import { Icon } from "@/registry/erbium/ui/icon";
import { codeLanguageIcon } from "@/registry/erbium/lib/code-language-icon";
import { normalizeCodeLanguage, updateCodeHighlight } from "@/registry/erbium/lib/code-highlighter";
import type { CodeHighlight } from "@/registry/erbium/lib/code-highlighter";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import type { CSSVariableStyle } from "@/registry/erbium/lib/erbium-utils";
import {
  CodePanelCopyButton,
  CodePanelHeader,
  CodePanelLines,
  CodePanelTitle,
  codePanelFocusRing,
  codePanelSurface,
} from "@/registry/erbium/blocks/code-panel";
import type { CodePanelLine } from "@/registry/erbium/blocks/code-panel";
import type { CopyButtonProps } from "@/registry/erbium/blocks/copy-button";

type CodeToken = TokensResult["tokens"][number][number];

const lineBreak = /\r\n|\n|\r/u;

const plaintext = new Set(["text", "plaintext", "plain", "txt", ""]);

/** Highlighted output from `highlightCode`, for code tokenized ahead of render. */
type CodeBlockTokens = Pick<TokensResult, "tokens" | "rootStyle">;

const CodeBlockToken = ({ token }: { token: CodeToken }) => {
  const htmlStyle = "htmlStyle" in token ? token.htmlStyle : undefined;

  const tokenStyle: CSSVariableStyle = {
    "--shiki-dark": htmlStyle?.["--shiki-dark"],
    "--shiki-light": htmlStyle?.["--shiki-light"],
  };

  return (
    <span
      style={tokenStyle}
      data-italic={htmlStyle?.["font-style"] === "italic" ? "" : undefined}
      data-bold={htmlStyle?.["font-weight"] === "bold" ? "" : undefined}
      className="text-(--shiki-light,inherit) dark:text-(--shiki-dark,inherit) data-italic:italic data-bold:font-bold"
    >
      {token.content}
    </span>
  );
};

interface CodeBlockItem {
  value: string;
  label: string;
  code: string;
  language?: string;
  tokens?: CodeBlockTokens;
  /** Lines to call out, by their displayed number (counted from `startLine`). */
  highlightLines?: readonly number[];
  disabled?: boolean;
}

type CodeBlockSource =
  | {
      code: string;
      language?: string;
      tokens?: CodeBlockTokens;
      /** Lines to call out, by their displayed number (counted from `startLine`). */
      highlightLines?: readonly number[];
      items?: never;
    }
  | {
      items: readonly CodeBlockItem[];
      code?: never;
      language?: never;
      tokens?: never;
      highlightLines?: never;
    };

type CodeBlockProps = Omit<
  TabsPrimitive.Root.Props,
  "value" | "defaultValue" | "onValueChange" | "orientation" | "dir"
> &
  CodeBlockSource & {
    dir?: never;
    value?: string;
    defaultValue?: string;
    onValueChange?: (value: string, details: TabsPrimitive.Root.ChangeEventDetails) => void;
    surface?: "code" | "command";
    lineNumbers?: boolean;
    /** The number of the first line, when `lineNumbers` is set. */
    startLine?: number;
    wrap?: boolean;
    title?: string;
  };

interface CodeBlockContextValue {
  items: readonly CodeBlockItem[];
  active: CodeBlockItem | undefined;
  surface: "code" | "command";
  lineNumbers: boolean;
  startLine: number;
  wrap: boolean;
  /** A command block whose items all have the same icon shows it once, before the tabs. */
  sharedIcon: boolean;
}

const CodeBlockContext = createContext<CodeBlockContextValue | null>(null);

const useCodeBlock = () => {
  const context = use(CodeBlockContext);

  if (!context) {
    throw new Error("Code block parts must be inside CodeBlock.");
  }

  return context;
};

const CodeBlockHeader = ({ className, ...props }: ComponentProps<typeof CodePanelHeader>) => (
  <CodePanelHeader
    {...props}
    data-slot="code-block-header"
    className={cn("flex-nowrap pe-12 group-data-[surface=command]/code-block:min-h-9", className)}
  />
);

const CodeBlockTitle = ({ className, ...props }: ComponentProps<typeof CodePanelTitle>) => (
  <CodePanelTitle {...props} data-slot="code-block-title" className={cn("truncate", className)} />
);

const CodeBlockActions = ({ className, ...props }: ComponentProps<"div">) => (
  <div
    {...props}
    data-slot="code-block-actions"
    className={cn(
      "absolute end-2 top-2 z-10 flex items-center gap-1 rounded-md bg-surface-panel",
      // Over the source, actions appear on hover or focus so they do not cover code while reading;
      // touch screens have no hover, and a header leaves them room, so both keep them shown.
      "opacity-0 transition-opacity group-focus-within/code-block:opacity-100 group-hover/code-block:opacity-100 group-has-[[data-slot=code-block-header]]/code-block:opacity-100 pointer-coarse:opacity-100 motion-reduce:transition-none",
      className,
    )}
  />
);

const CodeBlockLanguage = ({ children, ...props }: ComponentProps<typeof CodeBlockTitle>) => {
  const { active } = useCodeBlock();

  return <CodeBlockTitle {...props}>{children ?? active?.language ?? "text"}</CodeBlockTitle>;
};

const itemIcon = (item: CodeBlockItem | undefined, surface: "code" | "command") =>
  codeLanguageIcon(item?.language ?? (surface === "command" ? "shell" : undefined));

const CodeBlockIcon = ({
  value,
  className,
  ...props
}: Omit<ComponentProps<typeof Icon>, "name"> & { value?: string }) => {
  const { active, items, surface } = useCodeBlock();
  const item = value === undefined ? active : items.find((entry) => entry.value === value);

  return (
    <Icon
      {...props}
      className={cn("size-4.5", className)}
      name={itemIcon(item, surface)}
      data-slot="code-block-icon"
    />
  );
};

const CodeBlockTab = (props: ComponentProps<typeof TabsTrigger>) => <TabsTrigger {...props} />;

const CodeBlockTabs = ({
  children,
  className,
  "aria-label": label = "Code examples",
  ...props
}: ComponentProps<typeof TabsList>) => {
  const { items, sharedIcon } = useCodeBlock();

  return (
    <TabsList
      {...props}
      aria-label={label}
      className={cn("h-7 min-w-0 max-w-full overflow-x-auto", className)}
    >
      {children ??
        items.map((item) => (
          <CodeBlockTab key={item.value} value={item.value} disabled={item.disabled}>
            {sharedIcon ? null : <CodeBlockIcon value={item.value} />}
            {item.label}
          </CodeBlockTab>
        ))}
    </TabsList>
  );
};

/**
 * A ghost copy action for the active source. Keep it icon-only when it copies the block's source;
 * add a label only when it names something the icon cannot, such as "Copy prompt".
 */
const CodeBlockCopyButton = ({
  value,
  ...props
}: Omit<CopyButtonProps, "value"> & { value?: string }) => {
  const { active, surface } = useCodeBlock();

  return (
    <CodePanelCopyButton
      value={value ?? active?.code ?? ""}
      aria-label={surface === "command" ? "Copy command" : "Copy code"}
      disabled={!active}
      {...props}
    />
  );
};

// ANSI select graphic rendition sequences, which terminal output colors and styles text with.
const ansiStyle = new RegExp(`${String.fromCodePoint(27)}\\[[0-9;]*m`, "gu");

interface CodeLinesOptions {
  lineNumbers: boolean;
  startLine: number;
  highlightLines?: readonly number[];
  /** The tokens were highlighted from this exact source. */
  current: boolean;
  /** The source is terminal output, whose escape codes are never shown as text. */
  ansi: boolean;
}

/**
 * The source as panel rows. Tokens from an earlier version of a changing source keep coloring the
 * lines whose text is unchanged or has only grown, while the new version highlights.
 */
const codeLines = (
  code: string,
  result: CodeBlockTokens | undefined,
  options: CodeLinesOptions,
): CodePanelLine[] => {
  const calledOut = new Set(options.highlightLines);
  const texts = (options.ansi ? code.replaceAll(ansiStyle, "") : code).split(lineBreak);

  // A final line break ends the last line rather than starting an empty one. Copying still uses
  // the exact source.
  if (texts.length > 1 && lineBreak.test(code.at(-1) ?? "")) {
    texts.pop();
  }

  return texts.map((text, index) => {
    const number = options.startLine + index;
    const row = result?.tokens[index] ?? [];
    const highlighted = row.map((token) => token.content).join("");
    // A line that grew since it was highlighted, as a streamed line does, keeps its colors and
    // shows the new text plainly until the next highlight.
    const reusable = highlighted !== "" && (options.current || text.startsWith(highlighted));

    return {
      content: reusable ? (
        <>
          {row.map((token, tokenIndex) => (
            <CodeBlockToken key={tokenIndex} token={token} />
          ))}
          {options.current ? null : text.slice(highlighted.length)}
        </>
      ) : undefined,
      number: options.lineNumbers ? number : undefined,
      text,
      tone: calledOut.has(number) ? "highlight" : undefined,
    };
  });
};

/** A theme color from the highlighter's root style, which is `false` when the theme sets none. */
const themeColor = (result: CodeBlockTokens | undefined, name: string) => {
  const rootStyle = result?.rootStyle;
  const declarations = rootStyle === undefined || rootStyle === false ? [] : rootStyle.split(";");
  const declaration = declarations.find((entry) => entry.startsWith(`${name}:`));

  return declaration?.slice(name.length + 1);
};

type CodeBlockContentProps = Omit<
  ComponentProps<"pre">,
  "children" | "dangerouslySetInnerHTML" | "dir"
>;

const CodeBlockContent = ({ className, style, ...props }: CodeBlockContentProps) => {
  const { active, lineNumbers, startLine, wrap, surface } = useCodeBlock();
  const code = active?.code ?? "";
  const language = active?.language ?? "text";
  const tokens = active?.tokens;

  const [highlight, setHighlight] = useState<CodeHighlight>();
  // The latest highlight, which a growing source continues from.
  const latest = useRef<CodeHighlight>(undefined);

  useEffect(() => {
    let current = true;

    const run = async () => {
      try {
        const next = await updateCodeHighlight(latest.current, code, language);

        if (current) {
          latest.current = next;
          setHighlight(next);
        }
      } catch {
        // Source remains readable as plain text when highlighting is unavailable.
      }
    };

    // Provided tokens render on the server and skip the client highlighter.
    if (tokens === undefined && !plaintext.has(language)) {
      void run();
    }

    return () => {
      current = false;
    };
  }, [code, language, tokens]);

  // Until the current source is highlighted, the previous highlight colors the lines it shares.
  const sameLanguage = highlight?.language === normalizeCodeLanguage(language);
  const result = tokens ?? (sameLanguage ? highlight?.result : undefined);

  // Numbered rows use the file and diff view gutter; plain rows pad to the panel. The code column
  // keeps clear of the anchored actions, so row tints still reach both edges.
  const plainInset =
    surface === "command"
      ? "px-3 group-has-[[data-slot=code-block-actions]]/code-block:pe-12"
      : "px-panel group-has-[[data-slot=code-block-actions]]/code-block:pe-12";

  const codeInset = lineNumbers
    ? "pe-4 group-has-[[data-slot=code-block-actions]]/code-block:pe-12"
    : plainInset;

  const lines = codeLines(code, result, {
    ansi: normalizeCodeLanguage(language) === "ansi",
    current: tokens !== undefined || (sameLanguage && highlight?.code === code),
    highlightLines: active?.highlightLines,
    lineNumbers,
    startLine,
  });

  const blockStyle: CSSVariableStyle = {
    "--shiki-dark": themeColor(result, "--shiki-dark"),
    "--shiki-light": themeColor(result, "--shiki-light"),
    ...style,
  };

  return (
    <pre
      // Long code scrolls inside a fixed height; keyboard users need a tab stop to scroll it
      // (WCAG 2.1.1, axe scrollable-region-focusable). The rule only knows interactive roles.
      // oxlint-disable-next-line jsx-a11y/no-noninteractive-tabindex
      tabIndex={0}
      {...props}
      data-slot="code-block-content"
      data-language={language}
      dir="ltr"
      style={blockStyle}
      className={cn(
        "m-0 max-h-120 overflow-auto text-code-block [tab-size:2] text-(--shiki-light,inherit) dark:text-(--shiki-dark,inherit)",
        codePanelFocusRing,
        surface === "command" ? "px-3 py-3" : "p-panel",
        // Rows pad themselves so highlighted lines reach both edges.
        "px-0",
        className,
      )}
    >
      <code>
        <CodePanelLines lines={lines} wrap={wrap} limit={lines.length} codeClassName={codeInset} />
      </code>
    </pre>
  );
};

const CodeBlockPanel = ({
  value,
  ...props
}: Omit<TabsPrimitive.Panel.Props, "children"> & { value: string }) => {
  const context = useCodeBlock();

  const panelContext = useMemo(
    () => ({ ...context, active: context.items.find((entry) => entry.value === value) }),
    [context, value],
  );

  return (
    <TabsPrimitive.Panel {...props} value={value} data-slot="code-block-panel">
      <CodeBlockContext value={panelContext}>
        <CodeBlockContent />
      </CodeBlockContext>
    </TabsPrimitive.Panel>
  );
};

const CodeBlock = ({
  code,
  language,
  tokens,
  highlightLines,
  items: providedItems,
  value,
  defaultValue,
  onValueChange,
  surface = "code",
  lineNumbers = false,
  startLine = 1,
  wrap = false,
  title,
  children,
  className,
  ...props
}: CodeBlockProps) => {
  const items = useMemo(
    () =>
      providedItems ?? [
        {
          code: code ?? "",
          highlightLines,
          label: title ?? language ?? "Code",
          language,
          tokens,
          value: "code",
        },
      ],
    [providedItems, code, highlightLines, language, title, tokens],
  );

  const [selection, setSelection] = useState(defaultValue);
  const requested = value ?? selection;

  const enabled = items.filter((item) => item.disabled !== true);
  const active = enabled.find((item) => item.value === requested) ?? enabled.at(0);

  // Command tabs are alternatives for one command (package managers), so a shared icon shows once;
  // file tabs keep an icon each, even when the files share a language.
  const sharedIcon =
    surface === "command" &&
    items.length > 1 &&
    new Set(items.map((item) => itemIcon(item, surface))).size === 1;

  const context = useMemo(
    () => ({ active, items, lineNumbers, sharedIcon, startLine, surface, wrap }),
    [active, items, lineNumbers, sharedIcon, startLine, surface, wrap],
  );

  const hasTabs = providedItems !== undefined && items.length > 0;
  const hasTitle = title !== undefined && title !== "";

  return (
    <DirectionProvider direction="ltr">
      <CodeBlockContext value={context}>
        <TabsPrimitive.Root
          {...props}
          dir="ltr"
          data-slot="code-block"
          data-surface={surface}
          className={cn("group/code-block relative", codePanelSurface, className)}
          value={active?.value ?? null}
          onValueChange={(next, details) => {
            // Tabs report any value; only an item's value selects code.
            const item = items.find((entry) => entry.value === next);

            if (!item) {
              return;
            }

            onValueChange?.(item.value, details);

            if (!details.isCanceled && value === undefined) {
              setSelection(item.value);
            }
          }}
        >
          {children ?? (
            <>
              {hasTabs || hasTitle ? (
                <CodeBlockHeader>
                  {hasTabs ? (
                    <div className="flex min-w-0 items-center gap-related">
                      {sharedIcon ? (
                        <CodeBlockIcon className="shrink-0 text-muted-foreground" />
                      ) : null}
                      <CodeBlockTabs />
                    </div>
                  ) : (
                    <CodeBlockTitle>
                      <CodeBlockIcon />
                      <span className="truncate">{title}</span>
                    </CodeBlockTitle>
                  )}
                </CodeBlockHeader>
              ) : null}
              <CodeBlockActions>
                <CodeBlockCopyButton />
              </CodeBlockActions>
              {providedItems ? (
                items.map((item) => <CodeBlockPanel key={item.value} value={item.value} />)
              ) : (
                <CodeBlockContent />
              )}
            </>
          )}
        </TabsPrimitive.Root>
      </CodeBlockContext>
    </DirectionProvider>
  );
};

export {
  CodeBlock,
  CodeBlockHeader,
  CodeBlockTitle,
  CodeBlockActions,
  CodeBlockLanguage,
  CodeBlockIcon,
  CodeBlockTabs,
  CodeBlockTab,
  CodeBlockPanel,
  CodeBlockContent,
  CodeBlockCopyButton,
};

export type { CodeBlockProps, CodeBlockItem, CodeBlockContentProps, CodeBlockTokens };

import type { GrammarState, HighlighterCore, LanguageRegistration, TokensResult } from "shiki/core";

interface Grammar {
  /** Shiki's name for the language. */
  name: string;
  load: () => Promise<{ default: LanguageRegistration[] }>;
}

// Keyed by the normalized language name. Each grammar loads the first time it is used.
const grammars = new Map<string, Grammar>([
  ["css", { load: async () => await import("shiki/langs/css.mjs"), name: "css" }],
  ["diff", { load: async () => await import("shiki/langs/diff.mjs"), name: "diff" }],
  ["html", { load: async () => await import("shiki/langs/html.mjs"), name: "html" }],
  ["js", { load: async () => await import("shiki/langs/javascript.mjs"), name: "javascript" }],
  ["json", { load: async () => await import("shiki/langs/json.mjs"), name: "json" }],
  ["jsx", { load: async () => await import("shiki/langs/jsx.mjs"), name: "jsx" }],
  ["markdown", { load: async () => await import("shiki/langs/markdown.mjs"), name: "markdown" }],
  ["python", { load: async () => await import("shiki/langs/python.mjs"), name: "python" }],
  ["shell", { load: async () => await import("shiki/langs/shellscript.mjs"), name: "shellscript" }],
  ["sql", { load: async () => await import("shiki/langs/sql.mjs"), name: "sql" }],
  ["ts", { load: async () => await import("shiki/langs/typescript.mjs"), name: "typescript" }],
  ["tsx", { load: async () => await import("shiki/langs/tsx.mjs"), name: "tsx" }],
  ["yaml", { load: async () => await import("shiki/langs/yaml.mjs"), name: "yaml" }],
]);

const aliases = new Map<string, string>([
  ["bash", "shell"],
  ["javascript", "js"],
  ["md", "markdown"],
  ["patch", "diff"],
  ["py", "python"],
  ["sh", "shell"],
  ["shellscript", "shell"],
  ["typescript", "ts"],
  ["yml", "yaml"],
]);

const themes = { dark: "vitesse-dark", light: "vitesse-light" };

let highlighter: Promise<HighlighterCore> | undefined;
const languageRequests = new Map<string, Promise<void>>();

export const normalizeCodeLanguage = (language: string) => {
  const name = language.trim().toLowerCase();

  return aliases.get(name) ?? name;
};

const createHighlighter = async () => {
  const [core, engine, light, dark] = await Promise.all([
    import("shiki/core"),
    import("shiki/engine/javascript"),
    import("shiki/themes/vitesse-light.mjs"),
    import("shiki/themes/vitesse-dark.mjs"),
  ]);

  return await core.createHighlighterCore({
    engine: engine.createJavaScriptRegexEngine(),
    langs: [],
    themes: [light.default, dark.default],
  });
};

const getHighlighter = async () => {
  highlighter ??= createHighlighter();

  try {
    return await highlighter;
  } catch (error) {
    // A failed load is retried by the next caller.
    highlighter = undefined;
    throw error;
  }
};

const loadGrammar = async (instance: HighlighterCore, grammar: Grammar) => {
  const module = await grammar.load();
  await instance.loadLanguage(module.default);
};

// One runtime and one in-flight grammar load per language, shared by every block. Returns Shiki's
// name for the language, or `text` for a language without a grammar.
const resolveLanguage = async (instance: HighlighterCore, normalized: string) => {
  // Shiki renders ANSI escape codes without a grammar.
  if (normalized === "ansi") {
    return "ansi";
  }

  const grammar = grammars.get(normalized);

  if (!grammar) {
    return "text";
  }

  if (!instance.getLoadedLanguages().includes(grammar.name)) {
    let request = languageRequests.get(grammar.name);

    if (!request) {
      request = loadGrammar(instance, grammar);
      languageRequests.set(grammar.name, request);
    }

    try {
      await request;
    } finally {
      languageRequests.delete(grammar.name);
    }
  }

  return grammar.name;
};

const tokenizeLines = (instance: HighlighterCore, lang: string, code: string) => {
  const lines = code
    .split(/\r\n|\n|\r/u)
    .map((line) => instance.codeToTokens(line, { defaultColor: false, lang, themes }));

  return { ...lines[0], tokens: lines.flatMap((line) => line.tokens) };
};

const tokenize = (
  instance: HighlighterCore,
  lang: string,
  code: string,
  grammarState?: GrammarState,
): TokensResult =>
  // ANSI has no grammar state, so each line is colored on its own and gets the same colors
  // whether it arrives at once or streams.
  lang === "ansi"
    ? tokenizeLines(instance, lang, code)
    : instance.codeToTokens(code, { defaultColor: false, grammarState, lang, themes });

const tokenizeCode = async (code: string, language: string) => {
  const instance = await getHighlighter();

  return tokenize(instance, await resolveLanguage(instance, language), code);
};

const cache = new Map<string, { result: TokensResult; size: number }>();
const requests = new Map<string, Promise<TokensResult>>();
let cacheSize = 0;
const maxCacheSize = 2 * 1024 * 1024;

const remember = (key: string, code: string, result: TokensResult) => {
  const size = code.length * 2 + JSON.stringify(result.tokens).length * 2;

  if (size > maxCacheSize) {
    return;
  }

  cache.set(key, { result, size });
  cacheSize += size;

  while (cache.size > 100 || cacheSize > maxCacheSize) {
    const oldest = cache.keys().next().value;

    if (oldest === undefined) {
      break;
    }

    cacheSize -= cache.get(oldest)?.size ?? 0;
    cache.delete(oldest);
  }
};

const tokenizeAndRemember = async (key: string, code: string, language: string) => {
  const result = await tokenizeCode(code, language);
  remember(key, code, result);

  return result;
};

export const highlightCode = async (code: string, language: string): Promise<TokensResult> => {
  const normalized = normalizeCodeLanguage(language);
  const key = `${normalized}\u0000${code}`;
  const cached = cache.get(key);

  if (cached) {
    cache.delete(key);
    cache.set(key, cached);

    return cached.result;
  }

  const pending = requests.get(key);

  if (pending) {
    return await pending;
  }

  const request = tokenizeAndRemember(key, code, normalized);
  requests.set(key, request);

  try {
    return await request;
  } finally {
    requests.delete(key);
  }
};

/** Highlighted source that can be continued as the source grows. */
export interface CodeHighlight {
  code: string;
  /** The normalized language. */
  language: string;
  result: TokensResult;
  /**
   * Where the complete lines end, how many there are, and the grammar state after them. Absent
   * for a result from the shared cache; the next growth then highlights the source once in full.
   */
  checkpoint?: { length: number; lines: number; state: GrammarState | undefined };
}

const finalLineBreak = /(?:\r\n|\n|\r)$/u;

/** The length of the source's complete lines, through the last line break. */
const completeLength = (code: string) =>
  Math.max(code.lastIndexOf("\n"), code.lastIndexOf("\r")) + 1;

// Tokenizes only what follows the previous checkpoint: the new complete lines from the saved
// grammar state, then the unfinished last line from the state after them.
const continueHighlight = async (
  previous: CodeHighlight,
  code: string,
  language: string,
): Promise<CodeHighlight> => {
  const instance = await getHighlighter();
  const lang = await resolveLanguage(instance, language);
  const checkpoint = previous.checkpoint ?? { length: 0, lines: 0, state: undefined };
  const end = completeLength(code);

  let { state } = checkpoint;
  let lines = previous.result.tokens.slice(0, checkpoint.lines);

  if (end > checkpoint.length) {
    const complete = tokenize(
      instance,
      lang,
      code.slice(checkpoint.length, end).replace(finalLineBreak, ""),
      state,
    );

    lines = [...lines, ...complete.tokens];
    state = complete.grammarState;
  }

  const tail = tokenize(instance, lang, code.slice(end), state);

  return {
    checkpoint: { length: end, lines: lines.length, state },
    code,
    language,
    result: { ...tail, tokens: [...lines, ...tail.tokens] },
  };
};

/**
 * Highlights `code`, continuing from `previous` when the source has grown from it, as streamed
 * output does. Other changes highlight the source in full through the shared cache.
 */
export const updateCodeHighlight = async (
  previous: CodeHighlight | undefined,
  code: string,
  language: string,
): Promise<CodeHighlight> => {
  const normalized = normalizeCodeLanguage(language);

  if (
    previous !== undefined &&
    previous.language === normalized &&
    code.length > previous.code.length &&
    code.startsWith(previous.code) &&
    // A trailing CR may be half of a CRLF the next chunk completes.
    !previous.code.endsWith("\r")
  ) {
    return await continueHighlight(previous, code, normalized);
  }

  return { code, language: normalized, result: await highlightCode(code, normalized) };
};

import type { ComponentProps, ReactNode } from "react";
import { DirectionProvider } from "@/registry/erbium/ui/direction";
