interface CodePanelLine {
  /** The line number shown in the gutter; none when line numbers are off. */
  number?: number;
  text: string;
  /** Highlighted content for the line. `text` is shown when it is absent. */
  content?: ReactNode;
  /**
   * Diff changes, `highlight` to call out a line, or `separator` for the bar a diff draws over
   * collapsed unchanged lines.
   */
  tone?: "addition" | "deletion" | "highlight" | "separator";
}

// Rows the panel body can show before it scrolls; later rows stay out of view, so plain fallbacks
// and skeletons stop there.
const codePanelLineLimit = 200;

interface CodePanelLinesProps {
  lines: CodePanelLine[];
  className?: string;
  /** Wrap long lines inside the code column instead of scrolling. */
  wrap?: boolean;
  /** Rows to render. Defaults to the rows a panel shows before it scrolls. */
  limit?: number;
  /**
   * Classes for the code column. With line numbers, or without custom classes, the column starts
   * where Pierre starts its code; code blocks without line numbers pad it to the panel instead.
   */
  codeClassName?: string;
  /**
   * Fewest digits the gutter is sized for. Pierre sizes it by the file's line count, which can
   * exceed the numbers among the rows shown.
   */
  minDigits?: number;
  /** Mark added and removed lines with `+` and `-`, as Pierre's classic diff indicators do. */
  indicators?: boolean;
}

const marker = { addition: "+", deletion: "-" } as const;

/**
 * Source as rows in Pierre's metrics: the same font roles (`text-code-block`), a gutter of the
 * widest number plus three characters (two before the number, one after), and code starting one
 * character later, or two with diff indicators. Code blocks render their highlighted rows through
 * it, and file and diff views show their known source with it until Pierre has rendered, so the
 * swap changes colour, never position.
 */
const CodePanelLines = ({
  lines,
  className,
  wrap = false,
  limit = codePanelLineLimit,
  codeClassName,
  minDigits = 1,
  indicators = false,
}: CodePanelLinesProps) => {
  const shown = lines.slice(0, limit);
  const numbered = shown.some((line) => line.number !== undefined);

  // One gutter width for every row, sized by the widest number.
  const digits = Math.max(
    String(Math.max(...shown.map((line) => line.number ?? 0), 1)).length,
    minDigits,
  );

  const gutter = { minWidth: `${digits + 3}ch`, paddingInline: "2ch 1ch" };

  const codeInset =
    numbered || codeClassName === undefined
      ? { paddingInlineStart: indicators ? "2ch" : "1ch" }
      : undefined;

  return (
    <span
      data-slot="code-panel-lines"
      data-wrap={wrap ? "" : undefined}
      className={cn("grid text-code-block", wrap ? "min-w-0" : "min-w-max", className)}
    >
      {shown.map((line, index) =>
        line.tone === "separator" ? (
          <span
            key={`${index}:separator`}
            aria-hidden="true"
            data-slot="code-panel-line"
            data-tone="separator"
            className="h-8 bg-surface-control"
          />
        ) : (
          <span
            // Rows are positional: a fallback is replaced, never reordered.
            key={`${index}:${line.number ?? ""}`}
            data-slot="code-panel-line"
            data-tone={line.tone}
            className="group/line relative flex min-h-lh data-[tone=addition]:bg-success/8 data-[tone=deletion]:bg-error/8 data-[tone=highlight]:bg-primary/8"
          >
            {line.tone === "highlight" ? (
              // The edge marker keeps a highlighted line distinct without relying on its tint.
              <span aria-hidden="true" className="absolute inset-y-0 start-0 w-0.5 bg-primary" />
            ) : null}
            {numbered ? (
              <span
                aria-hidden="true"
                className="shrink-0 select-none text-end text-muted-foreground tabular-nums group-data-[tone=highlight]/line:text-foreground"
                style={gutter}
              >
                {line.number}
              </span>
            ) : null}
            <span
              className={cn(
                "relative min-w-0",
                codeClassName ?? "pe-4",
                wrap ? "whitespace-pre-wrap wrap-break-word" : "whitespace-pre",
              )}
              style={codeInset}
            >
              {indicators && (line.tone === "addition" || line.tone === "deletion") ? (
                <span
                  aria-hidden="true"
                  data-tone={line.tone}
                  className="absolute start-0 top-0 select-none data-[tone=addition]:text-success data-[tone=deletion]:text-error"
                >
                  {marker[line.tone]}
                </span>
              ) : null}
              {/* A blank row holds a newline so a copied selection keeps it. */}
              {line.content ?? (line.text === "" ? "\n" : line.text)}
            </span>
          </span>
        ),
      )}
    </span>
  );
};

/**
 * Numbered rows for a file's source. Like Pierre, `\r\n`, `\n`, and `\r` each end a line, and a final
 * line break ends with an empty row.
 */
const sourceLines = (source: string, numbered = true): CodePanelLine[] =>
  source
    .split(/\r\n|\n|\r/u)
    .slice(0, codePanelLineLimit)
    .map((text, index) => ({ number: numbered ? index + 1 : undefined, text }));

// Generic lines for source that is not known yet, measured into a skeleton.
const placeholderLines = sourceLines(
  [
    'import { createThing } from "./thing";',
    "",
    "export const configure = (options) => {",
    "  const thing = createThing(options);",
    "  thing.start();",
    "",
    "  return thing;",
    "};",
  ].join("\n"),
);

type CodePanelContentProps = Omit<ComponentProps<"section">, "dir" | "dangerouslySetInnerHTML"> & {
  /**
   * Shown in place of the rendered code until the renderer has produced output. Pass the known
   * source as `CodePanelLines` so it reads at once and highlighting lands without a loading state.
   */
  fallback?: ReactNode;
  /**
   * The source itself is not known yet (it is being fetched). Draws a skeleton of code lines.
   * Prefer `fallback` whenever the source is in hand.
   */
  loading?: boolean;
  /** Replaces the body when there is nothing to render. */
  empty?: ReactNode;
};

const CodePanelContent = ({
  fallback,
  loading,
  empty,
  children,
  className,
  ...props
}: CodePanelContentProps) => {
  const showEmpty = empty !== undefined && empty !== null && empty !== false;
  let body: ReactNode = empty;

  if (!showEmpty) {
    body =
      loading === true ? (
        <Skeleton loading label="Loading code">
          <CodePanelLines lines={placeholderLines} />
        </Skeleton>
      ) : (
        // The renderer's host is empty until its first render, so the fallback holds the code's
        // place and the highlighted code lands where it was.
        <>
          {fallback}
          {children}
        </>
      );
  }

  return (
    <section
      aria-busy={loading === true ? true : undefined}
      data-slot="code-panel-content"
      {...props}
      dir="ltr"
      className={cn(
        "max-h-120 min-w-0 overflow-auto bg-surface-panel",
        codePanelFocusRing,
        className,
      )}
    >
      {body}
    </section>
  );
};

const CodePanelEmpty = ({ title, description }: { title: ReactNode; description?: ReactNode }) => (
  <Empty className="rounded-none border-0 p-panel sm:p-panel">
    <EmptyHeader>
      <EmptyTitle>{title}</EmptyTitle>
      {description !== undefined && description !== null ? (
        <EmptyDescription>{description}</EmptyDescription>
      ) : null}
    </EmptyHeader>
  </Empty>
);

export {
  CodePanel,
  CodePanelHeader,
  CodePanelTitle,
  CodePanelActions,
  CodePanelCopyButton,
  CodePanelContent,
  CodePanelEmpty,
  CodePanelLines,
  sourceLines,
  codePanelFocusRing,
  codePanelHeader,
  codePanelSurface,
  codePanelTitle,
};

export type { CodePanelProps, CodePanelContentProps, CodePanelLine, CodePanelLinesProps };

