/*
 * A data table is a table built by `useDataTable`, given to `DataTable`,
 * and composed from the parts below. Every part reads the table from context:
 *
 *   <DataTable table={table}>
 *     <DataTableToolbar>
 *       <DataTableSearch />
 *       <DataTableFilters />
 *       <DataTableViewOptions />
 *     </DataTableToolbar>
 *     <DataTableContent loading={query.isFetching} />
 *     <DataTablePagination />
 *     <DataTableActionBar>…</DataTableActionBar>
 *   </DataTable>
 */

type Column = ReturnType<DataTableInstance["getAllLeafColumns"]>[number];

type Header = ReturnType<DataTableInstance["getFlatHeaders"]>[number];

const isText = <TValue,>(value: TValue): value is TValue & string => typeof value === "string";

/** A column's name in menus: its `meta.label`, its string header, or its id. */
const columnLabel = (column: Column) => {
  const { header, meta } = column.columnDef;

  return meta?.label ?? meta?.filter?.label ?? (isText(header) ? header : column.id);
};

interface DataTableProps<TData extends RowData> extends React.ComponentProps<"div"> {
  table: DataTableInstance<TData>;
  /**
   * Opens a row, such as its detail page, when the row is clicked. Clicks on a control in the row
   * (a checkbox, a menu, a link) are left to that control. Rows are not focusable, so also render
   * a link to the row in one of its cells for keyboards and for opening it in a new tab.
   */
  onRowClick?: (row: Row<DataTableFeatures, TData>) => void;
}

/** Opens a row by id, when the table's rows can be opened. */
const RowClickContext = React.createContext<((rowId: string) => void) | undefined>(undefined);

/** The rows on screen are being replaced, so their selection is not shown. */
const LoadingContext = React.createContext(false);

const interactive =
  "a, button, input, label, select, textarea, [contenteditable], [role=button], [role=checkbox], [role=menuitem], [role=switch]";

/** A click on the row itself: not on a control inside it, nor in a menu it opened, nor a text selection. */
const isRowClick = ({ target, currentTarget }: React.MouseEvent<HTMLElement>) => {
  if (!(target instanceof Element) || !currentTarget.contains(target)) {
    return false;
  }

  const control = target.closest(interactive);

  return (
    (control === null || !currentTarget.contains(control)) &&
    globalThis.getSelection()?.type !== "Range"
  );
};

/** Provides the table to its parts, which read it from context. */
const DataTable = <TData extends RowData>({
  table,
  onRowClick,
  className,
  ...props
}: DataTableProps<TData>) => {
  const openRowById = React.useCallback(
    (rowId: string) => {
      onRowClick?.(table.getRow(rowId, true));
    },
    [onRowClick, table],
  );

  const openRow = onRowClick === undefined ? undefined : openRowById;

  return (
    <table.AppTable>
      <RowClickContext value={openRow}>
        <div
          data-slot="data-table"
          className={cn("flex w-full min-w-0 flex-col gap-group", className)}
          {...props}
        />
      </RowClickContext>
    </table.AppTable>
  );
};

/** The row of search, filters and view options above the table. Stays readable while rows load. */
const DataTableToolbar = ({ className, ...props }: React.ComponentProps<"div">) => (
  <div
    data-slot="data-table-toolbar"
    className={cn("flex flex-wrap items-center gap-related", className)}
    {...props}
  />
);

/**
 * Searches every column. A server table waits for a pause in typing before it asks for rows;
 * a browser table filters on each keystroke.
 */
const DataTableSearch = ({
  placeholder = "Search",
  className,
}: {
  placeholder?: string;
  className?: string;
}) => {
  const table = useDataTableContext();
  const value = String(table.state.globalFilter ?? "");
  const [draft, setDraft] = React.useState(value);
  const [seen, setSeen] = React.useState(value);

  // The search changed elsewhere, such as Back or a cleared filter: show it.
  if (value !== seen) {
    setSeen(value);
    setDraft(value);
  }

  const commit = useDebouncedCallback(
    (next: string) => {
      table.setGlobalFilter(next);
    },
    { wait: table.options.manualFiltering === true ? 300 : 0 },
  );

  const change = (next: string) => {
    setDraft(next);
    commit(next);
  };

  return (
    <InputGroup data-slot="data-table-search" className={cn("w-full sm:max-w-64", className)}>
      <InputGroupAddon>
        <Icon name="search-01" aria-hidden="true" />
      </InputGroupAddon>
      <InputGroupInput
        type="search"
        aria-label={placeholder}
        placeholder={placeholder}
        value={draft}
        onChange={(event) => {
          change(event.target.value);
        }}
      />
      {draft === "" ? null : (
        <InputGroupAddon align="inline-end">
          <InputGroupButton
            size="icon-xs"
            aria-label="Clear search"
            onClick={() => {
              change("");
            }}
          >
            <Icon name="x" aria-hidden="true" />
          </InputGroupButton>
        </InputGroupAddon>
      )}
    </InputGroup>
  );
};

interface DataTableFiltersProps extends Omit<React.ComponentProps<"div">, "children"> {
  /**
   * Option counts by column id, for a server table: it holds one page, so counts it derives would
   * describe that page rather than every row.
   */
  counts?: Partial<Record<string, Map<string, number>>>;
}

/** Filter chips for the columns with a `meta.filter` config: an add-filter menu, then a chip per rule. */
const DataTableFilters = ({ counts, ...props }: DataTableFiltersProps) => {
  const filters = useTableFilters(useDataTableContext(), { counts });

  return <FilterBar filters={filters} {...props} />;
};

/** A filter button per filterable column, for tables with a few fixed filters. */
const DataTableFacets = ({
  counts,
  fields,
  ...props
}: DataTableFiltersProps & { fields?: string[] }) => {
  const filters = useTableFilters(useDataTableContext(), { counts });

  return <FilterFacets filters={filters} fields={fields} {...props} />;
};

/** Shows and hides columns. Lists every data column that can be hidden. */
const DataTableViewOptions = ({ className }: { className?: string }) => {
  const table = useDataTableContext();

  const columns = table
    .getAllLeafColumns()
    .filter((column) => column.accessorFn !== undefined && column.getCanHide());

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={<Button variant="outline" size="sm" className={cn("ms-auto", className)} />}
      >
        <Icon name="settings-01" aria-hidden="true" data-icon="inline-start" />
        View
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        <DropdownMenuGroup>
          <DropdownMenuLabel>Columns</DropdownMenuLabel>
          {columns.map((column) => (
            <DropdownMenuCheckboxItem
              key={column.id}
              checked={column.getIsVisible()}
              onCheckedChange={(checked) => {
                column.toggleVisibility(checked);
              }}
            >
              {columnLabel(column)}
            </DropdownMenuCheckboxItem>
          ))}
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
};

const ariaSort = { asc: "ascending", desc: "descending" } as const;

/**
 * A header cell's content. A column that can be sorted or hidden opens a menu with those actions;
 * the current sort shows as an arrow.
 */
const DataTableColumnHeader = ({ header }: { header: Header }) => {
  const { column } = header;
  const canSort = column.getCanSort();
  const canHide = column.accessorFn !== undefined && column.getCanHide();
  const sorted = column.getIsSorted();
  const content = <FlexRender header={header} />;

  if (!canSort && !canHide) {
    return content;
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={<Button variant="ghost" size="xs" className="-mx-2 font-medium" />}
      >
        {content}
        {sorted === false ? null : (
          <Icon
            name={sorted === "asc" ? "arrow-up-01" : "arrow-down-01"}
            aria-hidden="true"
            data-icon="inline-end"
          />
        )}
      </DropdownMenuTrigger>
      <DropdownMenuContent align={column.columnDef.meta?.align === "end" ? "end" : "start"}>
        {canSort ? (
          <DropdownMenuGroup>
            <DropdownMenuItem
              onClick={() => {
                column.toggleSorting(false);
              }}
            >
              <Icon name="arrow-up-01" aria-hidden="true" />
              Sort ascending
            </DropdownMenuItem>
            <DropdownMenuItem
              onClick={() => {
                column.toggleSorting(true);
              }}
            >
              <Icon name="arrow-down-01" aria-hidden="true" />
              Sort descending
            </DropdownMenuItem>
            {sorted === false ? null : (
              <DropdownMenuItem
                onClick={() => {
                  column.clearSorting();
                }}
              >
                <Icon name="x" aria-hidden="true" />
                Clear sort
              </DropdownMenuItem>
            )}
          </DropdownMenuGroup>
        ) : null}
        {canSort && canHide ? <DropdownMenuSeparator /> : null}
        {canHide ? (
          <DropdownMenuItem
            onClick={() => {
              column.toggleVisibility(false);
            }}
          >
            <Icon name="eye-off" aria-hidden="true" />
            Hide column
          </DropdownMenuItem>
        ) : null}
      </DropdownMenuContent>
    </DropdownMenu>
  );
};

/** The empty state: offers to clear the search and filters when they hide every row. */
const DataTableEmpty = () => {
  const table = useDataTableContext();
  const filtered = table.state.columnFilters.length > 0 || table.state.globalFilter !== "";

  return (
    <Empty className="border-0">
      <EmptyHeader>
        <EmptyTitle>{filtered ? "No matching rows" : "No rows yet"}</EmptyTitle>
        <EmptyDescription>
          {filtered ? "Change the search or filters." : "Rows appear here once they are added."}
        </EmptyDescription>
      </EmptyHeader>
      {filtered ? (
        <EmptyContent>
          <Button
            variant="outline"
            size="sm"
            onClick={() => {
              table.resetColumnFilters(true);
              table.resetGlobalFilter(true);
            }}
          >
            Clear filters
          </Button>
        </EmptyContent>
      ) : null}
    </Empty>
  );
};

interface DataTableContentProps extends React.ComponentProps<"table"> {
  /**
   * The rows are loading. Their skeleton is measured from the rows the table holds: the rows on
   * screen during a refetch, or sample rows (give the table sample data) for the first load. The
   * header is known, so it stays readable.
   */
  loading?: boolean;
  /** Remembers the table's shape across visits under this key, so a reload draws it exactly. */
  id?: string;
  /** Read to screen readers while the rows load. */
  label?: string;
  /** Shown in place of the table when the rows could not load. */
  error?: React.ReactNode | Error;
  /** Shown in the body when there are no rows. Defaults to `DataTableEmpty`. */
  empty?: React.ReactNode;
}

/**
 * The table itself. Columns with a `size` (in pixels) get that width and the table lays out at
 * fixed widths, so sample rows cannot size the columns differently from the rows that replace
 * them; columns without one share the remaining width.
 */
const DataTableContent = ({
  loading = false,
  id,
  label = "Loading rows",
  error,
  empty,
  className,
  ...props
}: DataTableContentProps) => {
  const table = useDataTableContext();
  const openRow = React.use(RowClickContext);
  const columns = table.getVisibleLeafColumns();
  const { rows } = table.getRowModel();
  const sized = columns.some((column) => column.columnDef.size !== undefined);

  return (
    <Skeleton loading={loading} id={id} label={label} error={error}>
      <LoadingContext value={loading}>
        <Table className={cn(sized && "table-fixed", className)} {...props}>
          {sized ? (
            <colgroup>
              {columns.map((column) => (
                <col key={column.id} style={{ width: column.columnDef.size }} />
              ))}
            </colgroup>
          ) : null}
          <TableHeader {...skeletonKnown}>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => {
                  const sorted = header.column.getIsSorted();

                  return (
                    <TableHead
                      key={header.id}
                      colSpan={header.colSpan}
                      aria-sort={sorted === false ? undefined : ariaSort[sorted]}
                      data-align={header.column.columnDef.meta?.align}
                      className="data-[align=end]:text-end"
                    >
                      {header.isPlaceholder ? null : (
                        <div className="flex items-center in-data-[align=end]:justify-end">
                          <DataTableColumnHeader header={header} />
                        </div>
                      )}
                    </TableHead>
                  );
                })}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {rows.length === 0 && !loading ? (
              <TableRow className="hover:bg-transparent">
                <TableCell colSpan={columns.length} className="p-0 whitespace-normal">
                  {empty ?? <DataTableEmpty />}
                </TableCell>
              </TableRow>
            ) : (
              rows.map((row) => (
                <TableRow
                  key={row.id}
                  // The selected tint is a cell background, which the skeleton would draw as a
                  // block over the row, so loading rows show plain; it returns with the rows.
                  data-state={!loading && row.getIsSelected() ? "selected" : undefined}
                  className={cn(openRow !== undefined && "cursor-pointer")}
                  onClick={
                    openRow === undefined
                      ? undefined
                      : (event) => {
                          if (isRowClick(event)) {
                            openRow(row.id);
                          }
                        }
                  }
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell
                      key={cell.id}
                      data-align={cell.column.columnDef.meta?.align}
                      // Fixed layout gives columns their width regardless of content, so
                      // unwrapped text would run into the next column; clip it with an
                      // ellipsis. Cells holding controls keep overflow visible for focus rings.
                      className={cn(
                        "data-[align=end]:text-end",
                        sized && "not-has-[button,[role=checkbox]]:truncate",
                      )}
                    >
                      <FlexRender cell={cell} />
                    </TableCell>
                  ))}
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </LoadingContext>
    </Skeleton>
  );
};

/**
 * The row count, the page size and the page controls. Counts selected rows while any are
 * selected.
 */
const DataTablePagination = ({
  pageSizes = dataTablePageSizes,
  className,
  ...props
}: React.ComponentProps<"div"> & { pageSizes?: readonly number[] }) => {
  const table = useDataTableContext();
  const { pageIndex, pageSize } = table.state.pagination;
  const rowCount = table.getRowCount();
  const selected = table.getSelectedRowIds().length;
  const sizes = pageSizes.includes(pageSize) ? pageSizes : [pageSize, ...pageSizes];

  return (
    <div
      data-slot="data-table-pagination"
      className={cn(
        "flex flex-wrap items-center justify-between gap-related text-caption text-muted-foreground",
        className,
      )}
      {...props}
    >
      <span aria-live="polite" className="tabular-nums">
        {selected > 0
          ? `${selected.toLocaleString()} of ${rowCount.toLocaleString()} selected`
          : `${rowCount.toLocaleString()} ${rowCount === 1 ? "row" : "rows"}`}
      </span>
      <div className="flex flex-wrap items-center gap-related">
        <Select
          value={pageSize}
          items={sizes.map((size) => ({ label: `${size} per page`, value: size }))}
          onValueChange={(size) => {
            if (size !== null) {
              table.setPageSize(size);
            }
          }}
        >
          <SelectTrigger size="sm" aria-label="Rows per page">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {sizes.map((size) => (
              <SelectItem key={size} value={size}>
                {size} per page
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        <Pagination className="mx-0 w-auto">
          <PaginationControls
            page={pageIndex + 1}
            pageCount={Math.max(table.getPageCount(), 1)}
            onPageChange={(page) => {
              table.setPageIndex(page - 1);
            }}
          />
        </Pagination>
      </div>
    </div>
  );
};

/** Actions for the selected rows. Shown while rows are selected; read them with `useDataTableContext`. */
const DataTableActionBar = ({ className, children, ...props }: React.ComponentProps<"div">) => {
  const table = useDataTableContext();
  const selected = table.getSelectedRowIds().length;

  if (selected === 0) {
    return null;
  }

  return (
    <div
      role="toolbar"
      aria-label="Selected rows"
      data-slot="data-table-action-bar"
      className={cn(
        "sticky bottom-4 z-10 mx-auto flex w-fit items-center gap-related rounded-xl surface-overlay p-1 ps-3 text-caption animate-in fade-in-0 slide-in-from-bottom-2 motion-reduce:animate-none",
        className,
      )}
      {...props}
    >
      <span className="tabular-nums">{selected.toLocaleString()} selected</span>
      <Separator orientation="vertical" className="h-4" />
      {children}
      <Button
        variant="ghost"
        size="icon-sm"
        aria-label="Clear selection"
        onClick={() => {
          table.resetRowSelection(true);
        }}
      >
        <Icon name="x" aria-hidden="true" />
      </Button>
    </div>
  );
};

/**
 * The header of a selection column: selects every row on the page. Checked when every row on the
 * page is selected, and mixed while any row is selected, on this page or another, so a selection
 * made elsewhere stays in view.
 */
const DataTableSelectAll = <TData extends RowData>({
  table,
}: HeaderContext<DataTableFeatures, TData>) => {
  // While rows load, the page they belong to is not on screen yet, so the header cannot say
  // whether all of them are selected, nor select the rows being replaced.
  const loading = React.use(LoadingContext);

  return (
    // Rows and the table keep their identity when the selection changes, so the checkbox
    // subscribes to the selection to render again.
    <Subscribe source={table.atoms.rowSelection}>
      {() => {
        const all = !loading && table.getIsAllPageRowsSelected();

        return (
          <Checkbox
            aria-label="Select all rows on this page"
            checked={all}
            indeterminate={!all && table.getSelectedRowIds().length > 0}
            disabled={loading}
            onCheckedChange={(checked) => {
              table.toggleAllPageRowsSelected(checked);
            }}
          />
        );
      }}
    </Subscribe>
  );
};

/** The cell of a selection column: selects its row. */
const DataTableSelectRow = <TData extends RowData>({
  row,
  table,
}: CellContext<DataTableFeatures, TData>) => (
  <Subscribe source={table.atoms.rowSelection}>
    {() => (
      <Checkbox
        aria-label="Select row"
        checked={row.getIsSelected()}
        disabled={!row.getCanSelect()}
        onCheckedChange={(checked) => {
          row.toggleSelected(checked);
        }}
      />
    )}
  </Subscribe>
);

export {
  DataTable,
  DataTableActionBar,
  DataTableColumnHeader,
  DataTableContent,
  DataTableEmpty,
  DataTableFacets,
  DataTableFilters,
  DataTablePagination,
  DataTableSearch,
  DataTableSelectAll,
  DataTableSelectRow,
  DataTableToolbar,
  DataTableViewOptions,
};

export type { DataTableContentProps, DataTableFiltersProps, DataTableProps };

import type { ColumnFiltersState, PaginationState, SortingState } from "@tanstack/react-table";
import { getColumnFilterFields, parseFilterSearch, toFilterSearch } from "@/registry/erbium/lib/filter-search";
import type { FilterSearchColumn, FilterSearchFields, SearchParams } from "@/registry/erbium/lib/filter-search";

/*
 * The URL form of a data table's query, so a sorted, filtered page of a table is a link:
 *
 *   ?q=acme&sort=issued.desc,customer&page=2&size=20&status=paid,overdue
 *
 * `q` is the search, `sort` the sort order (`.desc` marks a descending column), `page` the
 * 1-based page, `size` the page size, and each filterable column keeps its rule under its id.
 * Defaults are left out of the URL. A route with two tables gives each a `prefix`, which names
 * its params `users.q`, `users.page` and so on. These functions are pure, so a route loader can
 * parse the same search the table reads.
 */

/** The page sizes a table offers. */
const dataTablePageSizes = [10, 20, 30, 50, 100] as const;

/** Everything a server needs to answer for one page of a table. */
interface DataTableQuery {
  globalFilter: string;
  sorting: SortingState;
  columnFilters: ColumnFiltersState;
  pagination: PaginationState;
}

/** The parts of a column definition the codec reads. */
interface DataTableSearchColumn extends FilterSearchColumn {
  enableSorting?: boolean;
  /** Only its presence is read: a column with an accessor holds a value it can sort by. */
  accessorFn?: (row: never, index: number) => void;
  columns?: readonly DataTableSearchColumn[];
}

/** A table's columns and defaults. Share one object between the route and the table. */
interface DataTableSearchConfig {
  columns: readonly DataTableSearchColumn[];
  /** The order rows have when the URL names none. */
  defaultSorting?: SortingState;
  /** The page size when the URL names none. */
  defaultPageSize?: number;
  /**
   * Prefixes the table's params, for a route with more than one table: `prefix: "users"` writes
   * `?users.q=…&users.page=2`. Left out, the params are unprefixed.
   */
  prefix?: string;
}

type ParamValue = SearchParams[string];

/** A route's search params, with the table's own in their normal form. */
type DataTableSearchParams = Partial<Record<string, string | number | boolean>>;

const noSorting: SortingState = [];
const fallbackPageSize = 10;

/** What the codec derives from a column list, kept per list since columns are module constants. */
interface Schema {
  filterFields: FilterSearchFields;
  sortable: Set<string>;
}

const schemas = new WeakMap<readonly DataTableSearchColumn[], Schema>();

const collectSortable = (columns: readonly DataTableSearchColumn[], ids: Set<string>) => {
  for (const column of columns) {
    // TanStack makes an id from an accessor key, writing nested keys' dots as underscores.
    const id = column.id ?? column.accessorKey?.toString().replaceAll(".", "_");
    const hasValue = column.accessorKey !== undefined || column.accessorFn !== undefined;

    if (id !== undefined && hasValue && column.enableSorting !== false) {
      ids.add(id);
    }

    if (column.columns !== undefined) {
      collectSortable(column.columns, ids);
    }
  }

  return ids;
};

const getSchema = (columns: readonly DataTableSearchColumn[]): Schema => {
  const cached = schemas.get(columns);

  if (cached !== undefined) {
    return cached;
  }

  const schema = {
    filterFields: getColumnFilterFields(columns),
    sortable: collectSortable(columns, new Set()),
  };

  schemas.set(columns, schema);

  return schema;
};

const toText = (value: ParamValue) => (value === null || value === undefined ? "" : String(value));

const toPositiveInteger = (value: ParamValue) => {
  const number = Number(value);

  return Number.isInteger(number) && number > 0 ? number : undefined;
};

const parseSorting = (value: ParamValue, sortable: Set<string>): SortingState =>
  toText(value)
    .split(",")
    .flatMap((part) => {
      const [id = "", direction] = part.split(".");

      return sortable.has(id) ? [{ desc: direction === "desc", id }] : [];
    });

const encodeSorting = (sorting: SortingState) =>
  sorting.map(({ id, desc }) => (desc ? `${id}.desc` : id)).join(",");

/** The table's own params, read without their prefix. */
const unprefix = (search: SearchParams, prefix: string | undefined): SearchParams =>
  prefix === undefined
    ? search
    : Object.fromEntries(
        Object.entries(search).flatMap(([key, value]) =>
          key.startsWith(`${prefix}.`) ? [[key.slice(prefix.length + 1), value]] : [],
        ),
      );

const withPrefix = <TValue>(params: Record<string, TValue>, prefix: string | undefined) =>
  prefix === undefined
    ? params
    : Object.fromEntries(Object.entries(params).map(([key, value]) => [`${prefix}.${key}`, value]));

const getDefaultPageSize = (config: DataTableSearchConfig) =>
  config.defaultPageSize ?? fallbackPageSize;

const isPageSize = (size: number, config: DataTableSearchConfig) =>
  size === getDefaultPageSize(config) || dataTablePageSizes.some((option) => option === size);

/** The query a search holds, with the table's defaults where the URL names none. */
const parseDataTableSearch = (
  params: SearchParams,
  config: DataTableSearchConfig,
): DataTableQuery => {
  const { filterFields, sortable } = getSchema(config.columns);
  const search = unprefix(params, config.prefix);
  const size = toPositiveInteger(search.size);
  const sorting = parseSorting(search.sort, sortable);

  return {
    columnFilters: parseFilterSearch(search, filterFields),
    globalFilter: toText(search.q),
    pagination: {
      pageIndex: (toPositiveInteger(search.page) ?? 1) - 1,
      pageSize: size !== undefined && isPageSize(size, config) ? size : getDefaultPageSize(config),
    },
    sorting: sorting.length > 0 ? sorting : (config.defaultSorting ?? noSorting),
  };
};

/**
 * The search params for a query: one entry per param the table owns, `undefined` where the
 * query holds the default. Merge it into the current search so other params are kept. An empty
 * sort goes back to the default sort.
 */
const toDataTableSearch = (query: DataTableQuery, config: DataTableSearchConfig) => {
  const { filterFields } = getSchema(config.columns);
  const sort = encodeSorting(query.sorting);
  const { pageIndex, pageSize } = query.pagination;

  return withPrefix(
    {
      ...toFilterSearch(query.columnFilters, filterFields),
      page: pageIndex > 0 ? pageIndex + 1 : undefined,
      q: query.globalFilter === "" ? undefined : query.globalFilter,
      size: pageSize === getDefaultPageSize(config) ? undefined : pageSize,
      sort:
        sort === "" || sort === encodeSorting(config.defaultSorting ?? noSorting)
          ? undefined
          : sort,
    },
    config.prefix,
  );
};

/**
 * A route's `validateSearch` for a table: writes the table's params in their normal form, drops
 * the ones that do not fit its columns or hold a default, and keeps every other param.
 *
 * ```ts
 * createFileRoute("/invoices")({ validateSearch: validateDataTableSearch(invoicesTable) })
 * ```
 */
const validateDataTableSearch =
  (config: DataTableSearchConfig) =>
  (search: SearchParams): DataTableSearchParams => {
    const params = toDataTableSearch(parseDataTableSearch(search, config), config);

    return Object.fromEntries(
      Object.entries({ ...search, ...params }).filter(
        (entry): entry is [string, string | number | boolean] =>
          entry[1] !== undefined && entry[1] !== null,
      ),
    );
  };

export { dataTablePageSizes, parseDataTableSearch, toDataTableSearch, validateDataTableSearch };

export type { DataTableQuery, DataTableSearchColumn, DataTableSearchConfig, DataTableSearchParams };

/*
 * Calendar-day helpers shared by Calendar and DatePicker. Values are local
 * calendar days (midnight in the user's time zone), matching DayPicker.
 * Formatting uses Intl; parsing reads Gregorian dates in the locale's order.
 */

import type { DateRange } from "@daypicker/react";

type NumericField = "day" | "month" | "year";

const defaultFormat: Intl.DateTimeFormatOptions = { dateStyle: "medium" };

/** Separates the two ends of a typed range: an en dash, hyphen, or "to". */
const rangeSeparator = /\s+[–—-]\s+|\s+to\s+/iu;

const numericOrders = new Map<string, NumericField[]>();
const monthNameLists = new Map<string, string[][]>();

const cacheKey = (locale: string | undefined) => locale ?? "";

/** The order of day, month, and year in the locale's numeric date format. */
const numericOrder = (locale: string | undefined): NumericField[] => {
  const key = cacheKey(locale);
  const cached = numericOrders.get(key);

  if (cached) {
    return cached;
  }

  const order = new Intl.DateTimeFormat(locale, {
    calendar: "gregory",
    day: "numeric",
    month: "numeric",
    year: "numeric",
  })
    .formatToParts(new Date(2000, 10, 22))
    .flatMap((part) =>
      part.type === "day" || part.type === "month" || part.type === "year" ? [part.type] : [],
    );

  numericOrders.set(key, order);

  return order;
};

/** Long and short month names of the locale, with English as a fallback. */
const monthNames = (locale: string | undefined): string[][] => {
  const key = cacheKey(locale);
  const cached = monthNameLists.get(key);

  if (cached) {
    return cached;
  }

  const formatters = [locale, "en"].flatMap((tag) =>
    (["long", "short"] as const).map(
      (month) => new Intl.DateTimeFormat(tag, { calendar: "gregory", month }),
    ),
  );

  const names = Array.from({ length: 12 }, (_, month) =>
    formatters.map((formatter) =>
      formatter
        .format(new Date(2000, month, 1))
        .toLocaleLowerCase()
        .replaceAll(/[^\p{L}]/gu, ""),
    ),
  );

  monthNameLists.set(key, names);

  return names;
};

/** Converts Arabic-Indic and Persian digits to ASCII digits. */
const normalizeDigits = (text: string) =>
  text.replaceAll(/[٠-٩۰-۹]/gu, (digit) => {
    const code = digit.codePointAt(0) ?? 0;

    return String(code - (code >= 0x6_f0 ? 0x6_f0 : 0x6_60));
  });

/** Two-digit years map to 1950–2049. */
const expandYear = (token: string) => {
  const year = Number(token);

  if (token.length > 2) {
    return year;
  }

  return year < 50 ? 2000 + year : 1900 + year;
};

/** Builds a local date, rejecting overflow such as February 30. */
const toDate = (year: number, month: number, day: number): Date | undefined => {
  const date = new Date(year, month, day);

  // The Date constructor maps years 0–99 to 1900–1999.
  date.setFullYear(year, month, day);

  return date.getFullYear() === year && date.getMonth() === month && date.getDate() === day
    ? date
    : undefined;
};

const monthIndex = (word: string, locale: string | undefined) =>
  word.length < 3
    ? -1
    : monthNames(locale).findIndex((names) => names.some((name) => name.startsWith(word)));

/**
 * Formats a calendar day with Intl.
 *
 * @param date Day to format.
 * @param locale BCP 47 locale; the user's locale when omitted.
 * @param options Intl options; `dateStyle: "medium"` by default.
 * @returns Formatted day.
 */
const formatDate = (
  date: Date,
  locale?: string,
  options: Intl.DateTimeFormatOptions = defaultFormat,
): string => new Intl.DateTimeFormat(locale, options).format(date);

/**
 * Formats both ends of a range so the result can be parsed back.
 *
 * @param range Range to format.
 * @param locale BCP 47 locale; the user's locale when omitted.
 * @param options Intl options; `dateStyle: "medium"` by default.
 * @returns Formatted range, or an empty string without a start.
 */
const formatDateRange = (
  range: DateRange | undefined,
  locale?: string,
  options: Intl.DateTimeFormatOptions = defaultFormat,
): string => {
  if (!range?.from) {
    return "";
  }

  const from = formatDate(range.from, locale, options);

  return range.to ? `${from} – ${formatDate(range.to, locale, options)}` : from;
};

/**
 * Parses a typed day: ISO (`2026-11-09`), numeric in the locale's order
 * (`11/9/2026` in en-US, `9.11.2026` in de), or with a month name
 * (`Nov 9, 2026`, `9 November 2026`).
 *
 * @param text Typed text.
 * @param locale BCP 47 locale that sets the numeric order and month names.
 * @returns The day, or undefined when the text is not a valid date.
 */
const parseDate = (text: string, locale?: string): Date | undefined => {
  const value = normalizeDigits(text).trim().toLocaleLowerCase();
  const iso = /^(?<year>\d{4})-(?<month>\d{1,2})-(?<day>\d{1,2})$/u.exec(value)?.groups;

  if (iso) {
    return toDate(Number(iso.year), Number(iso.month) - 1, Number(iso.day));
  }

  const numbers = value.match(/\d+/gu) ?? [];
  const words = value.match(/\p{L}+/gu) ?? [];

  if (words.length === 0) {
    if (numbers.length !== 3) {
      return undefined;
    }

    const fields = new Map(numericOrder(locale).map((field, index) => [field, numbers[index]]));
    const year = fields.get("year");
    const month = fields.get("month");
    const day = fields.get("day");

    return year !== undefined && month !== undefined && day !== undefined
      ? toDate(expandYear(year), Number(month) - 1, Number(day))
      : undefined;
  }

  const month = words.map((word) => monthIndex(word, locale)).find((index) => index !== -1);
  const [first, second] = numbers;

  if (month === undefined || first === undefined || second === undefined || numbers.length !== 2) {
    return undefined;
  }

  // The year is the long or out-of-range number; otherwise the day comes first.
  const yearFirst = first.length > 2 || Number(first) > 31;

  return toDate(expandYear(yearFirst ? first : second), month, Number(yearFirst ? second : first));
};

/**
 * Parses a typed range: two days joined by an en dash, a spaced hyphen, or
 * "to". A single day starts an open range.
 *
 * @param text Typed text.
 * @param locale BCP 47 locale that sets the numeric order and month names.
 * @returns The ordered range, or undefined when either end is invalid.
 */
const parseDateRange = (text: string, locale?: string): DateRange | undefined => {
  const parts = text.split(rangeSeparator);

  if (parts.length > 2) {
    return undefined;
  }

  const [start = "", end] = parts;
  const from = parseDate(start, locale);
  const to = end === undefined ? undefined : parseDate(end, locale);

  if (!from || (end !== undefined && !to)) {
    return undefined;
  }

  return to && to < from ? { from: to, to: from } : { from, to };
};

/**
 * Serializes a calendar day as an ISO date (`2026-11-09`) in local time, for
 * form values that must not shift across time zones.
 *
 * @param date Day to serialize.
 * @returns ISO 8601 calendar date.
 */
const toISODate = (date: Date): string =>
  [
    String(date.getFullYear()).padStart(4, "0"),
    String(date.getMonth() + 1).padStart(2, "0"),
    String(date.getDate()).padStart(2, "0"),
  ].join("-");

/**
 * Adds whole days to a calendar day.
 *
 * @param date Starting day.
 * @param amount Days to add; negative values go back.
 * @returns New day.
 */
const addDays = (date: Date, amount: number): Date => {
  const next = new Date(date);

  next.setDate(next.getDate() + amount);

  return next;
};

export { addDays, formatDate, formatDateRange, parseDate, parseDateRange, toISODate };

import * as React from "react";
import type { Popover as PopoverPrimitive } from "@base-ui/react/popover";
import type { DateRange } from "@daypicker/react";
import { formatDate, formatDateRange, parseDate, parseDateRange, toISODate } from "@/registry/erbium/lib/date";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import { Calendar } from "@/registry/erbium/ui/calendar";
import { Icon } from "@/registry/erbium/ui/icon";
import { InputGroup, InputGroupAddon, InputGroupButton, InputGroupInput } from "@/registry/erbium/ui/input-group";
import { Popover, PopoverContent, PopoverTrigger } from "@/registry/erbium/ui/popover";

type DatePickerMode = "single" | "range";

type DatePickerValue = Date | DateRange | undefined;

interface DatePickerContextValue {
  anchor: HTMLElement | null;
  commitText: (text: string) => void;
  disabled: boolean;
  input: HTMLInputElement | null;
  mode: DatePickerMode;
  month: Date;
  selectDay: (day: Date) => void;
  setAnchor: (element: HTMLElement | null) => void;
  setInput: (element: HTMLInputElement | null) => void;
  setMonth: (month: Date) => void;
  setOpen: (open: boolean) => void;
  text: string;
  value: DatePickerValue;
}

const DatePickerContext = React.createContext<DatePickerContextValue | null>(null);

const useDatePicker = (part: string) => {
  const context = React.use(DatePickerContext);

  if (!context) {
    throw new Error(`${part} must be used within DatePicker`);
  }

  return context;
};

const startOf = (value: DatePickerValue) => (value instanceof Date ? value : value?.from);

const placeholders = { range: "Pick a date range", single: "Pick a date" } as const;

const triggerLabels = { range: "Choose date range", single: "Choose date" } as const;

interface DatePickerSharedProps {
  children?: React.ReactNode;
  /** Close the popup when a day, or the end of a range, is picked. */
  closeOnSelect?: boolean;
  defaultOpen?: boolean;
  disabled?: boolean;
  /** Intl options for the displayed value. Defaults to `{ dateStyle: "medium" }`. */
  formatOptions?: Intl.DateTimeFormatOptions;
  /** BCP 47 locale for formatting and parsing typed dates. */
  locale?: string;
  /** Submits the value as an ISO date, or an ISO interval in range mode. */
  name?: string;
  onOpenChange?: (open: boolean) => void;
  open?: boolean;
}

interface DatePickerSingleProps extends DatePickerSharedProps {
  defaultValue?: Date;
  mode?: "single";
  onValueChange?: (value: Date | undefined) => void;
  value?: Date | undefined;
}

interface DatePickerRangeProps extends DatePickerSharedProps {
  defaultValue?: DateRange;
  mode: "range";
  onValueChange?: (value: DateRange | undefined) => void;
  value?: DateRange | undefined;
}

type DatePickerProps = DatePickerSingleProps | DatePickerRangeProps;

const DatePicker = (props: DatePickerProps) => {
  const {
    children,
    closeOnSelect = true,
    defaultOpen = false,
    disabled = false,
    formatOptions,
    locale,
    name,
    onOpenChange,
    open: openProp,
  } = props;

  const mode = props.mode ?? "single";
  const valueControlled = "value" in props;
  const onRangeChange = props.mode === "range" ? props.onValueChange : undefined;
  const onSingleChange = props.mode === "range" ? undefined : props.onValueChange;

  const [uncontrolledValue, setUncontrolledValue] = React.useState<DatePickerValue>(
    props.defaultValue,
  );

  const value = valueControlled ? props.value : uncontrolledValue;

  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(defaultOpen);
  const open = openProp ?? uncontrolledOpen;

  const [month, setMonth] = React.useState(() => startOf(value) ?? new Date());
  const [anchor, setAnchor] = React.useState<HTMLElement | null>(null);
  const [input, setInput] = React.useState<HTMLInputElement | null>(null);

  // The first pick of each open session starts a new range; the second ends it.
  const pendingFrom = React.useRef<Date | undefined>(undefined);

  // The last value the picker set itself. A different value came from outside
  // (presets, resets), so the calendar moves to its month.
  const [ownValue, setOwnValue] = React.useState(value);

  if (value !== ownValue) {
    const start = startOf(value);

    setOwnValue(value);

    if (start) {
      setMonth(start);
    }
  }

  const text =
    value instanceof Date
      ? formatDate(value, locale, formatOptions)
      : formatDateRange(value, locale, formatOptions);

  const formValue =
    value instanceof Date
      ? toISODate(value)
      : [value?.from, value?.to].flatMap((day) => (day ? [toISODate(day)] : [])).join("/");

  const context = React.useMemo<DatePickerContextValue>(() => {
    const setValue = (next: DatePickerValue) => {
      setOwnValue(next);

      if (!valueControlled) {
        setUncontrolledValue(next);
      }

      onRangeChange?.(next instanceof Date ? { from: next, to: undefined } : next);
      onSingleChange?.(next instanceof Date ? next : next?.from);
    };

    const setOpen = (next: boolean) => {
      if (next && disabled) {
        return;
      }

      if (next) {
        pendingFrom.current = undefined;
        setMonth(startOf(value) ?? new Date());
      }

      setUncontrolledOpen(next);
      onOpenChange?.(next);
    };

    const selectDay = (day: Date) => {
      if (mode === "range") {
        const from = pendingFrom.current;

        pendingFrom.current = from ? undefined : day;

        if (!from) {
          setValue({ from: day });

          return;
        }

        setValue(day < from ? { from: day, to: from } : { from, to: day });
      } else {
        setValue(day);
      }

      if (closeOnSelect) {
        setOpen(false);
      }
    };

    const commitText = (typed: string) => {
      if (typed.trim() === "") {
        setValue(undefined);

        return;
      }

      const next = mode === "range" ? parseDateRange(typed, locale) : parseDate(typed, locale);
      const start = startOf(next);

      // Invalid text leaves the value unchanged; the input then shows it again.
      if (next && start) {
        setValue(next);
        setMonth(start);
      }
    };

    return {
      anchor,
      commitText,
      disabled,
      input,
      mode,
      month,
      selectDay,
      setAnchor,
      setInput,
      setMonth,
      setOpen,
      text,
      value,
    };
  }, [
    anchor,
    closeOnSelect,
    disabled,
    input,
    locale,
    mode,
    month,
    onOpenChange,
    onRangeChange,
    onSingleChange,
    text,
    value,
    valueControlled,
  ]);

  return (
    <DatePickerContext value={context}>
      <Popover
        open={open}
        onOpenChange={(next) => {
          context.setOpen(next);
        }}
      >
        {children}
      </Popover>
      {name === undefined ? null : (
        <input type="hidden" name={name} value={formValue} disabled={disabled} />
      )}
    </DatePickerContext>
  );
};

/** Text field that shows the value, accepts typed dates, and opens the calendar. */
const DatePickerInput = ({
  className,
  onBlur,
  onChange,
  onKeyDown,
  placeholder,
  triggerLabel,
  ...props
}: Omit<React.ComponentProps<"input">, "defaultValue" | "type" | "value"> & {
  /** Accessible name of the calendar button. */
  triggerLabel?: string;
}) => {
  // Destructured so the ref callbacks stay separate from the values read in render.
  const { commitText, disabled, mode, setAnchor, setInput, setOpen, text } =
    useDatePicker("DatePickerInput");

  // Typed text while editing; null shows the formatted value.
  const [draft, setDraft] = React.useState<string | null>(null);

  const commit = () => {
    if (draft !== null) {
      commitText(draft);
      setDraft(null);
    }
  };

  return (
    <InputGroup
      ref={setAnchor}
      data-slot="date-picker-input"
      data-disabled={disabled ? "" : undefined}
      className={className}
    >
      <InputGroupInput
        autoComplete="off"
        disabled={disabled}
        placeholder={placeholder ?? placeholders[mode]}
        {...props}
        ref={setInput}
        value={draft ?? text}
        onChange={(event) => {
          onChange?.(event);
          setDraft(event.target.value);
        }}
        onBlur={(event) => {
          onBlur?.(event);
          commit();
        }}
        onKeyDown={(event) => {
          onKeyDown?.(event);

          if (event.defaultPrevented) {
            return;
          }

          if (event.key === "Enter") {
            commit();
          } else if (event.key === "Escape" && draft !== null) {
            event.preventDefault();
            setDraft(null);
          } else if (event.key === "ArrowDown") {
            event.preventDefault();
            commit();
            setOpen(true);
          }
        }}
      />
      <InputGroupAddon align="inline-end">
        <PopoverTrigger
          disabled={disabled}
          render={
            <InputGroupButton size="icon-xs" aria-label={triggerLabel ?? triggerLabels[mode]} />
          }
        >
          <Icon name="calendar-01" />
        </PopoverTrigger>
      </InputGroupAddon>
    </InputGroup>
  );
};

/** Button that shows the value and opens the calendar, for pickers without typing. */
const DatePickerTrigger = ({
  children,
  className,
  placeholder,
  ...props
}: PopoverPrimitive.Trigger.Props & { placeholder?: string }) => {
  const context = useDatePicker("DatePickerTrigger");

  return (
    <PopoverTrigger
      data-slot="date-picker-trigger"
      data-placeholder={context.text === "" ? "" : undefined}
      disabled={context.disabled}
      className={cn(
        "flex w-fit min-w-0 items-center gap-control-gap control-size touch-target rounded-lg border surface-control text-control-sm whitespace-nowrap transition-[color,background-color,box-shadow] duration-150 outline-none select-none motion-reduce:transition-none aria-invalid:border-error aria-invalid:ring-[1.5px] aria-invalid:ring-invalid-halo data-placeholder:text-muted-foreground data-disabled:cursor-not-allowed data-disabled:opacity-50 dark:aria-invalid:border-invalid [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-control-icon",
        className,
      )}
      {...props}
    >
      <Icon name="calendar-01" className="text-muted-foreground" />
      <span className="truncate">
        {children ??
          (context.text === "" ? (placeholder ?? placeholders[context.mode]) : context.text)}
      </span>
    </PopoverTrigger>
  );
};

/** Popup anchored to the input (or the trigger) that holds the calendar. */
const DatePickerContent = ({
  align = "start",
  className,
  ...props
}: React.ComponentProps<typeof PopoverContent>) => {
  const context = useDatePicker("DatePickerContent");
  const popupRef = React.useRef<HTMLDivElement>(null);

  return (
    <PopoverContent
      anchor={context.anchor ?? undefined}
      align={align}
      // Focus the selected day, or today, so arrow keys move through the grid.
      initialFocus={() =>
        popupRef.current?.querySelector<HTMLElement>(
          "[data-slot=calendar] [role=gridcell] button[tabindex='0']",
        ) ?? true
      }
      finalFocus={() => context.input ?? true}
      className={cn("w-auto", className)}
      {...props}
      ref={popupRef}
    />
  );
};

type DatePickerCalendarProps = Omit<
  React.ComponentProps<typeof Calendar>,
  "mode" | "month" | "onMonthChange" | "onSelect" | "required" | "selected"
>;

/** Calendar bound to the picker's value and visible month. */
const DatePickerCalendar = (props: DatePickerCalendarProps) => {
  const context = useDatePicker("DatePickerCalendar");

  const shared = {
    month: context.month,
    onMonthChange: context.setMonth,
  };

  if (context.mode === "range") {
    return (
      <Calendar
        {...props}
        {...shared}
        mode="range"
        selected={context.value instanceof Date ? { from: context.value } : context.value}
        onSelect={(_, day) => {
          context.selectDay(day);
        }}
      />
    );
  }

  return (
    <Calendar
      {...props}
      {...shared}
      mode="single"
      selected={startOf(context.value)}
      onSelect={(_, day) => {
        context.selectDay(day);
      }}
    />
  );
};

export { DatePicker, DatePickerCalendar, DatePickerContent, DatePickerInput, DatePickerTrigger };

