import { parseDiffFromFile, parsePatchFiles } from "@pierre/diffs";
import type { DiffFileInput, FileDiffMetadata } from "@pierre/diffs";
import { FileDiff } from "@pierre/diffs/react";
import type { FileDiffProps, FileDiffOptions } from "@pierre/diffs/react";
import { createContext, use, useMemo, useState } from "react";
import type { ComponentProps, ReactNode } from "react";
import { Icon } from "@/registry/erbium/ui/icon";
import { applyDiffIcons } from "@/registry/erbium/lib/diff-icons";
import { enhanceDiffAccessibility } from "@/registry/erbium/lib/diff-accessibility";
import { fileIconName } from "@/registry/erbium/lib/file-icons";
import { diffTheme, diffThemeCSS } from "@/registry/erbium/lib/diff-theme";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import {
  CodePanel,
  CodePanelActions,
  CodePanelContent,
  CodePanelCopyButton,
  CodePanelEmpty,
  CodePanelHeader,
  CodePanelLines,
  CodePanelTitle,
} from "@/registry/erbium/blocks/code-panel";
import type { CodePanelContentProps, CodePanelLine, CodePanelProps } from "@/registry/erbium/blocks/code-panel";
import type { CopyButtonProps } from "@/registry/erbium/blocks/copy-button";

type OwnedOptions =
  | "theme"
  | "themeType"
  | "unsafeCSS"
  | "disableFileHeader"
  | "renderCustomHeader"
  | "renderHeaderPrefix"
  | "renderHeaderFilenameSuffix"
  | "renderHeaderMetadata";

type DiffViewOptions<Annotation = undefined> = Omit<
  FileDiffOptions<Annotation, undefined>,
  OwnedOptions
>;

type DiffViewSource =
  | (DiffFileInput & { fileDiff?: never; patch?: never })
  | { fileDiff: FileDiffMetadata; oldFile?: never; newFile?: never; patch?: never }
  | {
      /** A unified diff or `git diff` output for one file. */
      patch: string;
      oldFile?: never;
      newFile?: never;
      fileDiff?: never;
    };

/** The one file a patch changes. */
const patchDiff = (patch: string): FileDiffMetadata => {
  const files = parsePatchFiles(patch).flatMap((parsed) => parsed.files);
  const [file] = files;

  if (file === undefined || files.length > 1) {
    throw new Error(
      `DiffView expects a patch for exactly one file; this patch changes ${files.length}.`,
    );
  }

  return file;
};

type DiffViewProps<Annotation = undefined> = DiffViewSource &
  Omit<CodePanelProps, "children"> &
  Pick<
    FileDiffProps<Annotation, undefined>,
    | "lineAnnotations"
    | "selectedLines"
    | "renderAnnotation"
    | "renderGutterUtility"
    | "prerenderedHTML"
    | "metrics"
    | "disableWorkerPool"
  > & {
    options?: DiffViewOptions<Annotation>;
    children?: ReactNode;
  };

interface DiffViewContextValue {
  fileDiff: FileDiffMetadata;
  oldContents: string | undefined;
  newContents: string | undefined;
  content: ReactNode;
  /** False until Pierre has produced its first render; the plain diff shows until then. */
  rendered: boolean;
  /** Pierre's layout and gutter, so the plain diff matches them. */
  split: boolean;
  numbered: boolean;
  /** Pierre's classic `+` and `-` markers are on. */
  indicators: boolean;
  /** The longest gap of unchanged lines Pierre shows instead of collapsing. */
  collapse: number;
}

const DiffViewContext = createContext<DiffViewContextValue | null>(null);

const useDiffView = () => {
  const context = use(DiffViewContext);

  if (!context) {
    throw new Error("Diff view parts must be inside DiffView.");
  }

  return context;
};

const DiffViewHeader = (props: ComponentProps<typeof CodePanelHeader>) => (
  <CodePanelHeader {...props} data-slot="diff-view-header" />
);

const DiffViewTitle = ({ children, ...props }: ComponentProps<typeof CodePanelTitle>) => {
  const { fileDiff } = useDiffView();

  return (
    <CodePanelTitle {...props} data-slot="diff-view-title">
      <Icon name={fileIconName(fileDiff.name)} className="size-4.5" />
      <span className="truncate">
        {children ??
          (fileDiff.prevName !== undefined &&
          fileDiff.prevName !== "" &&
          fileDiff.prevName !== fileDiff.name
            ? `${fileDiff.prevName} → ${fileDiff.name}`
            : fileDiff.name)}
      </span>
    </CodePanelTitle>
  );
};

const DiffViewActions = (props: ComponentProps<typeof CodePanelActions>) => (
  <CodePanelActions {...props} data-slot="diff-view-actions" />
);

const DiffViewStats = ({ className, ...props }: Omit<ComponentProps<"span">, "children">) => {
  const { fileDiff } = useDiffView();
  const additions = fileDiff.hunks.reduce((total, hunk) => total + hunk.additionLines, 0);
  const deletions = fileDiff.hunks.reduce((total, hunk) => total + hunk.deletionLines, 0);

  return (
    <span
      {...props}
      data-slot="diff-view-stats"
      className={cn("inline-flex items-center gap-2 text-metadata tabular-nums", className)}
    >
      <span className="text-success">
        +{additions}
        <span className="sr-only"> added lines</span>
      </span>
      <span className="text-error">
        −{deletions}
        <span className="sr-only"> deleted lines</span>
      </span>
    </span>
  );
};

interface DiffRow {
  old?: CodePanelLine;
  new?: CodePanelLine;
}

const stripEOL = (line: string | undefined) => (line ?? "").replace(/\r?\n$/u, "");

const changedLines = (
  source: string[],
  index: number,
  count: number,
  firstNumber: number,
  tone: "addition" | "deletion",
): CodePanelLine[] =>
  Array.from({ length: count }, (_, offset) => ({
    number: firstNumber + offset,
    text: stripEOL(source[index + offset]),
    tone,
  }));

const separatorRow = (split: boolean): DiffRow =>
  split
    ? { new: { text: "", tone: "separator" }, old: { text: "", tone: "separator" } }
    : { new: { text: "", tone: "separator" } };

/** Unchanged lines `count` long, ending just before line `oldEnd` and `newEnd`. */
const unchangedRows = (
  fileDiff: FileDiffMetadata,
  split: boolean,
  { count, oldEnd, newEnd }: { count: number; oldEnd: number; newEnd: number },
): DiffRow[] =>
  Array.from({ length: count }, (_, offset) => {
    const newNumber = newEnd - count + offset;
    const text = stripEOL(fileDiff.additionLines[newNumber - 1]);
    const newLine = { number: newNumber, text };

    return split
      ? { new: newLine, old: { number: oldEnd - count + offset, text } }
      : { new: newLine };
  });

/**
 * Pierre's rule for unchanged lines between hunks: it shows a gap of up to `collapse` lines (all of
 * them with `expandUnchanged`) and draws a separator over a longer one. A partial patch has no
 * text for the gap, so every gap is a separator.
 */
const gapRows = (
  fileDiff: FileDiffMetadata,
  split: boolean,
  collapse: number,
  gap: { count: number; oldEnd: number; newEnd: number },
): DiffRow[] => {
  if (gap.count <= 0) {
    return [];
  }

  return !fileDiff.isPartial && gap.count <= collapse
    ? unchangedRows(fileDiff, split, gap)
    : [separatorRow(split)];
};

/**
 * The diff's rows as plain text, in Pierre's layout: one column for `unified`, old and new side by
 * side for `split`, with Pierre's separators. Shown until Pierre's first render, so the code reads
 * at once and highlighting lands in place.
 */
const diffRows = (fileDiff: FileDiffMetadata, split: boolean, collapse: number): DiffRow[] => {
  const rows: DiffRow[] = [];
  let oldNumber = 1;
  let newNumber = 1;

  for (const hunk of fileDiff.hunks) {
    oldNumber = hunk.deletionCount === 0 ? hunk.deletionStart + 1 : hunk.deletionStart;
    newNumber = hunk.additionCount === 0 ? hunk.additionStart + 1 : hunk.additionStart;
    rows.push(
      ...gapRows(fileDiff, split, collapse, {
        count: hunk.collapsedBefore,
        oldEnd: oldNumber,
        newEnd: newNumber,
      }),
    );

    for (const block of hunk.hunkContent) {
      if (block.type === "context") {
        for (let offset = 0; offset < block.lines; offset += 1) {
          const text = stripEOL(fileDiff.additionLines[block.additionLineIndex + offset]);
          const newLine = { number: newNumber, text };
          rows.push(split ? { new: newLine, old: { number: oldNumber, text } } : { new: newLine });
          oldNumber += 1;
          newNumber += 1;
        }

        continue;
      }

      const deletions = changedLines(
        fileDiff.deletionLines,
        block.deletionLineIndex,
        block.deletions,
        oldNumber,
        "deletion",
      );

      const additions = changedLines(
        fileDiff.additionLines,
        block.additionLineIndex,
        block.additions,
        newNumber,
        "addition",
      );

      oldNumber += block.deletions;
      newNumber += block.additions;

      if (split) {
        for (let index = 0; index < Math.max(deletions.length, additions.length); index += 1) {
          rows.push({
            new: additions[index] ?? { text: "" },
            old: deletions[index] ?? { text: "" },
          });
        }
      } else {
        rows.push(
          ...deletions.map((line) => ({ new: line })),
          ...additions.map((line) => ({ new: line })),
        );
      }
    }
  }

  // Unchanged lines after the last hunk, which a partial patch does not know.
  const trailing = fileDiff.additionLines.length - newNumber + 1;

  if (
    !fileDiff.isPartial &&
    fileDiff.hunks.length > 0 &&
    fileDiff.deletionLines.length > 0 &&
    trailing > 0
  ) {
    rows.push(
      ...gapRows(fileDiff, split, collapse, {
        count: trailing,
        oldEnd: oldNumber + trailing,
        newEnd: newNumber + trailing,
      }),
    );
  }

  return rows;
};

/** The digits Pierre sizes its number column for: the longest side of the file. */
const diffDigits = (fileDiff: FileDiffMetadata) => {
  const last = fileDiff.hunks.at(-1);

  const hunkEnd = last
    ? Math.max(
        last.additionStart + last.additionCount - (last.additionCount === 0 ? 0 : 1),
        last.deletionStart + last.deletionCount - (last.deletionCount === 0 ? 0 : 1),
      )
    : 0;

  return String(Math.max(hunkEnd, fileDiff.additionLines.length, fileDiff.deletionLines.length, 1))
    .length;
};

const DiffViewFallback = () => {
  const { fileDiff, split, numbered, indicators, collapse } = useDiffView();
  const rows = diffRows(fileDiff, split, collapse);
  const lines = { indicators, minDigits: diffDigits(fileDiff) };

  const side = (key: "old" | "new") =>
    rows.map((row) => {
      const line = row[key] ?? { text: "" };

      return numbered ? line : { ...line, number: undefined };
    });

  // Pierre leaves out the empty side of an added or deleted file.
  if (!split || fileDiff.type === "new") {
    return <CodePanelLines lines={side("new")} {...lines} />;
  }

  if (fileDiff.type === "deleted") {
    return <CodePanelLines lines={side("old")} {...lines} />;
  }

  return (
    <div className="grid grid-cols-2">
      <CodePanelLines lines={side("old")} className="min-w-0 overflow-hidden" {...lines} />
      <CodePanelLines lines={side("new")} className="min-w-0 overflow-hidden" {...lines} />
    </div>
  );
};

const DiffViewContent = (
  props: Omit<CodePanelContentProps, "children" | "empty" | "fallback" | "loading">,
) => {
  const { content, fileDiff, rendered } = useDiffView();
  const blank = fileDiff.additionLines.length === 0 && fileDiff.deletionLines.length === 0;

  const noChanges = blank ? (
    <CodePanelEmpty title="Empty file" description="This file has no contents." />
  ) : (
    <CodePanelEmpty
      title="No content changes"
      description="The two versions have identical contents."
    />
  );

  const empty = fileDiff.hunks.length > 0 ? undefined : noChanges;

  return (
    <CodePanelContent
      aria-label={`Changes to ${fileDiff.name}`}
      {...props}
      data-slot="diff-view-content"
      fallback={rendered ? undefined : <DiffViewFallback />}
      empty={empty}
    >
      {content}
    </CodePanelContent>
  );
};

const DiffViewCopyButton = ({
  side = "new",
  ...props
}: Omit<CopyButtonProps, "value"> & { side?: "old" | "new" }) => {
  const { oldContents, newContents } = useDiffView();
  const contents = side === "old" ? oldContents : newContents;

  return (
    <CodePanelCopyButton
      aria-label={`Copy ${side} file`}
      {...props}
      value={contents ?? ""}
      disabled={contents === undefined || props.disabled}
    />
  );
};

const DiffView = <Annotation = undefined,>({
  oldFile,
  newFile,
  fileDiff: providedDiff,
  patch,
  options,
  lineAnnotations,
  selectedLines,
  renderAnnotation,
  renderGutterUtility,
  prerenderedHTML,
  metrics,
  disableWorkerPool,
  children,
  className,
  ...props
}: DiffViewProps<Annotation>) => {
  const fileDiff = useMemo(
    () =>
      providedDiff ??
      (patch === undefined
        ? parseDiffFromFile(oldFile ?? null, newFile ?? null, options?.parseDiffOptions)
        : patchDiff(patch)),
    [providedDiff, patch, oldFile, newFile, options?.parseDiffOptions],
  );

  // Pierre highlights asynchronously, so its host stays empty until the first render; the plain
  // diff stands in until then.
  const [rendered, setRendered] = useState(false);

  const rendererOptions = useMemo(
    (): FileDiffOptions<Annotation, undefined> => ({
      diffIndicators: "classic",
      ...options,
      theme: diffTheme,
      themeType: "system",
      disableFileHeader: true,
      unsafeCSS: diffThemeCSS,
      onPostRender(node, instance, phase) {
        if (phase !== "unmount") {
          applyDiffIcons(node);
          enhanceDiffAccessibility(node);
          setRendered(true);
        }

        return options?.onPostRender?.(node, instance, phase);
      },
    }),
    [options],
  );

  const context = useMemo(
    () => ({
      fileDiff,
      // Partial patches cannot provide an exact full-file copy.
      oldContents:
        oldFile?.contents ??
        (!fileDiff.isPartial && fileDiff.type !== "new"
          ? fileDiff.deletionLines.join("")
          : undefined),
      newContents:
        newFile?.contents ??
        (!fileDiff.isPartial && fileDiff.type !== "deleted"
          ? fileDiff.additionLines.join("")
          : undefined),
      rendered: rendered || prerenderedHTML !== undefined,
      split: options?.diffStyle !== "unified",
      numbered: options?.disableLineNumbers !== true,
      indicators: (options?.diffIndicators ?? "classic") === "classic",
      collapse:
        options?.expandUnchanged === true
          ? Number.POSITIVE_INFINITY
          : (options?.collapsedContextThreshold ?? 1),
      content: (
        <FileDiff
          fileDiff={fileDiff}
          options={rendererOptions}
          lineAnnotations={lineAnnotations}
          selectedLines={selectedLines}
          renderAnnotation={renderAnnotation}
          renderGutterUtility={renderGutterUtility}
          prerenderedHTML={prerenderedHTML}
          metrics={metrics}
          disableWorkerPool={disableWorkerPool}
        />
      ),
    }),
    [
      disableWorkerPool,
      fileDiff,
      lineAnnotations,
      metrics,
      newFile?.contents,
      oldFile?.contents,
      options?.diffStyle,
      options?.disableLineNumbers,
      options?.diffIndicators,
      options?.expandUnchanged,
      options?.collapsedContextThreshold,
      prerenderedHTML,
      renderAnnotation,
      renderGutterUtility,
      rendered,
      rendererOptions,
      selectedLines,
    ],
  );

  return (
    <DiffViewContext value={context}>
      <CodePanel {...props} data-slot="diff-view" className={className}>
        {children ?? (
          <>
            <DiffViewHeader>
              <DiffViewTitle />
              <DiffViewActions>
                <DiffViewStats />
                <DiffViewCopyButton />
              </DiffViewActions>
            </DiffViewHeader>
            <DiffViewContent />
          </>
        )}
      </CodePanel>
    </DiffViewContext>
  );
};

export {
  DiffView,
  DiffViewHeader,
  DiffViewTitle,
  DiffViewStats,
  DiffViewActions,
  DiffViewContent,
  DiffViewCopyButton,
};

export type { DiffViewProps, DiffViewOptions };

export type {
  FileContents,
  FileDiffMetadata,
  DiffLineAnnotation,
  SelectedLineRange,
} from "@pierre/diffs";

import * as React from "react";
import { Drawer as DrawerPrimitive } from "@base-ui/react/drawer";
import { useMergedRefs } from "@base-ui/utils/useMergedRefs";
import { Icon } from "@/registry/erbium/ui/icon";
import { ModalHotkeysScope } from "@/registry/erbium/lib/modal-hotkeys-scope";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import { Button } from "@/registry/erbium/ui/button";
import { ScrollArea } from "@/registry/erbium/ui/scroll-area";

interface DrawerContextProps {
  hasSnapPoints: boolean;
  modal: DrawerPrimitive.Root.Props["modal"];
  showSwipeHandle: boolean;
}

const DrawerContext = React.createContext<DrawerContextProps | null>(null);
const DrawerPanelContext = React.createContext(false);

const useDrawer = () => {
  const context = React.useContext(DrawerContext);

  if (!context) {
    throw new Error("useDrawer must be used within a Drawer.");
  }

  return context;
};

// True below a DrawerProvider, so an inner provider joins the outer one.
const DrawerProviderContext = React.createContext(false);

/**
 * Coordinates every drawer inside it, so a `DrawerIndent` can follow whichever one is open. Mount
 * it once around the app. A nested provider joins the outer one rather than starting its own, so
 * a widget can mount one without hiding its drawers from the app's indent. Drawers work without
 * a provider; only the indent needs it.
 */
const DrawerProvider = ({ children }: DrawerPrimitive.Provider.Props) => {
  const nested = React.use(DrawerProviderContext);

  return (
    <DrawerProviderContext value={true}>
      {nested ? children : <DrawerPrimitive.Provider>{children}</DrawerPrimitive.Provider>}
    </DrawerProviderContext>
  );
};

/*
 * The scroll offset of the page while a drawer opens. A page taller than the viewport scales
 * around, and clips to, the part on screen. The scroll lock moves the offset from the document to
 * the body on platforms with classic scrollbars, so both count. Offsets are read from layout,
 * which the indent's transform does not change.
 */
const measureIndentTop = (indent: HTMLElement) =>
  Math.max(0, window.scrollY + document.body.scrollTop - indent.offsetTop);

/*
 * Holds `--drawer-indent-top` at the offset from the moment a drawer opens until the page has
 * eased back to rest, since the transform contains fixed descendants until then.
 */
const syncIndentTop = (element: HTMLElement) => {
  const setTop = (top: number) => {
    element.style.setProperty("--drawer-indent-top", `${top}px`);
  };

  const resetAtRest = () => {
    if (element.dataset.active === undefined) {
      setTop(0);
    }
  };

  if (element.dataset.active !== undefined) {
    setTop(measureIndentTop(element));

    return;
  }

  // Reading the animations flushes styles, so the transition back to rest is listed.
  const easing = element
    .getAnimations()
    .filter(
      (animation) =>
        animation instanceof CSSTransition && animation.transitionProperty === "transform",
    );

  if (easing.length === 0) {
    resetAtRest();

    return;
  }

  // A cancelled transition leaves the page at rest as well.
  for (const animation of easing) {
    animation.addEventListener("finish", resetAtRest);
    animation.addEventListener("cancel", resetAtRest);
  }
};

const useIndentTop = (indent: React.RefObject<HTMLDivElement | null>) => {
  React.useLayoutEffect(() => {
    const observer = new MutationObserver((records) => {
      for (const record of records) {
        if (record.target instanceof HTMLElement) {
          syncIndentTop(record.target);
        }
      }
    });

    if (indent.current !== null) {
      observer.observe(indent.current, { attributeFilter: ["data-active"] });
    }

    return () => {
      observer.disconnect();
    };
  }, [indent]);
};

/**
 * Wraps the app's main UI inside a `DrawerProvider`. While any drawer is open the page scales
 * back from the top of the screen, drops by the safe area, and rounds the visible part over a
 * dark layer, easing back to rest as the drawer is swiped away. It works for a page taller than
 * the viewport as well as one that scrolls inside its own container.
 *
 * The transform makes it the containing block for fixed descendants while a drawer is open. Keep
 * fixed chrome outside it, or offset it with `top-(--drawer-indent-top,0px)`, the scroll offset
 * the indent holds until the page is back at rest.
 */
const DrawerIndent = ({ className, ref, ...props }: DrawerPrimitive.Indent.Props) => {
  const indent = React.useRef<HTMLDivElement>(null);
  const mergedRef = useMergedRefs(ref, indent);
  useIndentTop(indent);

  return (
    <>
      <DrawerPrimitive.IndentBackground
        data-slot="drawer-indent-background"
        className="fixed inset-0 bg-overlay-base"
      />
      <DrawerPrimitive.Indent
        ref={mergedRef}
        data-slot="drawer-indent"
        className={cn(
          // Base.
          "relative bg-background [--drawer-indent-top:0px]",
          // Motion. The transition is off while a swipe drives the progress. Only the transform
          // eases: the clip window is placed after `data-active` lands, and easing it would sweep
          // it from the top of the document down to the screen.
          "transition-transform duration-[calc(var(--transition-duration-drawer)*var(--indent-transition))] ease-ui-drawer [--indent-transition:calc(1-clamp(0,calc(var(--drawer-swipe-progress)*100000),1))] motion-reduce:transition-none",
          // Inset: scale around the top of the screen, shift down, and round the visible part.
          "origin-[50%_var(--drawer-indent-top)] [--indent-radius:calc(0.75rem*(1-var(--drawer-swipe-progress)))] [--indent-scale:calc(0.94+(0.06*var(--drawer-swipe-progress)))] [--indent-shift:calc((env(safe-area-inset-top,0px)+14px)*(1-var(--drawer-swipe-progress)))]",
          "data-active:transform-[scale(var(--indent-scale))_translate3d(0,var(--indent-shift),0)] data-active:will-change-transform data-active:[clip-path:inset(var(--drawer-indent-top)_0_max(0px,calc(100%-var(--drawer-indent-top)-100lvh))_0_round_var(--indent-radius))]",
          className,
        )}
