import { createContext, useContext, useMemo, useState } from "react";
import { Field as FieldPrimitive } from "@base-ui/react/field";
import { Fieldset as FieldsetPrimitive } from "@base-ui/react/fieldset";
import { useMergedRefs } from "@base-ui/utils/useMergedRefs";
import { cva } from "class-variance-authority";
import type { VariantProps } from "class-variance-authority";
import { animateHeight } from "@/registry/erbium/lib/animate-height";
import { choiceCardClassName } from "@/registry/erbium/lib/choice-styles";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import { Separator } from "@/registry/erbium/ui/separator";

type FieldRootProps = FieldPrimitive.Root.Props & {
  /** Marks the field label or legend as required. */
  required?: boolean;
};

/** Whether the surrounding field, fieldset or questionnaire item must be answered. */
const FieldRequiredContext = createContext(false);
const useFieldRequired = () => useContext(FieldRequiredContext);

/** The required asterisk after a label or legend; the control's `required` announces it. */
const RequiredMark = () => (
  <span aria-hidden="true" className="text-error">
    *
  </span>
);

/**
 * Base UI's grouped-field pattern: a `Field.Root` rendered as the `<fieldset>`.
 * The legend names the group, and a `FieldDescription`, `FieldError` or
 * `FieldItem` directly inside it wires to the group's control, e.g. a radio or
 * checkbox group. Like `Field`, it eases to its new height when the group's
 * error or other content changes it.
 */
const FieldSet = ({ className, ref, required = false, ...props }: FieldRootProps) => (
  <FieldRequiredContext.Provider value={required}>
    <FieldPrimitive.Root
      ref={useMergedRefs(ref, animateHeight)}
      render={<FieldsetPrimitive.Root />}
      data-slot="field-set"
      className={cn(
        "flex flex-col gap-group has-[>[data-slot=checkbox-group]]:gap-3 has-[>[data-slot=radio-group]]:gap-3",
        className,
      )}
      {...props}
    />
  </FieldRequiredContext.Provider>
);

const FieldLegend = ({
  children,
  className,
  variant = "legend",
  ...props
}: FieldsetPrimitive.Legend.Props & { variant?: "legend" | "label" }) => {
  const required = useFieldRequired();

  return (
    <FieldsetPrimitive.Legend
      data-slot="field-legend"
      data-variant={variant}
      className={cn(
        "mb-1.5 font-medium data-[variant=label]:text-control data-[variant=legend]:text-body",
        className,
      )}
      {...props}
    >
      {children}
      {required ? (
        <>
          {" "}
          <RequiredMark />
        </>
      ) : null}
    </FieldsetPrimitive.Legend>
  );
};

const FieldGroup = ({ className, ...props }: React.ComponentProps<"div">) => (
  <div
    data-slot="field-group"
    className={cn(
      "group/field-group @container/field-group flex w-full flex-col gap-group data-[slot=checkbox-group]:gap-related *:data-[slot=field-group]:gap-group",
      className,
    )}
    {...props}
  />
);

/*
 * A horizontal row that pairs a choice control (`[data-choice]`: checkbox,
 * radio, switch) with a direct `FieldLabel` or `FieldContent` matches the
 * `choice-row` variant (variants.css). It top-aligns and offsets the control by
 * `choice-first-line` (sizing.css), so the control is centred on the label's
 * first line however far the label or description wraps. The offset is derived
 * from tokens; never hand-tune it with `mt-*` on the control or `items-*` on
 * the row.
 *
 * The card variant is a selectable surface-frame: flat, hairline-framed and
 * translucent, so it reads on the canvas, a panel, a popover or a dialog. The
 * rim and tint come from state: hover and a checked control (switch, checkbox,
 * radio) tint it, focus and validity color the rim. The label stretches over
 * the card, so the whole card toggles its control.
 */
const fieldVariants = cva("group/field flex w-full gap-related data-invalid:text-error", {
  defaultVariants: {
    orientation: "vertical",
    variant: "default",
  },
  variants: {
    orientation: {
      horizontal:
        "flex-row items-center has-[>[data-slot=field-content]]:items-start choice-row:items-start choice-row:*:data-choice:choice-first-line *:data-[slot=field-label]:flex-auto",
      responsive:
        "flex-col *:w-full @md/field-group:flex-row @md/field-group:items-center @md/field-group:*:w-auto @md/field-group:has-[>[data-slot=field-content]]:items-start @md/field-group:choice-row:items-start @md/field-group:choice-row:*:data-choice:choice-first-line @md/field-group:*:data-[slot=field-label]:flex-auto [&>.sr-only]:w-auto",
      vertical: "flex-col *:w-full [&>.sr-only]:w-auto",
    },
    variant: {
      card: choiceCardClassName,
      default: "",
    },
  },
});

/**
 * Base UI `Field.Root`: wires the label, description, error and control, and
 * exposes `name`, `invalid`, `dirty`, `touched` and `disabled`. Set `required`
 * to mark the field label. Inside TanStack Form, `field.Field` binds the
 * name and validation state to the surrounding `form.AppField`. The field eases
 * to its new height when an error or other content changes it.
 */
const Field = ({
  className,
  orientation = "vertical",
  ref,
  required = false,
  variant = "default",
  ...props
}: FieldRootProps & VariantProps<typeof fieldVariants>) => (
  <FieldRequiredContext.Provider value={required}>
    <FieldPrimitive.Root
      ref={useMergedRefs(ref, animateHeight)}
      data-slot="field"
      data-orientation={orientation}
      data-variant={variant}
      className={cn(fieldVariants({ orientation, variant }), className)}
      {...props}
    />
  </FieldRequiredContext.Provider>
);

const FieldContent = ({ className, ...props }: React.ComponentProps<"div">) => (
  <div
    data-slot="field-content"
    className={cn("group/field-content flex flex-1 flex-col gap-0.5 ", className)}
    {...props}
  />
);

const FieldLabel = ({ children, className, ...props }: FieldPrimitive.Label.Props) => {
  const required = useFieldRequired();

  return (
    <FieldPrimitive.Label
      data-slot="field-label"
      className={cn(
        "group/field-label peer/field-label flex w-fit gap-related text-control select-none data-disabled:pointer-events-none data-disabled:opacity-50 group-data-[variant=card]/field:w-full group-data-[variant=card]/field:after:absolute group-data-[variant=card]/field:after:inset-0",
        className,
      )}
      {...props}
    >
      {children}
      {required ? <RequiredMark /> : null}
    </FieldPrimitive.Label>
  );
};

/**
 * Helper information is replaced by the error while the field is invalid. A
 * hidden marker keeps its place, so the error takes it over at once instead of
 * fading in.
 */
const FieldDescription = ({ className, ...props }: FieldPrimitive.Description.Props) => (
  <FieldPrimitive.Validity>
    {({ validity }) =>
      validity.valid === false ? (
        <span hidden data-slot="field-description" data-replaced="" />
      ) : (
        <FieldPrimitive.Description
          data-slot="field-description"
          className={cn(
            "text-start text-caption font-normal text-muted-foreground group-has-data-horizontal/field:text-balance [[data-variant=legend]+&]:-mt-1.5",
            "last:mt-0 nth-last-2:-mt-1",
            "[&>a]:underline [&>a]:underline-offset-4 [&>a:hover]:text-link",
            className,
          )}
          {...props}
        />
      )
    }
  </FieldPrimitive.Validity>
);

const FieldSeparator = ({
  children,
  className,
  ...props
}: React.ComponentProps<"div"> & {
  children?: React.ReactNode;
}) => {
  const hasContent = children !== undefined && children !== null && children !== false;

  return (
    <div
      data-slot="field-separator"
      data-content={hasContent}
      className={cn(
        "relative -my-2 flex h-5 items-center text-caption group-data-[variant=outline]/field-group:-mb-2",
        className,
      )}
      {...props}
    >
      <Separator className="text-muted-foreground">
        {hasContent ? <span data-slot="field-separator-content">{children}</span> : null}
      </Separator>
    </div>
  );
};

type FieldErrorProps = FieldPrimitive.Error.Props & {
  /**
   * Messages from a form library. `FormFieldError` from `./form` passes the
   * TanStack Form field's errors, decoded from strings or Standard Schema
   * issues such as Effect Schema's. Duplicate messages collapse. When set, the
   * error shows exactly while there is at least one message; otherwise Base
   * UI's `match` rules apply.
   */
  errors?: readonly string[];
};

const FieldError = ({ className, children, errors, match, ...props }: FieldErrorProps) => {
  const messages = useMemo(
    () => [...new Set((errors ?? []).filter((message) => message.length > 0))],
    [errors],
  );

  const key = messages.join("\n");
  // Keep the last message mounted while Base UI plays the exit transition.
  const [shownKey, setShownKey] = useState(key);

  if (key && key !== shownKey) {
    setShownKey(key);
  }

  const shown = key || shownKey ? (key || shownKey).split("\n") : [];

  let content = children;

  if (errors) {
    content =
      shown.length > 1 ? (
        <ul className="ms-4 flex list-disc flex-col gap-1">
          {shown.map((message) => (
            <li key={message}>{message}</li>
          ))}
        </ul>
      ) : (
        shown[0]
      );
  }

  return (
    <FieldPrimitive.Error
      data-slot="field-error"
      role="alert"
      match={errors ? messages.length > 0 : match}
      className={cn(
        // `Field` eases the height; the message fades in, unless it takes a description's place.
        "text-caption font-normal text-error transition-opacity duration-200 ease-out data-ending-style:hidden data-starting-style:opacity-0 motion-reduce:transition-none [[data-replaced]~&]:transition-none [[data-replaced]~&]:data-starting-style:opacity-100",
        className,
      )}
      {...props}
    >
      {content}
    </FieldPrimitive.Error>
  );
};

/**
 * Base UI `Field.Item`: one checkbox or radio inside a group, with its own
 * label, description and disabled scope. Takes the same layout props as `Field`,
 * so `variant="card"` turns each item into a choice card.
 */
const FieldItem = ({
  className,
  orientation = "vertical",
  variant = "default",
  ...props
}: FieldPrimitive.Item.Props & VariantProps<typeof fieldVariants>) => (
  <FieldRequiredContext.Provider value={false}>
    <FieldPrimitive.Item
      data-slot="field-item"
      data-orientation={orientation}
      data-variant={variant}
      className={cn(fieldVariants({ orientation, variant }), className)}
      {...props}
    />
  </FieldRequiredContext.Provider>
);

const FieldControl = ({ required, ...props }: FieldPrimitive.Control.Props) => {
  const fieldRequired = useFieldRequired();

  return <FieldPrimitive.Control required={required ?? fieldRequired} {...props} />;
};

const FieldValidity = FieldPrimitive.Validity;

export {
  Field,
  FieldLabel,
  FieldDescription,
  FieldError,
  FieldGroup,
  FieldLegend,
  FieldSeparator,
  FieldSet,
  FieldContent,
  FieldItem,
  FieldControl,
  FieldValidity,
  FieldRequiredContext,
  RequiredMark,
  useFieldRequired,
};

import { iconDefinitions } from "@erbium/icons";
import type { IconName } from "@erbium/icons";
import { spriteSheets } from "@erbium/icons/sprite";

const byFileName: Record<string, IconName> = {
  ".gitattributes": "git",
  ".gitignore": "git",
  ".gitmodules": "git",
  ".npmrc": "npm-duo",
  "bun.lock": "bun",
  "bun.lockb": "bun",
  dockerfile: "docker",
  "package-lock.json": "npm-duo",
  "package.json": "npm-duo",
};

// Matched against the basename, so tool configs resolve to their tool.
const byFileNameContains: Record<string, IconName> = {
  ".eslintrc": "eslint",
  ".prettierrc": "prettier",
  "biome.json": "biome",
  "docker-compose": "docker",
  "eslint.config": "eslint",
  "next.config": "nextjs",
  "oxfmt.config": "oxc",
  "oxlint.config": "oxc",
  "prettier.config": "prettier",
  "tailwind.config": "tailwind",
  "vite.config": "vite",
  "webpack.config": "webpack",
};

const byFileExtension: Record<string, IconName> = {
  astro: "astro",
  avif: "image-duo",
  bash: "bash-duo",
  c: "lang-c",
  cc: "lang-c",
  cjs: "lang-javascript-duo",
  cpp: "lang-c",
  css: "lang-css-duo",
  csv: "file-table-duo",
  cts: "lang-typescript-duo",
  gif: "image-duo",
  go: "lang-go",
  gql: "graphql",
  graphql: "graphql",
  gz: "file-zip-duo",
  h: "lang-c",
  hpp: "lang-c",
  htm: "lang-html-duo",
  html: "lang-html-duo",
  ico: "image-duo",
  jpeg: "image-duo",
  jpg: "image-duo",
  js: "lang-javascript-duo",
  json: "braces",
  json5: "braces",
  jsonc: "braces",
  jsx: "react",
  md: "lang-markdown",
  mdx: "lang-markdown",
  mjs: "lang-javascript-duo",
  mts: "lang-typescript-duo",
  otf: "font",
  png: "image-duo",
  py: "lang-python",
  rb: "lang-ruby",
  rs: "lang-rust",
  sass: "sass",
  scss: "sass",
  sh: "bash-duo",
  sql: "file-table-duo",
  svelte: "svelte",
  svg: "svg-2",
  swift: "lang-swift",
  tar: "file-zip-duo",
  tf: "terraform",
  ts: "lang-typescript-duo",
  tsv: "file-table-duo",
  tsx: "react",
  ttf: "font",
  txt: "file-text-duo",
  vue: "vue",
  wasm: "wasm-duo",
  webp: "image-duo",
  woff: "font",
  woff2: "font",
  yaml: "yml",
  yml: "yml",
  zig: "zig",
  zip: "file-zip-duo",
  zsh: "bash-duo",
};

const fallback: IconName = "file-duo";

const extensionCandidates = (fileName: string) => {
  const segments = fileName.split(".");

  // `a.spec.ts` tries `spec.ts` and then `ts`; a leading dot is not an extension.
  return segments.slice(1).map((_, index) => segments.slice(index + 1).join("."));
};

/** The icon for a file path: exact name, then tool-config name, then extension. */
const fileIconName = (path: string): IconName => {
  const fileName = (path.split("/").at(-1) ?? path).toLowerCase();
  const exact = byFileName[fileName];

  if (exact) {
    return exact;
  }

  for (const [needle, icon] of Object.entries(byFileNameContains)) {
    if (fileName.includes(needle)) {
      return icon;
    }
  }

  for (const extension of extensionCandidates(fileName)) {
    const icon = byFileExtension[extension];

    if (icon) {
      return icon;
    }
  }

  return fallback;
};

// Pierre's tree renders icons through a sprite injected into its shadow root.
// Give it the file-type group plus the few interface glyphs its slots need, so
// the tree draws the same artwork as the rest of the system.
const treeInterfaceIcons = [
  "chevron-down",
  "lock",
  "more-horizontal",
] as const satisfies IconName[];

const symbolMarkup = (sheet: string, name: IconName) => {
  const match = new RegExp(
    `<symbol[^>]*\\sid="${iconDefinitions[name].id}"[\\s\\S]*?</symbol>`,
  ).exec(sheet);

  return match?.[0] ?? "";
};

const { files } = spriteSheets;

const treeSpriteSheet = `${files.slice(0, files.lastIndexOf("</svg>"))}${treeInterfaceIcons
  .map((name) => symbolMarkup(spriteSheets.ui, name))
  .join("\n")}\n</svg>\n`;

const treeIcon = (name: IconName) => {
  const { id, viewBox } = iconDefinitions[name];

  return { name: id, viewBox };
};

const treeIcons = <Rules extends Record<string, IconName>>(rules: Rules) =>
  Object.fromEntries(Object.entries(rules).map(([key, name]) => [key, treeIcon(name)]));

const fileTreeIcons = {
  byFileExtension: treeIcons(byFileExtension),
  byFileName: treeIcons(byFileName),
  byFileNameContains: treeIcons(byFileNameContains),
  colored: false,
  remap: {
    "file-tree-icon-chevron": treeIcon("chevron-down"),
    "file-tree-icon-ellipsis": treeIcon("more-horizontal"),
    "file-tree-icon-file": treeIcon(fallback),
    "file-tree-icon-lock": treeIcon("lock"),
  },
  set: "none",
  spriteSheet: treeSpriteSheet,
} as const;

export { fileIconName, fileTreeIcons };

import { FileTree as PierreTree, useFileTree as usePierreTree } from "@pierre/trees/react";
import type { FileTreeProps as PierreTreeProps } from "@pierre/trees/react";
import type { FileTreeOptions as PierreTreeOptions } from "@pierre/trees";
import { createContext, use, useMemo } from "react";
import type { ComponentProps, ReactNode } from "react";
import { DirectionProvider } from "@/registry/erbium/ui/direction";
import { fileTreeIcons } from "@/registry/erbium/lib/file-icons";
import { treeThemeCSS } from "@/registry/erbium/lib/tree-theme";
import { cn } from "@/registry/erbium/lib/erbium-utils";

type FileTreeOptions = Omit<
  PierreTreeOptions,
  | "unsafeCSS"
  | "composition"
  | "searchFakeFocus"
  | "density"
  | "itemHeight"
  | "icons"
  | "paths"
  | "preparedInput"
> & { paths: readonly string[] };

const useFileTree = (options: FileTreeOptions) =>
  // Match the sidebar’s 1.75rem control height; Pierre needs pixels for virtualization.
  usePierreTree({
    ...options,
    density: "default",
    icons: fileTreeIcons,
    itemHeight: 28,
    unsafeCSS: treeThemeCSS,
  });

type FileTreeProps = Omit<ComponentProps<"div">, "children" | "dangerouslySetInnerHTML" | "dir"> &
  Pick<PierreTreeProps, "model" | "preloadedData" | "renderContextMenu"> & { children?: ReactNode };

const TreeContext = createContext<Pick<
  PierreTreeProps,
  "model" | "preloadedData" | "renderContextMenu"
> | null>(null);

const FileTreeContent = ({
  className,
  ...props
}: Omit<PierreTreeProps, "model" | "header" | "preloadedData" | "renderContextMenu">) => {
  const context = use(TreeContext);

  if (!context) {
    throw new Error("File tree content must be inside FileTree.");
  }

  // The host keeps its fixed height while Pierre attaches the tree's shadow root, so the rows
  // land in place without a loading state.
  return (
    <PierreTree
      {...props}
      {...context}
      data-slot="file-tree-content"
      className={cn("block h-80 min-w-0", className)}
    />
  );
};

const FileTree = ({
  model,
  preloadedData,
  renderContextMenu,
  children,
  className,
  ...props
}: FileTreeProps) => {
  const context = useMemo(
    () => ({ model, preloadedData, renderContextMenu }),
    [model, preloadedData, renderContextMenu],
  );

  return (
    // File names and paths are code; the tree stays LTR even on RTL pages.
    <DirectionProvider direction="ltr">
      <TreeContext value={context}>
        <section
          aria-label="Files"
          {...props}
          dir="ltr"
          data-slot="file-tree"
          className={cn(
            "min-w-0 w-full overflow-hidden text-sidebar-foreground group-data-[collapsible=icon]:hidden",
            className,
          )}
        >
          {children ?? <FileTreeContent />}
        </section>
      </TreeContext>
    </DirectionProvider>
  );
};

const FileTreeHeader = ({ className, ...props }: ComponentProps<"div">) => (
  <div
    {...props}
