import type { ColumnFiltersState } from "@tanstack/react-table";
import {
  filterOperators,
  hasFilterConfig,
  isFilterRule,
  isOptionType,
  isRangeOperator,
} from "@/registry/erbium/lib/filter-rules";
import type { FilterOperator, FilterRule, FilterType, FilterValue } from "@/registry/erbium/lib/filter-rules";

/*
 * Filters in the URL. Each field with a rule gets one search param, named by the field id, so a
 * filtered view is a link that can be shared or bookmarked:
 *
 *   ?status=todo,in-progress&estimate=between.2,8&title=contains.api
 *
 * The value is the rule's values, comma separated, after `operator.` when the operator is not the
 * field type's default. Range ends may be blank (`between.2,`), a rule still being edited has no
 * values (`?title=`), and commas inside option values are written as `%2C`. Text values are never
 * split, so they keep their commas.
 *
 * The codec is router agnostic. It reads any search object (TanStack Router's parsed search, or
 * the entries of `URLSearchParams`) and writes plain values.
 */

/** The fields whose rules live in the URL, by id: each needs only its type. */
type FilterSearchFields<TKey extends string = string> = Record<TKey, { type: FilterType }>;

/** A search param value a filter can be read from. Routers that parse values as JSON, as TanStack
 * Router does, hand numbers and booleans back as well as strings. */
type ParamText = string | number | boolean;

/**
 * The params of a search object, such as TanStack Router's `Route.useSearch()`. Params of other
 * kinds are ignored at runtime.
 */
type SearchParams<TKey extends string = string> = Readonly<Partial<Record<TKey, ParamText | null>>>;

/**
 * The filter params of a search object. `validateFilterSearch` returns the fields that hold a
 * rule; `toFilterSearch` returns every field, with `undefined` for fields without a rule, so that
 * merging it into the current search removes those params.
 */
type FilterSearch<TKey extends string = string> = Partial<Record<TKey, string | number>>;

const dayKey = /^\d{4}-\d{2}-\d{2}$/u;
const operatorPrefix = /^(?<operator>[A-Za-z]+)\.(?<body>.*)$/su;

const escapeOption = (value: string) => value.replaceAll("%", "%25").replaceAll(",", "%2C");
const unescapeOption = (value: string) => value.replaceAll("%2C", ",").replaceAll("%25", "%");

const encodeValues = (rule: FilterRule) => {
  if (rule.type === "text") {
    return String(rule.values[0] ?? "");
  }

  if (isOptionType(rule.type)) {
    return rule.values
      .flatMap((value) => (value === null ? [] : [escapeOption(String(value))]))
      .join(",");
  }

  // Numbers and dates. A range keeps both ends, so a blank start stays a blank start.
  const values = isRangeOperator(rule.operator) ? rule.values.slice(0, 2) : rule.values.slice(0, 1);

  return values.map((value) => (value === null ? "" : String(value))).join(",");
};

const getOperator = (type: FilterType, name: string): FilterOperator | undefined =>
  filterOperators[type].find((operator) => operator === name);

// `undefined` marks a token that does not fit the type, which drops the whole param.
const decodeValue = (type: FilterType, token: string): FilterValue | undefined => {
  if (token === "") {
    return null;
  }

  if (type === "number") {
    const number = Number(token);

    return Number.isFinite(number) ? number : undefined;
  }

  return type === "date" && !dayKey.test(token) ? undefined : token;
};

const isDecoded = (value: FilterValue | undefined): value is FilterValue => value !== undefined;

const decodeValues = (
  type: FilterType,
  operator: FilterOperator,
  body: string,
): FilterValue[] | undefined => {
  if (body === "") {
    return [];
  }

  if (type === "text") {
    return [body];
  }

  if (isOptionType(type)) {
    return body.split(",").flatMap((token) => (token === "" ? [] : [unescapeOption(token)]));
  }

  const tokens = body.split(",").map((token) => decodeValue(type, token));
  const values = isRangeOperator(operator) ? tokens.slice(0, 2) : tokens.slice(0, 1);

  return values.every(isDecoded) ? values : undefined;
};

const isParamText = (value: unknown): value is ParamText =>
  typeof value === "string" || typeof value === "number" || typeof value === "boolean";

const isFieldId = <TKey extends string>(fields: FilterSearchFields<TKey>, id: string): id is TKey =>
  Object.hasOwn(fields, id);

/** The rule a search param value holds for a field of this type, or `undefined` when it does not fit. */
const decodeFilterParam = (type: FilterType, value: ParamText): FilterRule | undefined => {
  const param = String(value);
  const groups = operatorPrefix.exec(param)?.groups;
  const prefixed = getOperator(type, groups?.operator ?? "");
  const operator = prefixed ?? filterOperators[type][0];
  const body = prefixed === undefined ? param : (groups?.body ?? "");

  const values = decodeValues(type, operator, body);

  return values === undefined ? undefined : { operator, type, values };
};

/**
 * The search param value for a rule. Plain numbers are written as numbers, so routers that parse
 * search values as JSON (TanStack Router does) write `?estimate=3` rather than `?estimate=%223%22`.
 */
const encodeFilterParam = (rule: FilterRule): string | number => {
  const body = encodeValues(rule);
  const implicit = rule.operator === filterOperators[rule.type][0];
  // The operator is left out only when the value still reads back as the same rule, so a text
  // value such as `is.done` keeps its `contains.` prefix.
  const decoded = implicit ? decodeFilterParam(rule.type, body) : undefined;

  if (decoded?.operator === rule.operator && encodeValues(decoded) === body) {
    const number = Number(body);

    return body !== "" && String(number) === body ? number : body;
  }

  return `${rule.operator}.${body}`;
};

/**
 * The column filters a search object holds for these fields, in the order the params appear.
 * Params for other fields are ignored, and values that do not fit a field's type are dropped.
 */
const parseFilterSearch = <TKey extends string>(
  search: SearchParams<TKey>,
  fields: FilterSearchFields<TKey>,
): ColumnFiltersState =>
  Object.entries(search).flatMap(([id, value]) => {
    if (!isFieldId(fields, id) || !isParamText(value)) {
      return [];
    }

    const rule = decodeFilterParam(fields[id].type, value);

    return rule === undefined ? [] : [{ id, value: rule }];
  });

/**
 * The search params for column filters: one per field, `undefined` where a field has no rule.
 * Rules come first, in their order, so a link reopens the chips in the order they were added.
 * Merge the result into the current search so other params are kept.
 */
const toFilterSearch = <TKey extends string>(
  columnFilters: ColumnFiltersState,
  fields: FilterSearchFields<TKey>,
): FilterSearch<TKey> => {
  const search: FilterSearch<TKey> = {};

  for (const { id, value } of columnFilters) {
    if (isFieldId(fields, id) && isFilterRule(value) && value.type === fields[id].type) {
      search[id] = encodeFilterParam(value);
    }
  }

  for (const id in fields) {
    if (Object.hasOwn(fields, id) && !Object.hasOwn(search, id)) {
      search[id] = undefined;
    }
  }

  return search;
};

/**
 * Validates the filter params of a search object, for a route's `validateSearch`. Keeps a param
 * for each field that holds a rule, in URL order and written in its normal form, and drops the rest.
 *
 * ```ts
 * validateSearch: (search) => ({ ...validateFilterSearch(search, filterFields), page: … })
 * ```
 */
const validateFilterSearch = <TKey extends string>(
  search: SearchParams<TKey>,
  fields: FilterSearchFields<TKey>,
): FilterSearch<TKey> => {
  const valid: FilterSearch<TKey> = {};

  for (const { id, value } of parseFilterSearch(search, fields)) {
    if (isFieldId(fields, id) && isFilterRule(value)) {
      valid[id] = encodeFilterParam(value);
    }
  }

  return valid;
};

/** The parts of a column definition `getColumnFilterFields` reads. */
interface FilterSearchColumn {
  id?: string;
  /** A key of the row type: TanStack types it from the row, so generic columns need `PropertyKey`. */
  accessorKey?: PropertyKey;
  meta?: unknown;
  columns?: readonly FilterSearchColumn[];
}

/**
 * The filterable fields of column definitions, by column id, for the search codec. Columns made
 * filterable with `filterColumn(…)` are found, including columns inside groups.
 */
const getColumnFilterFields = (columns: readonly FilterSearchColumn[]): FilterSearchFields =>
  Object.fromEntries(
    columns.flatMap(function collect(column): [string, { type: FilterType }][] {
      const nested = column.columns?.flatMap(collect) ?? [];
      // TanStack makes an id from an accessor key, writing nested keys' dots as underscores.
      const id = column.id ?? column.accessorKey?.toString().replaceAll(".", "_");

      return id !== undefined && hasFilterConfig(column.meta)
        ? [...nested, [id, { type: column.meta.filter.type }]]
        : nested;
    }),
  );

export {
  decodeFilterParam,
  encodeFilterParam,
  getColumnFilterFields,
  parseFilterSearch,
  toFilterSearch,
  validateFilterSearch,
};

export type { FilterSearch, FilterSearchColumn, FilterSearchFields, SearchParams };

import * as React from "react";
import { Badge } from "@/registry/erbium/ui/badge";
import { Button } from "@/registry/erbium/ui/button";
import { ButtonGroup } from "@/registry/erbium/ui/button-group";
import { Calendar } from "@/registry/erbium/ui/calendar";
import type { DateRange } from "@/registry/erbium/ui/calendar";
import {
  Cascader,
  CascaderClear,
  CascaderContent,
  CascaderEmpty,
  CascaderList,
  CascaderSearch,
  CascaderTrigger,
} from "@/registry/erbium/ui/cascader";
import type { CascaderNode } from "@/registry/erbium/ui/cascader";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/registry/erbium/ui/dropdown-menu";
import { Icon } from "@/registry/erbium/ui/icon";
import { Input } from "@/registry/erbium/ui/input";
import { NumberField, NumberFieldGroup, NumberFieldInput } from "@/registry/erbium/ui/number-field";
import { Popover, PopoverContent, PopoverTrigger } from "@/registry/erbium/ui/popover";
import { Separator } from "@/registry/erbium/ui/separator";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/registry/erbium/ui/tooltip";
import {
  changeOperator,
  createRule,
  filterOperators,
  findOption,
  formatDayKey,
  getOperatorLabel,
  isFilterOperator,
  isNumber,
  isOptionType,
  isRangeOperator,
  isRuleEmpty,
  isText,
  parseDayKey,
} from "@/registry/erbium/lib/filter-rules";
import type { FilterField, FilterOption, FilterValue, Filters } from "@/registry/erbium/lib/filter-rules";
import { buttonVariants } from "@/registry/erbium/lib/button-variants";
import { cn } from "@/registry/erbium/lib/erbium-utils";

/*
 * Filter components. Every layout here reads the same `Filters` (from `useTableFilters` or
 * `useListFilters`) and edits values with the same controls: option fields in a searchable
 * cascader, whose option trees open level by level in one popup, and text, number and date fields
 * in a popover. The layouts differ only in how they present fields.
 */

// Rule changes

const setValues = (field: FilterField, values: FilterValue[]) => {
  field.setRule({ ...(field.rule ?? createRule(field.type)), values });
};

/** Checks or unchecks an option. Unchecking the last option removes the filter. */
const toggleOption = (field: FilterField, value: string, checked: boolean) => {
  const values = (field.rule?.values ?? []).filter((current) => current !== value);
  const next = checked ? [...values, value] : values;

  if (next.length === 0) {
    field.setRule(undefined);
  } else {
    setValues(field, next);
  }
};

// Summaries

const dateFormat = new Intl.DateTimeFormat(undefined, { dateStyle: "medium" });

const formatValue = (field: FilterField, value: FilterValue | undefined): string | null => {
  if (value === null || value === undefined || value === "") {
    return null;
  }

  if (field.type === "number" && isNumber(value)) {
    return new Intl.NumberFormat(undefined, field.format).format(value);
  }

  if (field.type === "date" && isText(value)) {
    return dateFormat.format(parseDayKey(value));
  }

  return findOption(field.options, String(value))?.label ?? String(value);
};

/** The labels of an option field's chosen options, in the order they were chosen. */
const optionLabels = (field: FilterField): string[] =>
  isOptionType(field.type)
    ? (field.rule?.values ?? []).map((value) => formatValue(field, value) ?? "")
    : [];

/** Past this many chosen options, a summary counts them instead of naming them. */
const namedOptionLimit = 2;

const isCounted = (field: FilterField) => optionLabels(field).length > namedOptionLimit;

/** What a field's value reads as in a chip or facet button, or `null` while it has none. */
const summarize = (field: FilterField): string | null => {
  const { rule } = field;

  if (rule === undefined || isRuleEmpty(rule)) {
    return null;
  }

  if (isOptionType(field.type)) {
    const labels = optionLabels(field);

    return isCounted(field) ? `${labels.length} selected` : labels.join(", ");
  }

  const [first, second] = rule.values;

  if (isRangeOperator(rule.operator)) {
    return `${formatValue(field, first) ?? "…"} – ${formatValue(field, second) ?? "…"}`;
  }

  return field.type === "text" ? `“${first ?? ""}”` : formatValue(field, first);
};

// Option trees

/** The chosen option values of a field's rule. */
const chosenValues = (field: FilterField) =>
  (field.rule?.values ?? []).flatMap((value) => (value === null ? [] : [String(value)]));

/** Calls `visit` for each option that can be chosen: the options without children. */
const forEachLeaf = (options: readonly FilterOption[], visit: (option: FilterOption) => void) => {
  for (const option of options) {
    if (option.children === undefined) {
      visit(option);
    } else {
      forEachLeaf(option.children, visit);
    }
  }
};

/** An option tree as cascader nodes, each keyed by `nodeValue`. */
const toOptionNodes = (
  options: readonly FilterOption[],
  nodeValue: (option: FilterOption) => string,
): CascaderNode[] =>
  options.map((option) => ({
    children: option.children === undefined ? undefined : toOptionNodes(option.children, nodeValue),
    icon: option.icon === undefined ? undefined : <Icon name={option.icon} aria-hidden="true" />,
    keywords: option.keywords,
    label: option.label,
    value: nodeValue(option),
  }));

/** The content of an option row, with the option's count when the field has counts. */
const OptionRow = ({ node, count }: { node: CascaderNode; count: number | undefined }) => (
  <>
    {node.icon}
    <span className="truncate">{node.label}</span>
    {count === undefined ? null : (
      <span className="ms-auto ps-4 text-muted-foreground tabular-nums">{count}</span>
    )}
  </>
);

interface NumberInputProps {
  field: FilterField;
  label: string;
  value: number | null;
  onValueChange: (value: number | null) => void;
  placeholder?: number;
}

const NumberInput = ({ field, label, value, onValueChange, placeholder }: NumberInputProps) => (
  <NumberField
    size="sm"
    value={value}
    min={field.min}
    max={field.max}
    step={field.step}
    format={field.format}
    onValueChange={onValueChange}
  >
    <NumberFieldGroup>
      <NumberFieldInput
        aria-label={label}
        placeholder={
          placeholder === undefined
            ? undefined
            : new Intl.NumberFormat(undefined, field.format).format(placeholder)
        }
      />
    </NumberFieldGroup>
  </NumberField>
);

const asNumber = (value: FilterValue | undefined) =>
  value !== undefined && isNumber(value) ? value : null;

const asDay = (value: FilterValue | undefined) =>
  value !== undefined && isText(value) ? parseDayKey(value) : undefined;

const NumberEditor = ({ field }: { field: FilterField }) => {
  const rule = field.rule ?? createRule(field.type);
  const [first, second] = rule.values;
  const start = asNumber(first);
  const end = asNumber(second);

  if (!isRangeOperator(rule.operator)) {
    return (
      <NumberInput
        field={field}
        label={field.label}
        value={start}
        onValueChange={(value) => {
          setValues(field, [value]);
        }}
      />
    );
  }

  return (
    <div className="grid grid-cols-2 gap-related">
      <NumberInput
        field={field}
        label={`${field.label} from`}
        value={start}
        placeholder={field.min ?? field.range?.[0]}
        onValueChange={(value) => {
          setValues(field, [value, end]);
        }}
      />
      <NumberInput
        field={field}
        label={`${field.label} to`}
        value={end}
        placeholder={field.max ?? field.range?.[1]}
        onValueChange={(value) => {
          setValues(field, [start, value]);
        }}
      />
    </div>
  );
};

const DateEditor = ({ field }: { field: FilterField }) => {
  const rule = field.rule ?? createRule(field.type);
  const [first, second] = rule.values;

  if (!isRangeOperator(rule.operator)) {
    return (
      <Calendar
        mode="single"
        defaultMonth={asDay(first)}
        selected={asDay(first)}
        onSelect={(selected: Date | undefined) => {
          setValues(field, selected === undefined ? [] : [formatDayKey(selected)]);
        }}
      />
    );
  }

  return (
    <Calendar
      mode="range"
      defaultMonth={asDay(first)}
      selected={{ from: asDay(first), to: asDay(second) }}
      onSelect={(selected: DateRange | undefined) => {
        setValues(field, [
          selected?.from === undefined ? null : formatDayKey(selected.from),
          selected?.to === undefined ? null : formatDayKey(selected.to),
        ]);
      }}
    />
  );
};

/** The editor for a text, number or date field's value. Render inside a popover. */
const FilterValueEditor = ({ field }: { field: FilterField }) => {
  if (field.type === "number") {
    return <NumberEditor field={field} />;
  }

  if (field.type === "date") {
    return <DateEditor field={field} />;
  }

  if (field.type !== "text") {
    return null;
  }

  const [value] = field.rule?.values ?? [];

  return (
    <Input
      aria-label={field.label}
      placeholder={field.placeholder ?? "Enter text…"}
      value={value !== undefined && isText(value) ? value : ""}
      onChange={(event) => {
        setValues(field, [event.target.value]);
      }}
    />
  );
};

interface FilterValueControlProps {
  field: FilterField;
  /** The button that opens the editor. */
  trigger: React.ReactElement;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Content after the editor, such as a clear action. */
  footer?: React.ReactNode;
  align?: "start" | "center" | "end";
}

/**
 * An option field's options in a searchable cascader, opened from a trigger. Options with
 * children open their level in place, and each option shows its count when the field has counts.
 * While more options are chosen than a summary names, hovering the trigger lists them in a tooltip.
 */
const FilterOptionMenu = ({
  field,
  trigger,
  open,
  onOpenChange,
  footer,
  align = "start",
}: FilterValueControlProps) => {
  const { counts, options } = field;
  const items = React.useMemo(() => toOptionNodes(options, (option) => option.value), [options]);

  // The tooltip is always mounted and only disabled, so the trigger keeps its element (and an
  // open menu keeps its anchor) when one more chosen option turns the names into a count.
  return (
    <Tooltip disabled={!isCounted(field)}>
      <Cascader
        multiple
        searchable
        items={items}
        value={chosenValues(field)}
        open={open}
        onOpenChange={onOpenChange}
        onValueChange={(values) => {
          if (values.length === 0) {
            field.setRule(undefined);
          } else {
            setValues(field, values);
          }
        }}
      >
        <CascaderTrigger render={<TooltipTrigger render={trigger} />} />
        <CascaderContent align={align} className="w-64">
          <CascaderSearch
            aria-label={`Search ${field.label}`}
            placeholder={`Search ${field.label.toLocaleLowerCase()}…`}
          />
          <CascaderEmpty>No options found.</CascaderEmpty>
          <CascaderList>
            {(node) => (
              <OptionRow
                node={node}
                count={
                  counts === undefined || node.children !== undefined
                    ? undefined
                    : (counts.get(node.value) ?? 0)
                }
              />
            )}
          </CascaderList>
          {footer}
        </CascaderContent>
      </Cascader>
      <TooltipContent>{optionLabels(field).join(", ")}</TooltipContent>
    </Tooltip>
  );
};

/**
 * Opens a field's value editor from a trigger: a searchable cascader for option fields, a popover
 * for the others. A text, number or date filter left without a value is removed when it closes.
 */
const FilterValueControl = ({
  field,
  trigger,
  open,
  onOpenChange,
  footer,
  align = "start",
}: FilterValueControlProps) => {
  if (isOptionType(field.type)) {
    return (
      <FilterOptionMenu
        field={field}
        trigger={trigger}
        open={open}
        onOpenChange={onOpenChange}
        footer={footer}
        align={align}
      />
    );
  }

  return (
    <Popover
      open={open}
      onOpenChange={(next) => {
        if (!next && field.rule !== undefined && isRuleEmpty(field.rule)) {
          field.setRule(undefined);
        }

        onOpenChange?.(next);
      }}
    >
      <PopoverTrigger render={trigger} />
      <PopoverContent align={align} className={field.type === "date" ? "w-auto" : "w-64"}>
        <FilterValueEditor field={field} />
        {footer}
      </PopoverContent>
    </Popover>
  );
};

// Chip mode

/** The menu that changes a filter's operator. */
const FilterOperatorMenu = ({ field }: { field: FilterField }) => {
  const { rule } = field;

  if (rule === undefined) {
    return null;
  }

  const count = rule.values.length;

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={<Button variant="outline" size="sm" className="text-muted-foreground" />}
      >
        {getOperatorLabel(field.type, rule.operator, count)}
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start">
        <DropdownMenuRadioGroup
          value={rule.operator}
          onValueChange={(operator) => {
            if (isFilterOperator(operator)) {
              field.setRule(changeOperator(rule, operator));
            }
          }}
        >
          {filterOperators[field.type].map((operator) => (
            <DropdownMenuRadioItem key={operator} value={operator}>
              {getOperatorLabel(field.type, operator, count)}
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
};

interface FilterChipProps {
  field: FilterField;
  /** Whether the value editor is open, for a bar that opens it when the filter is added. */
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  className?: string;
}

/** One active filter as a chip: field, operator, value, and a remove button. */
const FilterChip = ({ field, open, onOpenChange, className }: FilterChipProps) => {
  const summary = summarize(field);

  return (
    <ButtonGroup data-slot="filter-chip" aria-label={`${field.label} filter`} className={className}>
      {/* The field segment takes the buttons' surface and size so the chip reads as one control. */}
      <span
        data-slot="filter-chip-field"
        className={cn(
          buttonVariants({ size: "sm", variant: "outline" }),
          "pointer-events-none cursor-default",
        )}
      >
        {field.icon === undefined ? null : (
          <Icon
            name={field.icon}
            aria-hidden="true"
            data-icon="inline-start"
            className="text-muted-foreground"
          />
        )}
        {field.label}
      </span>
      <FilterOperatorMenu field={field} />
      <FilterValueControl
        field={field}
        open={open}
        onOpenChange={onOpenChange}
        trigger={
          <Button variant="outline" size="sm" className="max-w-56">
            <span className={cn("truncate", summary === null && "text-muted-foreground")}>
              {summary ?? "Choose…"}
            </span>
          </Button>
        }
      />
      <Button
        variant="outline"
        size="icon-sm"
        aria-label={`Remove ${field.label} filter`}
        onClick={() => {
          field.setRule(undefined);
        }}
      >
        <Icon name="x" aria-hidden="true" />
      </Button>
    </ButtonGroup>
  );
};

interface FilterMenuProps {
  filters: Filters;
  /** Called with a text, number or date field just added, so its value editor can open. */
  onFieldAdded?: (id: string) => void;
  className?: string;
  children?: React.ReactNode;
}

/** The menu value of a field, or of one of its options. JSON keeps any id and value apart. */
const menuValue = (id: string, option?: string) =>
  JSON.stringify(option === undefined ? [id] : [id, option]);

interface MenuTarget {
  field: FilterField;
  /** The option a row chooses, or none for a field row. */
  option?: string;
}

/**
 * The fields as the top level of the add-filter menu. An option field opens its option tree; a
 * text, number or date field is a row of its own, checked while the field has a filter.
 */
const toFieldTree = (fields: readonly FilterField[]) => {
  const targets = new Map<string, MenuTarget>();
  const counts = new Map<string, number>();
  const selected: string[] = [];

  const items = fields.map((field): CascaderNode => {
    const value = menuValue(field.id);

    const icon =
      field.icon === undefined ? undefined : <Icon name={field.icon} aria-hidden="true" />;

    targets.set(value, { field });

    if (!isOptionType(field.type)) {
      if (field.rule !== undefined) {
        selected.push(value);
      }

      return { icon, label: field.label, value };
    }

    forEachLeaf(field.options, (option) => {
      const key = menuValue(field.id, option.value);

      targets.set(key, { field, option: option.value });

      if (field.counts !== undefined) {
        counts.set(key, field.counts.get(option.value) ?? 0);
      }
    });

    for (const chosen of chosenValues(field)) {
      selected.push(menuValue(field.id, chosen));
    }

    return {
      children: toOptionNodes(field.options, (option) => menuValue(field.id, option.value)),
      icon,
      label: field.label,
      value,
    };
  });

  return { counts, items, selected, targets };
};

/**
 * The searchable menu that adds filters, built on the cascader. Option fields open their options
 * in place, and the search finds fields and options at any depth. Text, number and date fields
 * add an empty filter and hand off to its value editor.
 */
const FilterMenu = ({ filters, onFieldAdded, className, children = "Filter" }: FilterMenuProps) => {
  const [open, setOpen] = React.useState(false);
  // The field to open once the menu has closed and returned focus to its trigger.
  const added = React.useRef<string | null>(null);
  const { counts, items, selected, targets } = toFieldTree(filters.fields);

  return (
    <Cascader
      multiple
      searchable
      items={items}
      value={selected}
      open={open}
      onOpenChange={setOpen}
      onOpenChangeComplete={(next) => {
        if (!next && added.current !== null) {
          onFieldAdded?.(added.current);
          added.current = null;
        }
      }}
      onValueChange={(values, { node }) => {
        const target = node === null ? undefined : targets.get(node.value);

        if (node === null || target === undefined) {
          return;
        }

        const checked = values.includes(node.value);
        const { field, option } = target;

        if (option !== undefined) {
          toggleOption(field, option, checked);
        } else if (checked) {
          if (field.rule === undefined) {
            field.setRule(createRule(field.type));
          }

          added.current = field.id;
          setOpen(false);
        } else {
          field.setRule(undefined);
        }
      }}
    >
      <CascaderTrigger render={<Button variant="outline" size="sm" className={className} />}>
        <Icon name="list-filter" aria-hidden="true" data-icon="inline-start" />
        {children}
      </CascaderTrigger>
      <CascaderContent className="w-64">
        <CascaderSearch aria-label="Search filters" placeholder="Filter by…" />
        <CascaderEmpty>No filters found.</CascaderEmpty>
        <CascaderList>
          {(node) => <OptionRow node={node} count={counts.get(node.value)} />}
        </CascaderList>
      </CascaderContent>
    </Cascader>
  );
};

interface FilterBarProps extends Omit<React.ComponentProps<"div">, "children"> {
  filters: Filters;
  /** Content after the chips, such as a search input or view options. */
  children?: React.ReactNode;
}

/** Chip mode: an add-filter menu, a chip for each active filter, and a clear action. */
const FilterBar = ({ filters, className, children, ...props }: FilterBarProps) => {
  const [openId, setOpenId] = React.useState<string | null>(null);

  return (
    <div
      data-slot="filter-bar"
      className={cn("flex min-w-0 flex-wrap items-center gap-related", className)}
      {...props}
    >
      <FilterMenu filters={filters} onFieldAdded={setOpenId} />
      {filters.active.map((field) => (
        <FilterChip
          key={field.id}
          field={field}
          open={isOptionType(field.type) ? undefined : openId === field.id}
          onOpenChange={(open) => {
            setOpenId(open ? field.id : null);
          }}
        />
      ))}
      {filters.active.length === 0 ? null : (
        <Button
          variant="ghost"
          size="sm"
          onClick={() => {
            filters.clear();
          }}
        >
          Clear
        </Button>
      )}
      {children}
    </div>
  );
};

// Faceted mode

const FacetSummary = ({ field }: { field: FilterField }) => {
  const chosen = field.rule?.values ?? [];

  if (!isOptionType(field.type) || isCounted(field)) {
    return (
      <Badge variant="secondary" className="max-w-40">
        <span className="truncate">{summarize(field)}</span>
      </Badge>
    );
  }

  return chosen.map((value) => (
    <Badge key={String(value)} variant="secondary">
      {formatValue(field, value)}
    </Badge>
  ));
};

const FacetClear = ({ field }: { field: FilterField }) => {
  if (!isOptionType(field.type)) {
    return (
      <Button
        variant="ghost"
        size="sm"
        onClick={() => {
          field.setRule(undefined);
        }}
      >
        Clear filter
      </Button>
    );
  }

  // Clearing the cascader's selection removes the filter.
  return <CascaderClear>Clear filter</CascaderClear>;
};

interface FilterFacetProps {
  field: FilterField;
  className?: string;
}

/**
 * Faceted mode: a button for one field that shows its chosen values and opens its value editor.
 * Option fields mean "is any of"; text, number and date fields use their first operator.
 */
const FilterFacet = ({ field, className }: FilterFacetProps) => {
  const active = field.rule !== undefined && !isRuleEmpty(field.rule);

  return (
    <FilterValueControl
      field={field}
      footer={active || isOptionType(field.type) ? <FacetClear field={field} /> : null}
      trigger={
        <Button
          data-slot="filter-facet"
          variant="outline"
          size="sm"
          // Badges are as tall as the padded content box, so the padding goes and the height stays.
          className={cn("border-dashed has-data-[slot=badge]:py-0", className)}
        >
          <Icon
            name={active ? (field.icon ?? "list-filter") : "circle-fading-plus"}
            aria-hidden="true"
            data-icon="inline-start"
          />
          {field.label}
          {active ? (
            <>
              <Separator orientation="vertical" className="mx-0.5 -my-px h-auto self-stretch" />
              <FacetSummary field={field} />
            </>
          ) : null}
        </Button>
      }
    />
  );
};

interface FilterFacetsProps extends Omit<React.ComponentProps<"div">, "children"> {
  filters: Filters;
  /** The fields to show, by id, in order. Left out, every filterable field is shown. */
  fields?: string[];
  /** Content before the buttons, such as a search input. */
  children?: React.ReactNode;
}

/** Faceted mode: a button per field, then a reset action while any filter is active. */
const FilterFacets = ({ filters, fields, className, children, ...props }: FilterFacetsProps) => {
  const shown =
    fields === undefined
      ? filters.fields
      : fields.flatMap((id) => filters.fields.filter((field) => field.id === id));

  return (
    <div
      data-slot="filter-facets"
      className={cn("flex min-w-0 flex-wrap items-center gap-related", className)}
      {...props}
    >
      {children}
      {shown.map((field) => (
        <FilterFacet key={field.id} field={field} />
      ))}
      {filters.active.length === 0 ? null : (
        <Button
          variant="ghost"
          size="sm"
          onClick={() => {
            filters.clear();
          }}
        >
          Reset
          <Icon name="x" aria-hidden="true" data-icon="inline-end" />
        </Button>
      )}
    </div>
  );
};

export {
  FilterBar,
  FilterChip,
  FilterFacet,
  FilterFacets,
  FilterMenu,
  FilterOperatorMenu,
  FilterOptionMenu,
  FilterValueControl,
  FilterValueEditor,
};

export type {
  FilterBarProps,
  FilterChipProps,
  FilterFacetProps,
  FilterFacetsProps,
  FilterMenuProps,
  FilterValueControlProps,
};

/** Search-row padding belongs to the field; nested actions retain their behavior. */
export const focusSearchInput = (
  container: HTMLElement,
  event: Pick<PointerEvent, "button" | "target" | "defaultPrevented" | "preventDefault">,
) => {
  if (event.button !== 0 || event.defaultPrevented) {
    return;
  }

  if (
    event.target instanceof Element &&
    event.target.closest("input, button, a, select, textarea")
  ) {
    return;
  }

  const input = container.querySelector("input");

  if (!input || input.disabled) {
    return;
  }

  event.preventDefault();
  input.focus();
};

import * as React from "react";
import { useMergedRefs } from "@base-ui/utils/useMergedRefs";
import {
  createFormHook,
  createFormHookContexts,
  revalidateLogic,
  useSelector,
} from "@tanstack/react-form";
import type { AnyFieldMeta, AnyFormApi } from "@tanstack/react-form";
import { Option, Schema, SchemaTransformation } from "effect";
import { shake } from "@/registry/erbium/lib/shake";
import { Checkbox } from "@/registry/erbium/ui/checkbox";
import {
  Field as FieldRoot,
  FieldContent,
  FieldDescription,
  FieldError as FieldErrorMessage,
  FieldLabel,
  useFieldRequired,
} from "@/registry/erbium/ui/field";
import { Input } from "@/registry/erbium/ui/input";
import { OTPField as OTPFieldControl } from "@/registry/erbium/ui/otp-field";
import { PasswordInput } from "@/registry/erbium/ui/password-input";
import type { OTPFieldProps } from "@/registry/erbium/ui/otp-field";
import { StatefulButton } from "@/registry/erbium/ui/stateful-button";
import type { StatefulButtonProps, StatefulButtonState } from "@/registry/erbium/ui/stateful-button";
import { Switch } from "@/registry/erbium/ui/switch";
import { Textarea } from "@/registry/erbium/ui/textarea";

/*
 * TanStack Form bound to Erbium fields, validated with Effect Schema.
 *
 * Pass an Effect Schema to a validator through `Schema.toStandardSchemaV1`.
 * TanStack Form stores its failures in `field.state.meta.errors` as Standard
 * Schema issues (`{ message, path }`); the bound fields decode those and show
 * the messages in `FieldError`.
 *
 * Opinions baked in:
 * - `useAppForm` defaults to `revalidateLogic()`: `onDynamic` validators run on
 *   submit, then on every change once the user has tried to submit.
 * - A field shows its errors only after it is touched. Typing, blurring and
 *   submitting all touch it.
 * - A rejected submit shakes every invalid field. `FormField` owns the shake,
 *   so a field composed by hand (a select, radio group, autocomplete) shakes
 *   the same way as the prebuilt ones.
 */

const { fieldContext, formContext, useFieldContext, useFormContext } = createFormHookContexts();

/** A Standard Schema issue, e.g. an Effect Schema failure, read as its message. */
const IssueMessage = Schema.Struct({ message: Schema.String }).pipe(
  Schema.decodeTo(
    Schema.String,
    SchemaTransformation.transform({
      decode: (issue) => issue.message,
      encode: (message) => ({ message }),
    }),
  ),
);

/**
 * One entry of `field.state.meta.errors`: a string returned by a validator
 * function, or a Standard Schema issue from a schema validator.
 */
const ValidationMessage = Schema.Union([Schema.String, IssueMessage]);

const decodeValidationMessage = Schema.decodeUnknownOption(ValidationMessage);

/**
 * The messages a field shows: none until the user has touched it. Errors that
 * are neither a string nor an issue with a message are left out.
 */
const visibleMessages = (meta: AnyFieldMeta): string[] =>
  meta.isTouched
    ? meta.errors.flatMap((entry) => Option.toArray(decodeValidationMessage(entry)))
    : [];

const useFieldMeta = () => {
  const field = useFieldContext<unknown>();

  return useSelector(field.store, (state) => state.meta);
};

const useVisibleMessages = () => {
  const meta = useFieldMeta();

  return React.useMemo(() => visibleMessages(meta), [meta]);
};

/**
 * How much of the field a rejected submit shakes. `"auto"` shakes the whole
 * row of a choice field (a checkbox, radio or switch beside its label, the
 * same rows the `choice-row` variant aligns) and the control of any other.
 */
type FormFieldShake = "auto" | "control" | "field";

/** Matches `choice-row` in variants.css: a choice control beside a direct label. */
const CHOICE_ROW =
  ':has(> [data-choice]):has(> [data-slot="field-label"], > [data-slot="field-content"])';

/** Parts of a field that frame its control rather than being the control. */
const FIELD_CHROME = [
  '[data-slot="field-label"]',
  '[data-slot="field-description"]',
  '[data-slot="field-error"]',
  '[data-slot="field-content"]',
  '[aria-hidden="true"]',
  'input[type="hidden"]',
  ".sr-only",
].join(",");

/**
 * The elements a rejected submit shakes. A control is every direct child of
 * the field root that is not its label, description, error or a hidden helper
 * such as Base UI Select's validation input. That covers an input, an input
 * group, a select trigger, a radio group and an OTP field without each control
 * registering itself. Falls back to the root when nothing qualifies.
 */
const shakeTargets = (root: Element, shakeOn: FormFieldShake): Element[] => {
  if (shakeOn === "field" || (shakeOn === "auto" && root.matches(CHOICE_ROW))) {
    return [root];
  }

  const controls = [...root.children].filter((child) => !child.matches(FIELD_CHROME));

  return controls.length > 0 ? controls : [root];
};

/** Replays the error shake on the field after each submit that left it invalid. */
const useShakeOnRejectedSubmit = (
  rootRef: React.RefObject<Element | null>,
  shakeOn: FormFieldShake,
) => {
  const field = useFieldContext<unknown>();
  const attempts = useSelector(field.form.store, (state) => state.submissionAttempts);
  const submitting = useSelector(field.form.store, (state) => state.isSubmitting);
  const shaken = React.useRef(attempts);

  React.useEffect(() => {
    if (submitting || attempts === shaken.current) {
      return;
    }

    shaken.current = attempts;

    const root = rootRef.current;

    if (root && field.state.meta.errors.length > 0) {
      for (const target of shakeTargets(root, shakeOn)) {
        shake(target);
      }
    }
  }, [attempts, field, rootRef, shakeOn, submitting]);
};

type FieldProps = Omit<
  React.ComponentProps<typeof FieldRoot>,
  "dirty" | "invalid" | "name" | "touched"
> & {
  /**
   * What a rejected submit shakes. `"auto"` (default) shakes a choice row
   * whole and the control of any other field; `"control"` and `"field"` force
   * one or the other.
   */
  shakeOn?: FormFieldShake;
};

/**
 * `Field` bound to the surrounding `form.AppField`: name, invalid, touched and
 * dirty come from TanStack Form. Compose any label, description and control
 * inside it; invalid follows the visible errors, and a rejected submit shakes
 * the field (see `shakeOn`). Controls need no shake wiring of their own.
 */
const FormField = ({ ref, shakeOn = "auto", ...props }: FieldProps) => {
  const field = useFieldContext<unknown>();
  const meta = useFieldMeta();
  const messages = useVisibleMessages();
  const rootRef = React.useRef<HTMLDivElement | null>(null);
  useShakeOnRejectedSubmit(rootRef, shakeOn);

  return (
    <FieldRoot
      ref={useMergedRefs(ref, rootRef)}
      name={field.name}
      invalid={messages.length > 0}
      touched={meta.isTouched}
      dirty={meta.isDirty}
      {...props}
    />
  );
};

/** `FieldError` showing the surrounding field's visible messages. */
const FormFieldError = (
  props: Omit<React.ComponentProps<typeof FieldErrorMessage>, "errors" | "match">,
) => {
  const messages = useVisibleMessages();

  return <FieldErrorMessage errors={messages} {...props} />;
};

type LabelledFieldProps = Pick<FieldProps, "className" | "hidden" | "orientation"> & {
  /** Helper text below the control. The error replaces it while invalid. */
  description?: React.ReactNode;
  label: React.ReactNode;
};

const Description = ({ children }: { children?: React.ReactNode }) =>
  children === undefined ? null : <FieldDescription>{children}</FieldDescription>;

type TextFieldProps = LabelledFieldProps &
  Omit<
    React.ComponentProps<typeof Input>,
    "className" | "defaultValue" | "hidden" | "name" | "onBlur" | "onChange" | "ref" | "value"
  >;

/** A labelled text input for a string field. */
const TextField = ({
  className,
  description,
  hidden,
  label,
  orientation,
  required,
  ...props
}: TextFieldProps) => {
  const field = useFieldContext<string>();

  return (
    <FormField className={className} hidden={hidden} orientation={orientation} required={required}>
      <FieldLabel>{label}</FieldLabel>
      <Input
        value={field.state.value}
        onBlur={field.handleBlur}
        onChange={(event) => {
          field.handleChange(event.target.value);
        }}
        required={required}
        {...props}
      />
      <Description>{description}</Description>
      <FormFieldError />
    </FormField>
  );
};

type PasswordFieldProps = LabelledFieldProps &
  Omit<
    React.ComponentProps<typeof PasswordInput>,
    "className" | "defaultValue" | "hidden" | "name" | "onBlur" | "onChange" | "ref" | "value"
  >;

/**
 * A labelled `PasswordInput` for a string field. Pressing the show/hide toggle
 * with a pointer keeps focus in the input, so it does not touch the field. A
 * rejected submit shakes the whole input group, toggle included, since the
 * group is the field's control.
 */
const PasswordField = ({
  className,
  description,
  hidden,
  label,
  orientation,
  required,
  ...props
}: PasswordFieldProps) => {
  const field = useFieldContext<string>();

  return (
    <FormField className={className} hidden={hidden} orientation={orientation} required={required}>
      <FieldLabel>{label}</FieldLabel>
      <PasswordInput
        value={field.state.value}
        onBlur={field.handleBlur}
        onChange={(event) => {
          field.handleChange(event.target.value);
        }}
        required={required}
        {...props}
      />
      <Description>{description}</Description>
      <FormFieldError />
    </FormField>
  );
};

type TextareaFieldProps = LabelledFieldProps &
  Omit<
    React.ComponentProps<typeof Textarea>,
    "className" | "defaultValue" | "hidden" | "name" | "onBlur" | "onChange" | "ref" | "value"
  >;

/** A labelled textarea for a string field. */
const TextareaField = ({
  className,
  description,
  hidden,
  label,
  orientation,
  required,
  ...props
}: TextareaFieldProps) => {
  const field = useFieldContext<string>();

  return (
    <FormField className={className} hidden={hidden} orientation={orientation} required={required}>
      <FieldLabel>{label}</FieldLabel>
      <Textarea
        value={field.state.value}
        onBlur={field.handleBlur}
        onChange={(event) => {
          field.handleChange(event.target.value);
