    <OTPFieldPrimitive.Input
      data-slot="otp-field-input"
      data-status={status === "idle" ? undefined : status}
      spellCheck={false}
      render={
        render ??
        ((inputProps, state) => (
          <span className="relative inline-flex">
            <input {...inputProps} />
            {status === "loading" && (
              <span
                aria-hidden
                className="pointer-events-none absolute inset-0 flex items-center justify-center text-field text-muted-foreground"
              >
                <span className="shimmer motion-reduce:animate-none [--shimmer-color:color-mix(in_oklab,currentColor_35%,transparent)] [--shimmer-spread:1.5ch]">
                  {state.value}
                </span>
              </span>
            )}
          </span>
        ))
      }
      className={cn(
        "relative size-control min-w-0 rounded-lg border surface-field text-center text-field outline-none transition-[color,background-color,border-color,box-shadow] duration-150 focus-visible:z-10 focus-visible:border-ring focus-visible:ring-[1.5px] focus-visible:ring-focus-halo-strong motion-reduce:transition-none data-invalid:border-error data-[status=error]:border-error focus-visible:data-invalid:ring-0 data-disabled:cursor-not-allowed data-disabled:opacity-50 dark:data-invalid:border-invalid dark:data-[status=error]:border-invalid data-[status=success]:border-success data-[status=success]:text-success-soft-foreground data-[status=loading]:text-transparent motion-safe:data-[status=loading]:animate-pulse",
        className,
      )}
      {...props}
    />
  );
};

const OTPFieldSeparator = ({ className, ...props }: OTPFieldPrimitive.Separator.Props) => (
  <OTPFieldPrimitive.Separator
    render={
      <Separator
        data-slot="otp-field-separator"
        orientation="horizontal"
        variant="full"
        className={cn("rounded-full data-horizontal:w-3 data-horizontal:self-auto", className)}
      />
    }
    {...props}
  />
);

const OTPFieldSlots = ({ groups, length }: { groups?: number[]; length: number }) => {
  const sizes = groups ?? [length];
  let index = 0;

  return sizes.map((size, groupIndex) => {
    const start = index;
    index += size;

    return (
      <React.Fragment key={start}>
        {groupIndex > 0 && <OTPFieldSeparator />}
        <OTPFieldGroup>
          {Array.from({ length: size }, (_, offset) => {
            const slot = start + offset;

            return (
              <OTPFieldInput
                key={slot}
                aria-label={slot === 0 ? undefined : `Character ${slot + 1} of ${length}`}
              />
            );
          })}
        </OTPFieldGroup>
      </React.Fragment>
    );
  });
};

const otpFieldStatus = (
  value: string | undefined,
  length: number,
  validation: OTPFieldValidation | undefined,
  verifiedValue: string | undefined,
): OTPFieldStatus => {
  const complete = value?.length === length;

  if (validation?.isValidating === true && complete) {
    return "loading";
  }

  if (validation?.isTouched === true && !validation.isValid) {
    return "error";
  }

  if (validation?.isValid === true && complete && value === verifiedValue) {
    return "success";
  }

  return "idle";
};

const assignRef = <T,>(ref: React.Ref<T> | undefined, node: T | null) => {
  if (ref === null || ref === undefined) {
    return;
  }

  if ("current" in ref) {
    ref.current = node;
  } else {
    ref(node);
  }
};

type OTPFieldProps = OTPFieldPrimitive.Root.Props & {
  /** Validation metadata owned by the form library. Does not lock editing. */
  validation?: OTPFieldValidation;
  /** Value confirmed by verification. Valid form metadata alone does not imply success. */
  verifiedValue?: string;
  /**
   * Splits the default slots into visual groups, e.g. `[3, 3]` renders
   * `123-456`. Ignored when `children` are passed.
   */
  groups?: number[];
};

const OTPField = ({
  className,
  children,
  groups,
  length,
  readOnly,
  ref,
  validation,
  verifiedValue,
  value,
  ...props
}: OTPFieldProps) => {
  const rootRef = React.useRef<HTMLDivElement | null>(null);

  const status = otpFieldStatus(value, length, validation, verifiedValue);

  React.useEffect(() => {
    if (status === "error") {
      shake(rootRef.current);
    }
  }, [status]);

  return (
    <OTPFieldStatusContext value={status}>
      <OTPFieldPrimitive.Root
        data-slot="otp-field"
        data-status={status === "idle" ? undefined : status}
        aria-busy={status === "loading" || undefined}
        length={length}
        readOnly={readOnly}
        value={value}
        ref={(node) => {
          rootRef.current = node;

          assignRef(ref, node);
        }}
        className={cn("flex w-fit items-center gap-related", className)}
        {...props}
      >
        {children ?? <OTPFieldSlots groups={groups} length={length} />}
      </OTPFieldPrimitive.Root>
    </OTPFieldStatusContext>
  );
};

export type { OTPFieldProps, OTPFieldValidation };

export { OTPField, OTPFieldGroup, OTPFieldInput, OTPFieldSeparator };

import * as React from "react";
import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import { useMergedRefs } from "@base-ui/utils/useMergedRefs";
import type { AnyRouter, RegisteredRouter } from "@tanstack/react-router";
import { usePagination } from "@/registry/erbium/hooks/use-pagination";
import type { PaginationOptions } from "@/registry/erbium/hooks/use-pagination";
import { usePredictedIntent } from "@/registry/erbium/hooks/use-predicted-intent";
import { buttonVariants } from "@/registry/erbium/lib/button-variants";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import { Icon } from "@/registry/erbium/ui/icon";
import { linkFromTarget, linkTarget } from "@/registry/erbium/ui/link";
import type { AnyLinkTargetProps, HrefTargetProps, LinkTargetProps, NoTargetProps } from "@/registry/erbium/ui/link";

type PaginationSize = "default" | "icon" | "sm" | "icon-sm";

const pageClassName = (isActive: boolean | undefined, size: PaginationSize, className?: string) =>
  cn(
    buttonVariants({ size, variant: isActive === true ? "outline" : "ghost" }),
    "tabular-nums",
    className,
  );

const Pagination = ({ className, ...props }: React.ComponentProps<"nav">) => (
  <nav
    aria-label="pagination"
    data-slot="pagination"
    className={cn("mx-auto flex w-full justify-center", className)}
    {...props}
  />
);

const PaginationContent = ({ className, ...props }: React.ComponentProps<"ul">) => (
  <ul
    data-slot="pagination-content"
    className={cn("flex items-center gap-0.5", className)}
    {...props}
  />
);

const PaginationItem = ({ ...props }: React.ComponentProps<"li">) => (
  <li data-slot="pagination-item" {...props} />
);

interface PaginationLinkOwnProps {
  isActive?: boolean;
  size?: PaginationSize;
}

type PaginationLinkProps = ((useRender.ComponentProps<"a"> & NoTargetProps) | HrefTargetProps) &
  PaginationLinkOwnProps;

/**
 * A page link. It takes Router's link options, such as `to="." search={{ page }}`, so the page
 * preloads before the click; `href` takes a fully built URL.
 */
function PaginationLink(props: PaginationLinkProps): React.ReactElement;

// Restores Router's generics, so `to` and `search` type against the app's routes.
function PaginationLink<
  TRouter extends AnyRouter = RegisteredRouter,
  const TFrom extends string = string,
  const TTo extends string | undefined = undefined,
  const TMaskFrom extends string = TFrom,
  const TMaskTo extends string = "",
>(
  props: LinkTargetProps<TRouter, TFrom, TTo, TMaskFrom, TMaskTo> & PaginationLinkOwnProps,
): React.ReactElement;

function PaginationLink({
  className,
  isActive,
  size = "icon",
  render,
  to,
  href,
  ...props
}: PaginationLinkProps | (AnyLinkTargetProps & PaginationLinkOwnProps & { render?: never })) {
  return useRender({
    defaultTagName: "a",
    props: mergeProps(
      {
        "aria-current": isActive === true ? "page" : undefined,
        className: pageClassName(isActive, size, className),
      },
      props,
    ),
    render: linkTarget({ href, render, to }),
    state: { active: isActive === true, slot: "pagination-link" },
  });
}

type PaginationButtonProps = Omit<React.ComponentProps<"button">, "type"> & {
  isActive?: boolean;
  size?: PaginationSize;
  /**
   * Called when the user is about to press the button: the cursor is heading for it, it is a
   * tab stop or two away, or a finger touches it. Use it to fetch the page ahead of time.
   */
  onIntent?: () => void;
};

/**
 * A page button, for pages kept in state rather than in the URL, such as a table's page
 * index.
 */
const PaginationButton = ({
  className,
  isActive,
  size = "icon",
  onIntent,
  disabled,
  ref,
  ...props
}: PaginationButtonProps) => {
  const intentRef = usePredictedIntent(
    () => {
      onIntent?.();
    },
    { enabled: onIntent !== undefined && disabled !== true && isActive !== true },
  );

  return (
    <button
      type="button"
      ref={useMergedRefs(ref, intentRef)}
      aria-current={isActive === true ? "page" : undefined}
      data-slot="pagination-button"
      data-active={isActive === true ? "" : undefined}
      data-disabled={disabled === true ? "" : undefined}
      disabled={disabled}
      className={pageClassName(isActive, size, className)}
      {...props}
    />
  );
};

interface PaginationStepOwnProps {
  /**
   * Marks the step unavailable, on the first or last page. A plain step loses its `href`; a
   * link drops its destination, and a rendered `PaginationButton` disables natively.
   */
  disabled?: boolean;
  text?: string;
}

type PaginationStepProps = ((useRender.ComponentProps<"a"> & NoTargetProps) | HrefTargetProps) &
  PaginationStepOwnProps;

type PaginationStepImplementationProps =
  | PaginationStepProps
  | (AnyLinkTargetProps & PaginationStepOwnProps & { render?: never });

// A plain `a` loses its `href`, and with it its role, so it keeps `role="link"`. A link or a
// rendered element receives `disabled`, which router links and native buttons both honor.
const disabledStepProps = (isPlainAnchor: boolean) =>
  isPlainAnchor
    ? { "aria-disabled": true, "data-disabled": "", href: undefined, role: "link" }
    : { disabled: true };

const PaginationStep = ({
  className,
  disabled = false,
  render,
  to,
  href,
  children,
  ...props
}: PaginationStepImplementationProps & { children: React.ReactNode }) => {
  const element = linkTarget({ href, render, to });

  return useRender({
    defaultTagName: "a",
    props: mergeProps(
      { children, className: pageClassName(false, "default", className) },
      props,
      // Applied last so nothing passed can make a disabled step navigable.
      disabled ? disabledStepProps(element === undefined) : {},
    ),
    render: element,
  });
};

/** The step to the previous page. It takes the same link options as `PaginationLink`. */
function PaginationPrevious(props: PaginationStepProps): React.ReactElement;

function PaginationPrevious<
  TRouter extends AnyRouter = RegisteredRouter,
  const TFrom extends string = string,
  const TTo extends string | undefined = undefined,
  const TMaskFrom extends string = TFrom,
  const TMaskTo extends string = "",
>(
  props: LinkTargetProps<TRouter, TFrom, TTo, TMaskFrom, TMaskTo> & PaginationStepOwnProps,
): React.ReactElement;

function PaginationPrevious({
  className,
  text = "Previous",
  ...props
}: PaginationStepImplementationProps) {
  return (
    <PaginationStep
      aria-label="Go to previous page"
      data-slot="pagination-previous"
      className={cn("ps-1.5!", className)}
      {...props}
    >
      <Icon name="chevron-left" data-icon="inline-start" className="rtl:rotate-180" />
      <span className="hidden sm:block">{text}</span>
    </PaginationStep>
  );
}

/** The step to the next page. It takes the same link options as `PaginationLink`. */
function PaginationNext(props: PaginationStepProps): React.ReactElement;

function PaginationNext<
  TRouter extends AnyRouter = RegisteredRouter,
  const TFrom extends string = string,
  const TTo extends string | undefined = undefined,
  const TMaskFrom extends string = TFrom,
  const TMaskTo extends string = "",
>(
  props: LinkTargetProps<TRouter, TFrom, TTo, TMaskFrom, TMaskTo> & PaginationStepOwnProps,
): React.ReactElement;

function PaginationNext({ className, text = "Next", ...props }: PaginationStepImplementationProps) {
  return (
    <PaginationStep
      aria-label="Go to next page"
      data-slot="pagination-next"
      className={cn("pe-1.5!", className)}
      {...props}
    >
      <span className="hidden sm:block">{text}</span>
      <Icon name="chevron-right" data-icon="inline-end" className="rtl:rotate-180" />
    </PaginationStep>
  );
}

const PaginationEllipsis = ({ className, ...props }: React.ComponentProps<"span">) => (
  <span
    aria-hidden
    data-slot="pagination-ellipsis"
    className={cn(
      "flex size-control items-center justify-center [&_svg:not([class*='size-'])]:size-4",
      className,
    )}
    {...props}
  >
    <Icon name="more-horizontal" />
    <span className="sr-only">More pages</span>
  </span>
);

/** Router's link options for one page. */
type PaginationLinkOptions =
  | Omit<AnyLinkTargetProps, "children">
  | Omit<HrefTargetProps, "children">;

type PaginationControlsProps = PaginationOptions &
  Omit<React.ComponentProps<"ul">, "children"> &
  (
    | {
        /**
         * Returns Router's link options for a page, for pages kept in the URL, so each page
         * preloads before the click: `(page) => ({ to: ".", search: { page } })`. Build typed
         * options with Router's `linkOptions`.
         */
        linkOptions: (page: number) => PaginationLinkOptions;
        onPageChange?: never;
        onPageIntent?: never;
      }
    | {
        linkOptions?: never;
        /** Called with the chosen page, for pages kept in state. Renders buttons. */
        onPageChange: (page: number) => void;
        /**
         * Called when the user is about to choose a page, before the click. Use it to fetch
         * the page ahead of time.
         */
        onPageIntent?: (page: number) => void;
      }
  );

/**
 * Previous, page, and next controls laid out by `usePagination`. With `linkOptions` the controls
 * are links, for pages in the URL; with `onPageChange` they are buttons, for pages in state
 * such as a table's.
 */
const PaginationControls = ({
  page,
  pageCount,
  siblingCount,
  boundaryCount,
  linkOptions,
  onPageChange,
  onPageIntent,
  ...props
}: PaginationControlsProps) => {
  const pagination = usePagination({ boundaryCount, page, pageCount, siblingCount });

  // Buttons for state-driven pages; links otherwise.
  const step = (target: number | undefined) => {
    if (onPageChange === undefined) {
      return target === undefined
        ? { disabled: true }
        : { render: linkFromTarget(linkOptions(target)) };
    }

    return {
      disabled: target === undefined,
      render: (
        <PaginationButton
          size="default"
          onClick={() => {
            if (target !== undefined) {
              onPageChange(target);
            }
          }}
          onIntent={
            target === undefined || onPageIntent === undefined
              ? undefined
              : () => {
                  onPageIntent(target);
                }
          }
        />
      ),
    };
  };

  return (
    <PaginationContent {...props}>
      <PaginationItem>
        <PaginationPrevious {...step(pagination.previousPage)} />
      </PaginationItem>
      {pagination.items.map((item) =>
        item.type === "ellipsis" ? (
          <PaginationItem key={item.key}>
            <PaginationEllipsis />
          </PaginationItem>
        ) : (
          <PaginationItem key={item.page}>
            {onPageChange === undefined ? (
              <PaginationLink
                isActive={item.current}
                render={linkFromTarget(linkOptions(item.page))}
              >
                {item.page}
              </PaginationLink>
            ) : (
              <PaginationButton
                isActive={item.current}
                onClick={() => {
                  onPageChange(item.page);
                }}
                onIntent={
                  onPageIntent === undefined
                    ? undefined
                    : () => {
                        onPageIntent(item.page);
                      }
                }
              >
                {item.page}
              </PaginationButton>
            )}
          </PaginationItem>
        ),
      )}
      <PaginationItem>
        <PaginationNext {...step(pagination.nextPage)} />
      </PaginationItem>
    </PaginationContent>
  );
};

export {
  Pagination,
  PaginationButton,
  PaginationContent,
  PaginationControls,
  PaginationEllipsis,
  PaginationItem,
  PaginationLink,
  PaginationNext,
  PaginationPrevious,
};

import * as React from "react";
import { Toggle as TogglePrimitive } from "@base-ui/react/toggle";
import { useRender } from "@base-ui/react/use-render";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import { Icon } from "@/registry/erbium/ui/icon";
import { InputGroup, InputGroupAddon, InputGroupButton, InputGroupInput } from "@/registry/erbium/ui/input-group";
import { StatefulIcon } from "@/registry/erbium/ui/stateful-icon";

/*
 * A password input with a built-in show/hide toggle, composed from InputGroup.
 *
 * Behavior:
 * - The toggle is a pressed-state button named "Show password". The name stays
 *   the same in both states; `aria-pressed` says whether the password shows.
 * - A pointer press keeps focus, caret and selection in the input, so the field
 *   is not blurred (and a form field is not marked touched) by the toggle. A
 *   keyboard press leaves focus on the toggle.
 * - Submitting or resetting the surrounding form hides the password again, so a
 *   revealed value is never left as plain text.
 * - Disabling the root, or the surrounding Field, disables the toggle too. A
 *   read-only input can still be revealed.
 */

type PasswordInputVisibilityChangeReason = "toggle" | "submit" | "reset";

interface PasswordInputVisibilityChangeDetails {
  reason: PasswordInputVisibilityChangeReason;
}

interface PasswordInputContextValue {
  controlDisabled: boolean;
  controlId: string;
  disabled: boolean;
  inputRef: React.RefObject<HTMLInputElement | null>;
  setControlDisabled: (disabled: boolean) => void;
  setControlId: (id: string) => void;
  setVisible: (visible: boolean, details: PasswordInputVisibilityChangeDetails) => void;
  visible: boolean;
}

const PasswordInputContext = React.createContext<PasswordInputContextValue | null>(null);

const usePasswordInputContext = (part: string) => {
  const context = React.useContext(PasswordInputContext);

  if (context === null) {
    throw new Error(`${part} must be used inside PasswordInputRoot.`);
  }

  return context;
};

type Selection = Pick<HTMLInputElement, "selectionDirection" | "selectionEnd" | "selectionStart">;

type PasswordInputRootProps = Omit<React.ComponentProps<typeof InputGroup>, "onChange"> & {
  /** Whether the password shows as text. Controls the visibility. */
  visible?: boolean;
  /** Initial visibility when uncontrolled. */
  defaultVisible?: boolean;
  /** Called before the visibility changes: on a toggle press, form submit or form reset. */
  onVisibleChange?: (visible: boolean, details: PasswordInputVisibilityChangeDetails) => void;
  /** Disables the input and the toggle. */
  disabled?: boolean;
};

/** InputGroup that holds the visibility state shared by the control and the toggle. */
const PasswordInputRoot = ({
  visible: visibleProp,
  defaultVisible = false,
  onVisibleChange,
  disabled = false,
  className,
  ...props
}: PasswordInputRootProps) => {
  const [uncontrolledVisible, setUncontrolledVisible] = React.useState(defaultVisible);
  const visible = visibleProp ?? uncontrolledVisible;
  const generatedId = React.useId();
  const [controlId, setControlId] = React.useState(generatedId);
  const [controlDisabled, setControlDisabled] = React.useState(false);
  const inputRef = React.useRef<HTMLInputElement | null>(null);
  const selection = React.useRef<Selection | null>(null);

  const setVisible = React.useCallback(
    (next: boolean, details: PasswordInputVisibilityChangeDetails) => {
      if (next === visible) {
        return;
      }

      // Changing the input type can move the caret; remember it to restore it.
      const input = inputRef.current;
      selection.current =
        input !== null && input.ownerDocument.activeElement === input
          ? {
              selectionDirection: input.selectionDirection,
              selectionEnd: input.selectionEnd,
              selectionStart: input.selectionStart,
            }
          : null;

      onVisibleChange?.(next, details);

      if (visibleProp === undefined) {
        setUncontrolledVisible(next);
      }
    },
    [onVisibleChange, visible, visibleProp],
  );

  // After a visibility change re-renders the input, restore the saved caret.
  React.useLayoutEffect(() => {
    const input = inputRef.current;
    const saved = selection.current;
    selection.current = null;

    if (
      input === null ||
      saved === null ||
      saved.selectionStart === null ||
      saved.selectionEnd === null ||
      input.ownerDocument.activeElement !== input
    ) {
      return;
    }

    input.setSelectionRange(
      saved.selectionStart,
      saved.selectionEnd,
      saved.selectionDirection ?? undefined,
    );
  });

  const context = React.useMemo<PasswordInputContextValue>(
    () => ({
      controlDisabled,
      controlId,
      disabled,
      inputRef,
      setControlDisabled,
      setControlId,
      setVisible,
      visible,
    }),
    [controlDisabled, controlId, disabled, setVisible, visible],
  );

  return (
    <PasswordInputContext.Provider value={context}>
      <InputGroup
        data-slot="password-input"
        data-visible={visible ? "" : undefined}
        data-disabled={disabled ? "" : undefined}
        className={className}
        {...props}
      />
    </PasswordInputContext.Provider>
  );
};

type PasswordInputControlProps = Omit<React.ComponentProps<typeof InputGroupInput>, "type">;

/**
 * The password `<input>`: `type="password"`, or `type="text"` while shown. It
 * works with Field like any input and defaults to `autoComplete="current-password"`;
 * pass `autoComplete="new-password"` on sign-up and password-change forms.
 */
const PasswordInputControl = ({
  autoCapitalize = "off",
  autoComplete = "current-password",
  className,
  disabled,
  id,
  ref,
  spellCheck = false,
  ...props
}: PasswordInputControlProps) => {
  const context = usePasswordInputContext("PasswordInputControl");
  const { controlId, inputRef, setControlDisabled, setControlId, setVisible, visible } = context;
  const inputId = id ?? controlId;

  React.useEffect(() => {
    setControlId(inputId);
  }, [inputId, setControlId]);

  // A disabled Field disables the input without a prop; mirror it on the toggle.
  React.useLayoutEffect(() => {
    setControlDisabled(inputRef.current?.disabled ?? false);
  });

  // Hide the password when the form is sent or reset.
  React.useEffect(() => {
    const form = inputRef.current?.form;

    const hideOnSubmit = () => {
      setVisible(false, { reason: "submit" });
    };

    const hideOnReset = () => {
      setVisible(false, { reason: "reset" });
    };

    form?.addEventListener("submit", hideOnSubmit);
    form?.addEventListener("reset", hideOnReset);

    return () => {
      form?.removeEventListener("submit", hideOnSubmit);
      form?.removeEventListener("reset", hideOnReset);
    };
  }, [inputRef, setVisible]);

  return useRender({
    props: {
      ...props,
      autoCapitalize,
      autoComplete,
      // Hide the browser's own reveal and clear buttons (Edge).
      className: cn("[&::-ms-clear]:hidden [&::-ms-reveal]:hidden", className),
      "data-visible": visible ? "" : undefined,
      disabled: context.disabled || disabled,
      id: inputId,
      spellCheck,
      type: visible ? "text" : "password",
    },
    ref: [inputRef, ref ?? null],
    render: <InputGroupInput />,
  });
};

/** The toggle's icon: eye-off while hidden, eye while shown. Hidden from assistive technology. */
const PasswordInputIndicator = ({ className }: { className?: string }) => {
  const { visible } = usePasswordInputContext("PasswordInputIndicator");

  return (
    <StatefulIcon
      className={className}
      state={visible ? "visible" : "hidden"}
      icons={{
        hidden: <Icon name="eye-off" />,
        visible: <Icon name="eye" />,
      }}
    />
  );
};

type PasswordInputToggleProps = Omit<
  TogglePrimitive.Props,
  "defaultPressed" | "onPressedChange" | "pressed" | "value"
>;

/** Shows or hides the password. Place it in an `InputGroupAddon`. */
const PasswordInputToggle = ({
  "aria-label": ariaLabel = "Show password",
  children,
  className,
  disabled,
  onClick,
  onMouseDown,
  ...props
}: PasswordInputToggleProps) => {
  const context = usePasswordInputContext("PasswordInputToggle");
  const { controlId, inputRef, setVisible, visible } = context;

  return (
    <TogglePrimitive
      data-slot="password-input-toggle"
      aria-label={ariaLabel}
      aria-controls={controlId}
      pressed={visible}
      disabled={context.disabled || context.controlDisabled || disabled}
      onPressedChange={(pressed) => {
        setVisible(pressed, { reason: "toggle" });
      }}
      onMouseDown={(event) => {
        onMouseDown?.(event);

        // Keep focus, caret and selection in the input on a pointer press.
        if (!event.defaultPrevented) {
          event.preventDefault();
        }
      }}
      onClick={(event) => {
        onClick?.(event);

        const input = inputRef.current;

        // `detail` is 0 for a keyboard press, which keeps focus on the toggle.
        if (event.detail > 0 && input !== null && input.ownerDocument.activeElement !== input) {
          input.focus({ preventScroll: true });
        }
      }}
      render={
        <InputGroupButton
          size="icon-sm"
          // An invalid input paints the eye in the error color, like the label and border.
          className="group-has-[>[data-slot=input-group-control][aria-invalid=true]]/input-group:text-error [&_svg:not([class*='size-'])]:size-control-icon"
        />
      }
      className={className}
      {...props}
    >
      {children ?? <PasswordInputIndicator />}
    </TogglePrimitive>
  );
};

