function SidebarMenuButton<
  TRouter extends AnyRouter = RegisteredRouter,
  const TFrom extends string = string,
  const TTo extends string | undefined = undefined,
  const TMaskFrom extends string = TFrom,
  const TMaskTo extends string = "",
>(
  props: LinkTargetProps<TRouter, TFrom, TTo, TMaskFrom, TMaskTo> & SidebarMenuButtonOwnProps,
): React.ReactElement;

function SidebarMenuButton({
  render,
  to,
  href,
  variant = "default",
  size = "default",
  tooltip,
  className,
  ...props
}: SidebarRowImplementationProps & SidebarMenuButtonOwnProps) {
  const { isMobile, state } = useSidebar();
  const hasTooltip = tooltip !== undefined && tooltip !== "";
  const element = linkTarget({ href, render, to });

  const comp = useRender({
    defaultTagName: "button",
    props: mergeProps(
      {
        className: cn(sidebarMenuButtonVariants({ size, variant }), className),
      },
      props,
    ),
    render: hasTooltip ? <TooltipTrigger render={element} /> : element,
    state: {
      size,
      slot: "sidebar-menu-button",
    },
  });

  if (!hasTooltip) {
    return comp;
  }

  // A string tooltip is shorthand for its content.
  const tooltipProps = tooltip instanceof Object ? tooltip : { children: tooltip };

  return (
    <Tooltip>
      {comp}
      <TooltipContent
        side="right"
        align="center"
        hidden={state !== "collapsed" || isMobile}
        {...tooltipProps}
      />
    </Tooltip>
  );
}

