      <motion.span
        animate={{ y: isOpen ? "-12.5%" : "25%" }}
        className="absolute inset-0"
        initial={false}
        transition={transition}
      >
        <Icon name="chevron-down" className="size-full [--icon-stroke-width:2]" />
