      />
      <motion.rect
        animate={{ width: isOpen ? 6 : 2 }}
        fill="currentColor"
        height="12"
        initial={false}
        rx="1"
        transition={{ duration: reduceMotion ? 0 : duration }}
        x="5"
        y="6"
      />
    </svg>
  );
};

