/* Coarse pointers get a 2.75rem hit area through ::after, centred on the
   control. The visible size stays on the scale above. Apply this to leaf
   controls only: on a container the overlay would cover its children. */
@utility touch-target {
  @media (pointer: coarse) {
    :where(&) {
      position: relative;
    }

    &::after {
      position: absolute;
      top: 50%;
      left: 50%;
      width: max(100%, var(--touch-target-size, 2.75rem));
      height: max(100%, var(--touch-target-size, 2.75rem));
      content: "";
      translate: -50% -50%;
    }
  }
}

