/* Centres a choice control (checkbox, radio, switch) on the first line of the
   label beside it, so it stays put when the label or its description wraps.
   The offset comes from the label's line box and the control's height: a
   control taller or shorter than `--choice-size` publishes `--choice-height`.
   Field applies it through the `choice-row` variant (variants.css); do not
   offset choice controls by hand. */
@utility choice-first-line {
  margin-block-start: max(
    0px,
    calc(
      (
          var(--text-control) * var(--text-control--line-height) -
            var(--choice-height, var(--choice-size))
        ) /
        2
    )
  );
}

