  --font-heading: var(--font-sans);
  --font-mono:
    "Paper Mono", ui-monospace, sfmono-regular, menlo, monaco, consolas, "Liberation Mono",
    "Courier New", monospace;

  color-scheme: light;

  --background: var(--surface-canvas);
