const Tabs = ({ className, orientation = "horizontal", ...props }: TabsPrimitive.Root.Props) => (
  <TabsPrimitive.Root
    data-slot="tabs"
    data-orientation={orientation}
    orientation={orientation}
    className={cn("group/tabs flex gap-related data-horizontal:flex-col", className)}
    {...props}
  />
);

const TabsList = ({ className, children, ...props }: TabsPrimitive.List.Props) => {
  const shouldReduceMotion = useReducedMotion();

  return (
    <TabsPrimitive.List
      data-slot="tabs-list"
      className={cn(
        "relative isolate inline-flex min-h-control w-fit items-center justify-center rounded-lg surface-well p-0.75 text-muted-foreground group-data-vertical/tabs:h-fit group-data-vertical/tabs:flex-col",
        className,
      )}
      {...props}
    >
      {children}
      <TabsPrimitive.Indicator
        data-slot="tabs-indicator"
        className="pointer-events-none absolute top-0 left-0 z-0 rounded-md border surface-control"
        render={(indicatorProps, state) => {
          const position = state.activeTabPosition;
          const size = state.activeTabSize;

          if (!position || !size || size.width === 0 || size.height === 0) {
            return <span {...indicatorProps} />;
          }

          /* Motion owns these handler names with different signatures; the
             indicator never receives them, so they are dropped. */
          const {
            onAnimationStart: _onAnimationStart,
            onDrag: _onDrag,
            onDragEnd: _onDragEnd,
            onDragStart: _onDragStart,
            ...motionProps
          } = indicatorProps;

          return (
            <motion.span
              {...motionProps}
              initial={false}
              animate={{
                height: size.height,
                width: size.width,
                x: position.left,
                y: position.top,
              }}
              transition={
                shouldReduceMotion === true
                  ? { duration: 0 }
                  : { damping: 35, stiffness: 400, type: "spring" }
              }
            />
          );
        }}
      />
    </TabsPrimitive.List>
  );
};

