const toastCloseRender = <Button variant="ghost" size="icon-sm" />;

const ToastClose = ({
  className,
  children,
  render = toastCloseRender,
  ...props
}: ToastPrimitive.Close.Props) => (
  <ToastPrimitive.Close
    data-slot="toast-close"
    aria-label="Close toast"
    render={render}
