import { useEffect, useRef } from "react";
import type { MouseEvent, PointerEvent } from "react";

const INTERACTIVE =
  'a, button:not([data-slot="checkbox"]), input, select, textarea, [contenteditable]';

interface DragSelectOptions {
  /** Returns the index and selected state of the item under the pointer, or `null` when it is not selectable. */
  resolve: (target: Element, container: HTMLElement) => { index: number; selected: boolean } | null;
  /** Applies `selected` to every selectable item from `start` to `end`, inclusive. */
  selectRange: (start: number, end: number, selected: boolean, container: HTMLElement) => void;
}

/**
 * Press on an item and drag across its siblings to select or clear them in one gesture.
 * Spread the returned handlers on the element that contains the items.
 */
export const useDragSelect = ({ resolve, selectRange }: DragSelectOptions) => {
  const drag = useRef<{ index: number; selected: boolean } | null>(null);
  const suppressClick = useRef(false);
  const stopDrag = useRef<() => void>(null);

  useEffect(() => () => stopDrag.current?.(), []);

  return {
    onClickCapture(event: MouseEvent<HTMLElement>) {
      if (suppressClick.current) {
        suppressClick.current = false;
        event.preventDefault();
        event.stopPropagation();
      }
    },
    onPointerDown(event: PointerEvent<HTMLElement>) {
      const { target } = event;

      if (event.button !== 0 || event.pointerType === "touch" || !(target instanceof Element)) {
        return;
      }

      if (target.closest(INTERACTIVE)) {
        return;
      }

      const item = resolve(target, event.currentTarget);

      if (!item) {
        return;
      }

      stopDrag.current?.();
      suppressClick.current = false;
      drag.current = { index: item.index, selected: !item.selected };

      const preventTextSelection = (selectEvent: Event) => {
        selectEvent.preventDefault();
      };

      const stop = () => {
        drag.current = null;
        stopDrag.current = null;
        window.removeEventListener("pointerup", stop);
        window.removeEventListener("pointercancel", stop);
        window.removeEventListener("blur", stop);
        document.removeEventListener("selectstart", preventTextSelection);
        // The click that follows pointerup fires after this; release the guard once it has.
        window.setTimeout(() => {
          suppressClick.current = false;
        }, 0);
      };

      window.addEventListener("pointerup", stop);
      window.addEventListener("pointercancel", stop);
      window.addEventListener("blur", stop);
      document.addEventListener("selectstart", preventTextSelection);
      stopDrag.current = stop;
    },
    onPointerOver(event: PointerEvent<HTMLElement>) {
      const { current } = drag;

      if (!current || !(event.buttons & 1) || !(event.target instanceof Element)) {
        return;
      }

      const item = resolve(event.target, event.currentTarget);

      if (!item || item.index === current.index) {
        return;
      }

      // Let clicks that `selectRange` dispatches through.
      suppressClick.current = false;
      selectRange(
        Math.min(current.index, item.index),
        Math.max(current.index, item.index),
        current.selected,
        event.currentTarget,
      );
      current.index = item.index;
      // The drag already toggled the item it started on; swallow the click released over it.
      suppressClick.current = true;
    },
  };
};

import * as React from "react";
import { functionalUpdate } from "@tanstack/react-table";
import type { ColumnFiltersState, OnChangeFn, Updater } from "@tanstack/react-table";
import {
  createFilters,
  hasFilterConfig,
  isFilterRule,
  isNumber,
  matchesRule,
} from "@/registry/erbium/lib/filter-rules";
import type { FilterCell, FilterFieldConfig, FilterSource, Filters } from "@/registry/erbium/lib/filter-rules";
import { parseFilterSearch, toFilterSearch } from "@/registry/erbium/lib/filter-search";
import type { FilterSearch, FilterSearchFields, SearchParams } from "@/registry/erbium/lib/filter-search";

/*
 * Adapters from a data source to the `Filters` the filter components read. A TanStack table keeps
 * the rules in its own `columnFilters` state and filters its rows itself; a plain list keeps the
 * rules here and filters its items with the same matcher.
 */

/** The parts of a filterable column the adapter reads; any column with `columnFilteringFeature` has them. */
interface FilterableColumn {
  id: string;
  columnDef: { meta?: unknown };
  getCanFilter: () => boolean;
  getFacetedUniqueValues?: () => Map<FilterCell, number>;
  getFacetedMinMaxValues?: () => undefined | [number, number];
}

/** The parts of a table the adapter reads and changes. */
interface FilterableTable {
  atoms: { columnFilters?: { get: () => ColumnFiltersState } };
  getAllLeafColumns: () => FilterableColumn[];
  setColumnFilters: (updater: Updater<ColumnFiltersState>) => void;
}

interface TableFiltersOptions {
  /**
   * Option counts by column id. Pass them when the server filters the rows: the table holds one
   * page, so counts it derives would describe that page rather than every row.
   */
  counts?: Partial<Record<string, Map<string, number>>>;
}

const noFilters: ColumnFiltersState = [];

/**
 * Filters for a TanStack table. Columns opt in with `filterColumn(…)`, or with a `meta.filter`
 * config and `filterFn: filterFn_rule`. Rules live in the table's `columnFilters` state; call
 * this where `useTable` is called, so the filters re-render with the table.
 *
 * Register `columnFacetingFeature` with `facetedUniqueValues` and `facetedMinMaxValues` for option
 * counts and number ranges that follow the other active filters.
 */
const useTableFilters = (table: FilterableTable, { counts }: TableFiltersOptions = {}): Filters => {
  const sources = table.getAllLeafColumns().flatMap((column): FilterSource[] => {
    const { meta } = column.columnDef;

    if (!hasFilterConfig(meta) || !column.getCanFilter()) {
      return [];
    }

    const config = meta.filter;
    const serverCounts = counts?.[column.id];

    return [
      {
        config,
        facets:
          serverCounts === undefined ? column.getFacetedUniqueValues?.() : new Map(serverCounts),
        id: column.id,
        range: config.type === "number" ? column.getFacetedMinMaxValues?.() : undefined,
      },
    ];
  });

  return createFilters(sources, table.atoms.columnFilters?.get() ?? noFilters, (updater) => {
    table.setColumnFilters(updater);
  });
};

/** A list field: a filter config plus how to read the field from an item. */
interface ListFilterField<TItem> extends FilterFieldConfig {
  /** Reads the field's value from an item, such as `(task) => task.status`. */
  value: (item: TItem) => FilterCell;
}

interface ListFiltersOptions<TItem> {
  items: readonly TItem[];
  /** The filterable fields by id. Keep the object stable (a module constant or a memo). */
  fields: Record<string, ListFilterField<TItem>>;
  /** The rules, when the caller owns them, such as rules kept in the URL. */
  columnFilters?: ColumnFiltersState;
  onColumnFiltersChange?: OnChangeFn<ColumnFiltersState>;
  defaultColumnFilters?: ColumnFiltersState;
}

const widen = (range: [number, number] | undefined, value: number): [number, number] =>
  range === undefined ? [value, value] : [Math.min(range[0], value), Math.max(range[1], value)];

/**
 * Filters for a plain list. Returns the `filters` to give the filter components and the `items`
 * that pass them. Option counts and number ranges follow the other active filters, as a table's
 * facets do.
 */
const useListFilters = <TItem>({
  items,
  fields,
  columnFilters,
  onColumnFiltersChange,
  defaultColumnFilters = noFilters,
}: ListFiltersOptions<TItem>): { filters: Filters; items: TItem[] } => {
  const [ownFilters, setOwnFilters] = React.useState(defaultColumnFilters);
  const state = columnFilters ?? ownFilters;

  const setState = React.useCallback(
    (updater: Updater<ColumnFiltersState>) => {
      if (onColumnFiltersChange === undefined) {
        setOwnFilters(updater);
      } else {
        onColumnFiltersChange(updater);
      }
    },
    [onColumnFiltersChange],
  );

  return React.useMemo(() => {
    const entries = Object.entries(fields);

    const rules = state.flatMap((filter) =>
      isFilterRule(filter.value) && filter.id in fields
        ? [{ id: filter.id, rule: filter.value }]
        : [],
    );

    // Each item's field values, read once.
    const rows = items.map((item) => ({
      cells: new Map(entries.map(([id, field]) => [id, field.value(item)])),
      item,
    }));

    const passes = (cells: Map<string, FilterCell>, except?: string) =>
      rules.every(({ id, rule }) => id === except || matchesRule(cells.get(id), rule));

    const sources = entries.map(([id, config]): FilterSource => {
      const facets = new Map<FilterCell, number>();
      let range: [number, number] | undefined;

      for (const { cells } of rows) {
        const cell = cells.get(id);

        if (passes(cells, id) && cell !== null && cell !== undefined) {
          facets.set(cell, (facets.get(cell) ?? 0) + 1);
          range = isNumber(cell) ? widen(range, cell) : range;
        }
      }

      return { config, facets, id, range: config.type === "number" ? range : undefined };
    });

    return {
      filters: createFilters(sources, state, setState),
      items: rows.filter(({ cells }) => passes(cells)).map(({ item }) => item),
    };
  }, [items, fields, state, setState]);
};

interface FilterSearchOptions<TKey extends string> {
  /** The current search params, such as TanStack Router's `Route.useSearch()`. */
  search: SearchParams<TKey>;
  /** The fields kept in the URL: `getColumnFilterFields(columns)` for a table, the fields of a list. */
  fields: FilterSearchFields<TKey>;
  /**
   * Writes the filter params after a change. Merge them into the current search, replacing the
   * history entry so each keystroke is not a step back:
   * `navigate({ search: (prev) => ({ ...prev, ...next }), replace: true })`.
   */
  onSearchChange: (next: FilterSearch<TKey>) => void;
}

/**
 * Keeps column filters in the URL, so a filtered view is a link. Returns `columnFilters` and
 * `onColumnFiltersChange` to pass to `useTable` (in `state` and as the change handler) or to spread
 * into `useListFilters`. The search params are the only copy of the rules; the router owns them.
 */
const useFilterSearch = <TKey extends string>({
  search,
  fields,
  onSearchChange,
}: FilterSearchOptions<TKey>) => {
  const columnFilters = React.useMemo(() => parseFilterSearch(search, fields), [search, fields]);
  // Updates made before the router re-renders build on each other, not on stale search.
  const pending = React.useRef<{ from: ColumnFiltersState; next: ColumnFiltersState }>(undefined);

  const onColumnFiltersChange: OnChangeFn<ColumnFiltersState> = (updater) => {
    const last = pending.current?.from === columnFilters ? pending.current.next : columnFilters;
    const next = functionalUpdate(updater, last);

    pending.current = { from: columnFilters, next };
    onSearchChange(toFilterSearch(next, fields));
  };

  return { columnFilters, onColumnFiltersChange };
};

export { useFilterSearch, useListFilters, useTableFilters };

export type {
  FilterableColumn,
  FilterableTable,
  FilterSearchOptions,
  ListFilterField,
  ListFiltersOptions,
  TableFiltersOptions,
};

import { useMediaQuery } from "@base-ui/react/unstable-use-media-query";

/** Below Tailwind's `md:`, the shadcn mobile breakpoint, so a viewport is never both mobile and `md`. */
const MOBILE_QUERY = "(width < 48rem)";

/**
 * Whether the viewport is mobile-sized. Built on Base UI's media query hook, so it follows
 * viewport changes through the `matchMedia` change event and never renders an unresolved value.
 * It is `false` on the server; pass `{ defaultMatches: true }` to change that, or
 * `{ noSsr: true }` in client-only apps to resolve on the first render.
 */
const useIsMobile = (options: useMediaQuery.Options = {}) => useMediaQuery(MOBILE_QUERY, options);

export { MOBILE_QUERY, useIsMobile };

import { useMemo } from "react";

interface PaginationOptions {
  /** The current page, starting at 1. Values outside `1..pageCount` are clamped. */
  page: number;
  /** The number of pages. Zero or less renders a single page. */
  pageCount: number;
  /**
   * Pages shown on each side of the current page.
   * @default 1
   */
  siblingCount?: number;
  /**
   * Pages always shown at the start and the end.
   * @default 1
   */
  boundaryCount?: number;
}

type PaginationItem =
  | { type: "page"; page: number; current: boolean }
  | { type: "ellipsis"; key: "start-ellipsis" | "end-ellipsis" };

interface Pagination {
  /** The clamped current page. */
  page: number;
  /** At least 1. */
  pageCount: number;
  /** Pages and gaps to render, in order. */
  items: PaginationItem[];
  /** The previous page, or `undefined` on the first page. */
  previousPage: number | undefined;
  /** The next page, or `undefined` on the last page. */
  nextPage: number | undefined;
}

const range = (start: number, end: number) =>
  Array.from({ length: Math.max(end - start + 1, 0) }, (_, index) => start + index);

const toPage = (page: number, current: number): PaginationItem => ({
  current: page === current,
  page,
  type: "page",
});

/**
 * Lays out the pages of a paginated view. The item count stays constant as the current
 * page moves, so the control does not shift under the pointer: boundary pages, sibling
 * pages around the current one, and an ellipsis for each gap of two or more pages. A gap of
 * exactly one page shows that page instead of an ellipsis.
 */
const getPagination = ({
  page,
  pageCount,
  siblingCount = 1,
  boundaryCount = 1,
}: PaginationOptions): Pagination => {
  const count = Math.max(1, Math.floor(pageCount));
  const current = Math.min(Math.max(1, Math.floor(page)), count);
  const siblings = Math.max(0, Math.floor(siblingCount));
  const boundaries = Math.max(0, Math.floor(boundaryCount));

  const startPages = range(1, Math.min(boundaries, count));
  const endPages = range(Math.max(count - boundaries + 1, boundaries + 1), count);

  // The sibling window keeps its full width near either end.
  const siblingsStart = Math.max(
    Math.min(current - siblings, count - boundaries - siblings * 2 - 1),
    boundaries + 2,
  );

  const siblingsEnd = Math.min(
    Math.max(current + siblings, boundaries + siblings * 2 + 2),
    count - boundaries - 1,
  );

  // Small page counts can reach a page twice; keep the first of each.
  const seen = new Set<number>();
  const items: PaginationItem[] = [];

  const addPages = (entries: number[]) => {
    for (const entry of entries) {
      if (entry >= 1 && entry <= count && !seen.has(entry)) {
        seen.add(entry);
        items.push(toPage(entry, current));
      }
    }
  };

  addPages(startPages);

  if (siblingsStart > boundaries + 2) {
    items.push({ key: "start-ellipsis", type: "ellipsis" });
  } else if (boundaries + 1 < count - boundaries) {
    addPages([boundaries + 1]);
  }

  addPages(range(siblingsStart, siblingsEnd));

  if (siblingsEnd < count - boundaries - 1) {
    items.push({ key: "end-ellipsis", type: "ellipsis" });
  } else if (count - boundaries > boundaries) {
    addPages([count - boundaries]);
  }

  addPages(endPages);

  return {
    items,
    nextPage: current < count ? current + 1 : undefined,
    page: current,
    pageCount: count,
    previousPage: current > 1 ? current - 1 : undefined,
  };
};

/** Lays out the pages of a paginated view; see `getPagination`. */
const usePagination = ({ page, pageCount, siblingCount, boundaryCount }: PaginationOptions) =>
  useMemo(
    () => getPagination({ boundaryCount, page, pageCount, siblingCount }),
    [boundaryCount, page, pageCount, siblingCount],
  );

export { getPagination, usePagination };

export type { Pagination, PaginationItem, PaginationOptions };

import { ForesightManager, useForesight } from "@foresightjs/react";
import type { HitSlop } from "@foresightjs/react";

// Foresight mirrors its state onto `data-active`, `data-predicted`, and `data-status` by
// default. Base UI parts style themselves through `data-active` and `data-status`, so the
// attributes stay off for every element the library registers. The manager is a client
// singleton; registration happens in effects, so the server never creates it.
if (typeof window !== "undefined") {
  ForesightManager.instance.alterGlobalSettings({ setDataAttributes: false });
}

interface PredictedIntentOptions {
  /**
   * Whether the element takes part in prediction. A disabled element stays registered and
   * never fires.
   * @default true
   */
  enabled?: boolean;
  /**
   * Extra distance around the element that counts as a hit, in pixels or per side.
   * @default 0
   */
  hitSlop?: HitSlop;
  /** A label for Foresight's development tools. */
  name?: string;
  /**
   * Milliseconds before a fired element can fire again. Match it to how long the work it
   * starts stays fresh.
   * @default Infinity
   */
  reactivateAfter?: number;
}

/**
 * Calls `onIntent` when the user is about to interact with an element: the cursor is heading
 * for it, it is a tab stop or two away, scrolling is bringing it under the cursor, or a
 * finger touches it. Use it to start work a click would otherwise wait for, such as loading
 * data, a lazy component, or an image. Prediction stays off on slow connections and with
 * Save-Data.
 *
 * Returns a callback ref for the element. The latest `onIntent` and options are read when
 * prediction fires, so neither needs to be memoized.
 */
const usePredictedIntent = (
  onIntent: () => void,
  { enabled = true, hitSlop, name, reactivateAfter }: PredictedIntentOptions = {},
) => {
  const { elementRef } = useForesight({
    callback: onIntent,
    enabled,
    hitSlop,
    name,
    reactivateAfter,
  });

  return elementRef;
};

export { usePredictedIntent };

export type { PredictedIntentOptions };

import { useRouterState } from "@tanstack/react-router";

/**
 * True while TanStack Router resolves a navigation: matching, `beforeLoad`,
 * loaders and lazy route chunks. Preloads do not count. Pass it to a loading
 * indicator such as `LogoLoader`'s `loading` prop.
 */
const useRouterPending = () => useRouterState({ select: (state) => state.status === "pending" });

export { useRouterPending };

import { createCn } from "cn/config";
import type { CSSProperties } from "react";

const anySurfaceColor = () => true;

/**
 * Surface roles are registered as one class group so `cn` keeps only the last
 * role: `cn("surface-control", "surface-fill-primary")` yields the fill.
 */
export const cn = createCn({
  extend: {
    classGroups: {
      "control-geometry": ["control-size", "control-size-sm", "control-size-xs", "control-size-lg"],
      "font-size": [
        {
          text: [
            "control",
            "control-sm",
            "metadata",
            "code-block",
            "inline-code",
            "field",
            "editable",
            "display",
            "title",
            "subtitle",
            "body",
            "caption",
          ],
        },
      ],
      // Motion tokens from theme.css, so a later `duration-*` or `ease-*` replaces an earlier one.
      duration: [{ duration: ["ui-fast", "ui", "ui-slow", "panel", "drawer"] }],
      ease: [{ ease: ["ui-out", "ui-move", "ui-drawer"] }],
      gap: [{ gap: ["related", "group", "section", "control-gap"] }],
      p: [{ p: ["panel", "panel-sm"] }],
      px: [{ px: ["panel", "related", "control-inset"] }],
      py: [{ py: ["panel", "related", "control-gap"] }],
      surface: [
        {
          "control-geometry": [
            "control-size",
            "control-size-sm",
            "control-size-xs",
            "control-size-lg",
          ],
          surface: [
            "panel",
            "control",
            "field",
            "overlay",
            "modal",
            "flat",
            "frame",
            "well",
            "knob",
            {
              fill: [anySurfaceColor],
              ghost: [anySurfaceColor],
              tag: [anySurfaceColor],
              tint: [anySurfaceColor],
            },
          ],
        },
      ],
    },
  },
});

/** CSS custom properties keyed by name, e.g. `{ "--ratio": 1.5 }`. */
export type CSSVariables<Value = string | number> = Partial<
  Record<`--${string}`, Value | undefined>
>;

/**
 * Inline `style` that also accepts CSS custom properties. React's `CSSProperties`
 * omits them, and this type is assignable to it, so annotating a constant replaces
 * an `as CSSProperties` cast. Annotate a constant rather than using `satisfies`:
 * an inline literal still fails React's excess-property check.
 */
export type CSSVariableStyle = CSSProperties & CSSVariables;
